const List<String> layoutMadina15Pages6 = <String>[
  '26;51;1;\nT;0;46:29:1:وَإِذۡ صَرَفۡنَآ إِلَيۡكَ نَفَرࣰا مِّنَ ٱلۡجِنِّ يَسۡتَمِعُونَ ٱلۡقُرۡءَانَ\nT;0;46:29:0:فَلَمَّا حَضَرُوهُ قَالُوٓاْ أَنصِتُواْۖ فَلَمَّا قُضِيَ وَلَّوۡاْ إِلَىٰ قَوۡمِهِم\nT;0;46:29:2:مُّنذِرِينَ¦46:30:1:قَالُواْ يَٰقَوۡمَنَآ إِنَّا سَمِعۡنَا كِتَٰبًا أُنزِلَ مِنۢ\nT;0;46:30:0:بَعۡدِ مُوسَىٰ مُصَدِّقࣰا لِّمَا بَيۡنَ يَدَيۡهِ يَهۡدِيٓ إِلَى ٱلۡحَقِّ\nT;0;46:30:2:وَإِلَىٰ طَرِيقࣲ مُّسۡتَقِيمࣲ¦46:31:1:يَٰقَوۡمَنَآ أَجِيبُواْ دَاعِيَ ٱللَّهِ وَءَامِنُواْ\nT;0;46:31:2:بِهِۦ يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُجِرۡكُم مِّنۡ عَذَابٍ أَلِيمࣲ\nT;0;46:32:1:وَمَن لَّا يُجِبۡ دَاعِيَ ٱللَّهِ فَلَيۡسَ بِمُعۡجِزࣲ فِي ٱلۡأَرۡضِ وَلَيۡسَ لَهُۥ\nT;0;46:32:2:مِن دُونِهِۦٓ أَوۡلِيَآءُۚ أُوْلَٰٓئِكَ فِي ضَلَٰلࣲ مُّبِينٍ¦46:33:1:أَوَلَمۡ يَرَوۡاْ\nT;0;46:33:0:أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَلَمۡ يَعۡيَ بِخَلۡقِهِنَّ\nT;0;46:33:2:بِقَٰدِرٍ عَلَىٰٓ أَن يُحۡـِۧيَ ٱلۡمَوۡتَىٰۚ بَلَىٰٓۚ إِنَّهُۥ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ\nT;0;46:34:1:وَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَلَيۡسَ هَٰذَا بِٱلۡحَقِّۖ قَالُواْ\nT;0;46:34:2:بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ\nT;0;46:35:1:فَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل\nT;0;46:35:0:لَّهُمۡۚ كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَ مَا يُوعَدُونَ لَمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةࣰ\nT;2;46:35:2:مِّن نَّهَارِۭۚ بَلَٰغࣱۚ فَهَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلۡفَٰسِقُونَ',
  '26;51;1;203\nH;47\nB;47\nT;0;47:1:3:ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعۡمَٰلَهُمۡ¦47:2:1:وَٱلَّذِينَ ءَامَنُواْ\nT;0;47:2:0:وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَءَامَنُواْ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدࣲ وَهُوَ ٱلۡحَقُّ مِن رَّبِّهِمۡ كَفَّرَ\nT;0;47:2:2:عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَأَصۡلَحَ بَالَهُمۡ¦47:3:1:ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُواْ ٱتَّبَعُواْ ٱلۡبَٰطِلَ وَأَنَّ\nT;0;47:3:2:ٱلَّذِينَ ءَامَنُواْ ٱتَّبَعُواْ ٱلۡحَقَّ مِن رَّبِّهِمۡۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ لِلنَّاسِ أَمۡثَٰلَهُمۡ\nT;0;47:4:1:فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ فَضَرۡبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثۡخَنتُمُوهُمۡ فَشُدُّواْ ٱلۡوَثَاقَ فَإِمَّا\nT;0;47:4:0:مَنَّۢا بَعۡدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَاۚ ذَٰلِكَۖ وَلَوۡ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ\nT;0;47:4:0:مِنۡهُمۡ وَلَٰكِن لِّيَبۡلُوَاْ بَعۡضَكُم بِبَعۡضࣲۗ وَٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ\nT;0;47:4:2:أَعۡمَٰلَهُمۡ¦47:5:3:سَيَهۡدِيهِمۡ وَيُصۡلِحُ بَالَهُمۡ¦47:6:3:وَيُدۡخِلُهُمُ ٱلۡجَنَّةَ عَرَّفَهَا لَهُمۡ\nT;0;47:7:3:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَنصُرُواْ ٱللَّهَ يَنصُرۡكُمۡ وَيُثَبِّتۡ أَقۡدَامَكُمۡ\nT;0;47:8:3:وَٱلَّذِينَ كَفَرُواْ فَتَعۡسࣰا لَّهُمۡ وَأَضَلَّ أَعۡمَٰلَهُمۡ¦47:9:1:ذَٰلِكَ بِأَنَّهُمۡ كَرِهُواْ\nT;0;47:9:2:مَآ أَنزَلَ ٱللَّهُ فَأَحۡبَطَ أَعۡمَٰلَهُمۡ¦47:10:1:۞ أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ\nT;0;47:10:2:كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ دَمَّرَ ٱللَّهُ عَلَيۡهِمۡۖ وَلِلۡكَٰفِرِينَ أَمۡثَٰلُهَا\nT;0;47:11:3:ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوۡلَى ٱلَّذِينَ ءَامَنُواْ وَأَنَّ ٱلۡكَٰفِرِينَ لَا مَوۡلَىٰ لَهُمۡ',
  '26;51;2;\nT;0;47:12:1:إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتࣲ تَجۡرِي مِن\nT;0;47:12:0:تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَٱلَّذِينَ كَفَرُواْ يَتَمَتَّعُونَ وَيَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَٰمُ\nT;0;47:12:2:وَٱلنَّارُ مَثۡوࣰى لَّهُمۡ¦47:13:1:وَكَأَيِّن مِّن قَرۡيَةٍ هِيَ أَشَدُّ قُوَّةࣰ مِّن قَرۡيَتِكَ\nT;0;47:13:2:ٱلَّتِيٓ أَخۡرَجَتۡكَ أَهۡلَكۡنَٰهُمۡ فَلَا نَاصِرَ لَهُمۡ¦47:14:1:أَفَمَن كَانَ عَلَىٰ بَيِّنَةࣲ مِّن\nT;0;47:14:2:رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُم¦47:15:1:مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي\nT;0;47:15:0:وُعِدَ ٱلۡمُتَّقُونَۖ فِيهَآ أَنۡهَٰرࣱ مِّن مَّآءٍ غَيۡرِ ءَاسِنࣲ وَأَنۡهَٰرࣱ مِّن لَّبَنࣲ لَّمۡ يَتَغَيَّرۡ\nT;0;47:15:0:طَعۡمُهُۥ وَأَنۡهَٰرࣱ مِّنۡ خَمۡرࣲ لَّذَّةࣲ لِّلشَّٰرِبِينَ وَأَنۡهَٰرࣱ مِّنۡ عَسَلࣲ مُّصَفࣰّىۖ وَلَهُمۡ\nT;0;47:15:0:فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغۡفِرَةࣱ مِّن رَّبِّهِمۡۖ كَمَنۡ هُوَ خَٰلِدࣱ فِي ٱلنَّارِ وَسُقُواْ\nT;0;47:15:2:مَآءً حَمِيمࣰا فَقَطَّعَ أَمۡعَآءَهُمۡ¦47:16:1:وَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَ حَتَّىٰٓ إِذَا\nT;0;47:16:0:خَرَجُواْ مِنۡ عِندِكَ قَالُواْ لِلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مَاذَا قَالَ ءَانِفًاۚ أُوْلَٰٓئِكَ\nT;0;47:16:2:ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡ¦47:17:1:وَٱلَّذِينَ ٱهۡتَدَوۡاْ\nT;0;47:17:2:زَادَهُمۡ هُدࣰى وَءَاتَىٰهُمۡ تَقۡوَىٰهُمۡ¦47:18:1:فَهَلۡ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ\nT;0;47:18:0:أَن تَأۡتِيَهُم بَغۡتَةࣰۖ فَقَدۡ جَآءَ أَشۡرَاطُهَاۚ فَأَنَّىٰ لَهُمۡ إِذَا جَآءَتۡهُمۡ\nT;0;47:18:2:ذِكۡرَىٰهُمۡ¦47:19:1:فَٱعۡلَمۡ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ\nT;0;47:19:2:وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَٱللَّهُ يَعۡلَمُ مُتَقَلَّبَكُمۡ وَمَثۡوَىٰكُمۡ',
  '26;51;2;\nT;0;47:20:1:وَيَقُولُ ٱلَّذِينَ ءَامَنُواْ لَوۡلَا نُزِّلَتۡ سُورَةࣱۖ فَإِذَآ أُنزِلَتۡ سُورَةࣱ\nT;0;47:20:0:مُّحۡكَمَةࣱ وَذُكِرَ فِيهَا ٱلۡقِتَالُ رَأَيۡتَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضࣱ\nT;0;47:20:2:يَنظُرُونَ إِلَيۡكَ نَظَرَ ٱلۡمَغۡشِيِّ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ فَأَوۡلَىٰ لَهُمۡ\nT;0;47:21:1:طَاعَةࣱ وَقَوۡلࣱ مَّعۡرُوفࣱۚ فَإِذَا عَزَمَ ٱلۡأَمۡرُ فَلَوۡ صَدَقُواْ ٱللَّهَ\nT;0;47:21:2:لَكَانَ خَيۡرࣰا لَّهُمۡ¦47:22:1:فَهَلۡ عَسَيۡتُمۡ إِن تَوَلَّيۡتُمۡ أَن تُفۡسِدُواْ\nT;0;47:22:2:فِي ٱلۡأَرۡضِ وَتُقَطِّعُوٓاْ أَرۡحَامَكُمۡ¦47:23:1:أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ\nT;0;47:23:2:ٱللَّهُ فَأَصَمَّهُمۡ وَأَعۡمَىٰٓ أَبۡصَٰرَهُمۡ¦47:24:1:أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَ\nT;0;47:24:2:أَمۡ عَلَىٰ قُلُوبٍ أَقۡفَالُهَآ¦47:25:1:إِنَّ ٱلَّذِينَ ٱرۡتَدُّواْ عَلَىٰٓ أَدۡبَٰرِهِم\nT;0;47:25:0:مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡهُدَى ٱلشَّيۡطَٰنُ سَوَّلَ لَهُمۡ وَأَمۡلَىٰ\nT;0;47:25:2:لَهُمۡ¦47:26:1:ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لِلَّذِينَ كَرِهُواْ مَا نَزَّلَ ٱللَّهُ\nT;0;47:26:2:سَنُطِيعُكُمۡ فِي بَعۡضِ ٱلۡأَمۡرِۖ وَٱللَّهُ يَعۡلَمُ إِسۡرَارَهُمۡ\nT;0;47:27:1:فَكَيۡفَ إِذَا تَوَفَّتۡهُمُ ٱلۡمَلَٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ\nT;0;47:27:2:وَأَدۡبَٰرَهُمۡ¦47:28:1:ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُواْ مَآ أَسۡخَطَ ٱللَّهَ\nT;0;47:28:2:وَكَرِهُواْ رِضۡوَٰنَهُۥ فَأَحۡبَطَ أَعۡمَٰلَهُمۡ¦47:29:1:أَمۡ حَسِبَ\nT;0;47:29:2:ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٌ أَن لَّن يُخۡرِجَ ٱللَّهُ أَضۡغَٰنَهُمۡ',
  '26;51;2;204\nT;0;47:30:1:وَلَوۡ نَشَآءُ لَأَرَيۡنَٰكَهُمۡ فَلَعَرَفۡتَهُم بِسِيمَٰهُمۡۚ وَلَتَعۡرِفَنَّهُمۡ فِي\nT;0;47:30:2:لَحۡنِ ٱلۡقَوۡلِۚ وَٱللَّهُ يَعۡلَمُ أَعۡمَٰلَكُمۡ¦47:31:1:وَلَنَبۡلُوَنَّكُمۡ حَتَّىٰ نَعۡلَمَ\nT;0;47:31:2:ٱلۡمُجَٰهِدِينَ مِنكُمۡ وَٱلصَّٰبِرِينَ وَنَبۡلُوَاْ أَخۡبَارَكُمۡ¦47:32:1:إِنَّ ٱلَّذِينَ\nT;0;47:32:0:كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ وَشَآقُّواْ ٱلرَّسُولَ مِنۢ بَعۡدِ\nT;0;47:32:0:مَا تَبَيَّنَ لَهُمُ ٱلۡهُدَىٰ لَن يَضُرُّواْ ٱللَّهَ شَيۡـࣰٔا وَسَيُحۡبِطُ\nT;0;47:32:2:أَعۡمَٰلَهُمۡ¦47:33:1:۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ\nT;0;47:33:2:وَلَا تُبۡطِلُوٓاْ أَعۡمَٰلَكُمۡ¦47:34:1:إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ\nT;0;47:34:2:ٱللَّهِ ثُمَّ مَاتُواْ وَهُمۡ كُفَّارࣱ فَلَن يَغۡفِرَ ٱللَّهُ لَهُمۡ¦47:35:1:فَلَا تَهِنُواْ\nT;0;47:35:0:وَتَدۡعُوٓاْ إِلَى ٱلسَّلۡمِ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ وَٱللَّهُ مَعَكُمۡ وَلَن يَتِرَكُمۡ\nT;0;47:35:2:أَعۡمَٰلَكُمۡ¦47:36:1:إِنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبࣱ وَلَهۡوࣱۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ\nT;0;47:36:2:يُؤۡتِكُمۡ أُجُورَكُمۡ وَلَا يَسۡـَٔلۡكُمۡ أَمۡوَٰلَكُمۡ¦47:37:1:إِن يَسۡـَٔلۡكُمُوهَا\nT;0;47:37:2:فَيُحۡفِكُمۡ تَبۡخَلُواْ وَيُخۡرِجۡ أَضۡغَٰنَكُمۡ¦47:38:1:هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ\nT;0;47:38:0:تُدۡعَوۡنَ لِتُنفِقُواْ فِي سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبۡخَلُۖ وَمَن يَبۡخَلۡ\nT;0;47:38:0:فَإِنَّمَا يَبۡخَلُ عَن نَّفۡسِهِۦۚ وَٱللَّهُ ٱلۡغَنِيُّ وَأَنتُمُ ٱلۡفُقَرَآءُۚ وَإِن\nT;2;47:38:2:تَتَوَلَّوۡاْ يَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ ثُمَّ لَا يَكُونُوٓاْ أَمۡثَٰلَكُم',
  '26;51;3;\nH;48\nB;48\nT;0;48:1:3:إِنَّا فَتَحۡنَا لَكَ فَتۡحࣰا مُّبِينࣰا¦48:2:1:لِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ\nT;0;48:2:2:وَمَا تَأَخَّرَ وَيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكَ وَيَهۡدِيَكَ صِرَٰطࣰا مُّسۡتَقِيمࣰا\nT;0;48:3:3:وَيَنصُرَكَ ٱللَّهُ نَصۡرًا عَزِيزًا¦48:4:1:هُوَ ٱلَّذِيٓ أَنزَلَ ٱلسَّكِينَةَ فِي قُلُوبِ\nT;0;48:4:0:ٱلۡمُؤۡمِنِينَ لِيَزۡدَادُوٓاْ إِيمَٰنࣰا مَّعَ إِيمَٰنِهِمۡۗ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ\nT;0;48:4:2:وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمࣰا¦48:5:1:لِّيُدۡخِلَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ\nT;0;48:5:0:جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنۡهُمۡ\nT;0;48:5:2:سَيِّـَٔاتِهِمۡۚ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوۡزًا عَظِيمࣰا¦48:6:1:وَيُعَذِّبَ\nT;0;48:6:0:ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ ٱلظَّآنِّينَ\nT;0;48:6:0:بِٱللَّهِ ظَنَّ ٱلسَّوۡءِۚ عَلَيۡهِمۡ دَآئِرَةُ ٱلسَّوۡءِۖ وَغَضِبَ ٱللَّهُ عَلَيۡهِمۡ\nT;0;48:6:2:وَلَعَنَهُمۡ وَأَعَدَّ لَهُمۡ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرࣰا¦48:7:1:وَلِلَّهِ جُنُودُ\nT;0;48:7:2:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا¦48:8:1:إِنَّآ\nT;0;48:8:2:أَرۡسَلۡنَٰكَ شَٰهِدࣰا وَمُبَشِّرࣰا وَنَذِيرࣰا¦48:9:1:لِّتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦ\nT;0;48:9:2:وَتُعَزِّرُوهُ وَتُوَقِّرُوهُۚ وَتُسَبِّحُوهُ بُكۡرَةࣰ وَأَصِيلًا',
  '26;51;3;\nT;0;48:10:1:إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوۡقَ\nT;0;48:10:0:أَيۡدِيهِمۡۚ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفۡسِهِۦۖ وَمَنۡ أَوۡفَىٰ\nT;0;48:10:2:بِمَا عَٰهَدَ عَلَيۡهُ ٱللَّهَ فَسَيُؤۡتِيهِ أَجۡرًا عَظِيمࣰا¦48:11:1:سَيَقُولُ\nT;0;48:11:0:لَكَ ٱلۡمُخَلَّفُونَ مِنَ ٱلۡأَعۡرَابِ شَغَلَتۡنَآ أَمۡوَٰلُنَا وَأَهۡلُونَا\nT;0;48:11:0:فَٱسۡتَغۡفِرۡ لَنَاۚ يَقُولُونَ بِأَلۡسِنَتِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ قُلۡ\nT;0;48:11:0:فَمَن يَمۡلِكُ لَكُم مِّنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ بِكُمۡ ضَرًّا أَوۡ أَرَادَ بِكُمۡ\nT;0;48:11:2:نَفۡعَۢاۚ بَلۡ كَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرَۢا¦48:12:1:بَلۡ ظَنَنتُمۡ أَن لَّن\nT;0;48:12:0:يَنقَلِبَ ٱلرَّسُولُ وَٱلۡمُؤۡمِنُونَ إِلَىٰٓ أَهۡلِيهِمۡ أَبَدࣰا وَزُيِّنَ ذَٰلِكَ فِي\nT;0;48:12:2:قُلُوبِكُمۡ وَظَنَنتُمۡ ظَنَّ ٱلسَّوۡءِ وَكُنتُمۡ قَوۡمَۢا بُورࣰا¦48:13:1:وَمَن لَّمۡ يُؤۡمِنۢ\nT;0;48:13:2:بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَعِيرࣰا¦48:14:1:وَلِلَّهِ مُلۡكُ\nT;0;48:14:0:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ\nT;0;48:14:2:وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِيمࣰا¦48:15:1:سَيَقُولُ ٱلۡمُخَلَّفُونَ إِذَا\nT;0;48:15:0:ٱنطَلَقۡتُمۡ إِلَىٰ مَغَانِمَ لِتَأۡخُذُوهَا ذَرُونَا نَتَّبِعۡكُمۡۖ يُرِيدُونَ\nT;0;48:15:0:أَن يُبَدِّلُواْ كَلَٰمَ ٱللَّهِۚ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمۡ قَالَ ٱللَّهُ مِن قَبۡلُۖ\nT;0;48:15:2:فَسَيَقُولُونَ بَلۡ تَحۡسُدُونَنَاۚ بَلۡ كَانُواْ لَا يَفۡقَهُونَ إِلَّا قَلِيلࣰا',
  '26;51;3;205\nT;0;48:16:1:قُل لِّلۡمُخَلَّفِينَ مِنَ ٱلۡأَعۡرَابِ سَتُدۡعَوۡنَ إِلَىٰ قَوۡمٍ أُوْلِي بَأۡسࣲ شَدِيدࣲ\nT;0;48:16:0:تُقَٰتِلُونَهُمۡ أَوۡ يُسۡلِمُونَۖ فَإِن تُطِيعُواْ يُؤۡتِكُمُ ٱللَّهُ أَجۡرًا حَسَنࣰاۖ\nT;0;48:16:2:وَإِن تَتَوَلَّوۡاْ كَمَا تَوَلَّيۡتُم مِّن قَبۡلُ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمࣰا¦48:17:1:لَّيۡسَ\nT;0;48:17:0:عَلَى ٱلۡأَعۡمَىٰ حَرَجࣱ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجࣱ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجࣱۗ\nT;0;48:17:0:وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا\nT;0;48:17:2:ٱلۡأَنۡهَٰرُۖ وَمَن يَتَوَلَّ يُعَذِّبۡهُ عَذَابًا أَلِيمࣰا¦48:18:1:۞ لَّقَدۡ رَضِيَ ٱللَّهُ\nT;0;48:18:0:عَنِ ٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِي\nT;0;48:18:2:قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيۡهِمۡ وَأَثَٰبَهُمۡ فَتۡحࣰا قَرِيبࣰا¦48:19:1:وَمَغَانِمَ\nT;0;48:19:2:كَثِيرَةࣰ يَأۡخُذُونَهَاۗ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمࣰا¦48:20:1:وَعَدَكُمُ ٱللَّهُ\nT;0;48:20:0:مَغَانِمَ كَثِيرَةࣰ تَأۡخُذُونَهَا فَعَجَّلَ لَكُمۡ هَٰذِهِۦ وَكَفَّ أَيۡدِيَ\nT;0;48:20:0:ٱلنَّاسِ عَنكُمۡ وَلِتَكُونَ ءَايَةࣰ لِّلۡمُؤۡمِنِينَ وَيَهۡدِيَكُمۡ صِرَٰطࣰا\nT;0;48:20:2:مُّسۡتَقِيمࣰا¦48:21:1:وَأُخۡرَىٰ لَمۡ تَقۡدِرُواْ عَلَيۡهَا قَدۡ أَحَاطَ ٱللَّهُ بِهَاۚ\nT;0;48:21:2:وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣰا¦48:22:1:وَلَوۡ قَٰتَلَكُمُ ٱلَّذِينَ\nT;0;48:22:2:كَفَرُواْ لَوَلَّوُاْ ٱلۡأَدۡبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيࣰّا وَلَا نَصِيرࣰا¦48:23:1:سُنَّةَ\nT;0;48:23:2:ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِيلࣰا',
  '26;52;0;\nT;0;48:24:1:وَهُوَ ٱلَّذِي كَفَّ أَيۡدِيَهُمۡ عَنكُمۡ وَأَيۡدِيَكُمۡ عَنۡهُم بِبَطۡنِ مَكَّةَ مِنۢ\nT;0;48:24:2:بَعۡدِ أَنۡ أَظۡفَرَكُمۡ عَلَيۡهِمۡۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا\nT;0;48:25:1:هُمُ ٱلَّذِينَ كَفَرُواْ وَصَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ\nT;0;48:25:0:وَٱلۡهَدۡيَ مَعۡكُوفًا أَن يَبۡلُغَ مَحِلَّهُۥۚ وَلَوۡلَا رِجَالࣱ مُّؤۡمِنُونَ وَنِسَآءࣱ\nT;0;48:25:0:مُّؤۡمِنَٰتࣱ لَّمۡ تَعۡلَمُوهُمۡ أَن تَطَـُٔوهُمۡ فَتُصِيبَكُم مِّنۡهُم مَّعَرَّةُۢ\nT;0;48:25:0:بِغَيۡرِ عِلۡمࣲۖ لِّيُدۡخِلَ ٱللَّهُ فِي رَحۡمَتِهِۦ مَن يَشَآءُۚ لَوۡ تَزَيَّلُواْ لَعَذَّبۡنَا\nT;0;48:25:2:ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابًا أَلِيمًا¦48:26:1:إِذۡ جَعَلَ ٱلَّذِينَ كَفَرُواْ\nT;0;48:26:0:فِي قُلُوبِهِمُ ٱلۡحَمِيَّةَ حَمِيَّةَ ٱلۡجَٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ\nT;0;48:26:0:عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَلۡزَمَهُمۡ كَلِمَةَ ٱلتَّقۡوَىٰ\nT;0;48:26:2:وَكَانُوٓاْ أَحَقَّ بِهَا وَأَهۡلَهَاۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمࣰا\nT;0;48:27:1:لَّقَدۡ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءۡيَا بِٱلۡحَقِّۖ لَتَدۡخُلُنَّ ٱلۡمَسۡجِدَ\nT;0;48:27:0:ٱلۡحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمۡ وَمُقَصِّرِينَ\nT;0;48:27:0:لَا تَخَافُونَۖ فَعَلِمَ مَا لَمۡ تَعۡلَمُواْ فَجَعَلَ مِن دُونِ ذَٰلِكَ\nT;0;48:27:2:فَتۡحࣰا قَرِيبًا¦48:28:1:هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ\nT;0;48:28:2:ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦۚ وَكَفَىٰ بِٱللَّهِ شَهِيدࣰا',
  '26;52;0;206\nT;0;48:29:1:مُّحَمَّدࣱ رَّسُولُ ٱللَّهِۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلۡكُفَّارِ رُحَمَآءُ بَيۡنَهُمۡۖ\nT;0;48:29:0:تَرَىٰهُمۡ رُكَّعࣰا سُجَّدࣰا يَبۡتَغُونَ فَضۡلࣰا مِّنَ ٱللَّهِ وَرِضۡوَٰنࣰاۖ سِيمَاهُمۡ\nT;0;48:29:0:فِي وُجُوهِهِم مِّنۡ أَثَرِ ٱلسُّجُودِۚ ذَٰلِكَ مَثَلُهُمۡ فِي ٱلتَّوۡرَىٰةِۚ وَمَثَلُهُمۡ فِي\nT;0;48:29:0:ٱلۡإِنجِيلِ كَزَرۡعٍ أَخۡرَجَ شَطۡـَٔهُۥ فَـَٔازَرَهُۥ فَٱسۡتَغۡلَظَ فَٱسۡتَوَىٰ\nT;0;48:29:0:عَلَىٰ سُوقِهِۦ يُعۡجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلۡكُفَّارَۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ\nT;2;48:29:2:ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ مِنۡهُم مَّغۡفِرَةࣰ وَأَجۡرًا عَظِيمَۢا\nH;49\nB;49\nT;0;49:1:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُقَدِّمُواْ بَيۡنَ يَدَيِ ٱللَّهِ وَرَسُولِهِۦۖ وَٱتَّقُواْ\nT;0;49:1:2:ٱللَّهَۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمࣱ¦49:2:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَرۡفَعُوٓاْ\nT;0;49:2:0:أَصۡوَٰتَكُمۡ فَوۡقَ صَوۡتِ ٱلنَّبِيِّ وَلَا تَجۡهَرُواْ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ\nT;0;49:2:2:لِبَعۡضٍ أَن تَحۡبَطَ أَعۡمَٰلُكُمۡ وَأَنتُمۡ لَا تَشۡعُرُونَ¦49:3:1:إِنَّ ٱلَّذِينَ\nT;0;49:3:0:يَغُضُّونَ أَصۡوَٰتَهُمۡ عِندَ رَسُولِ ٱللَّهِ أُوْلَٰٓئِكَ ٱلَّذِينَ ٱمۡتَحَنَ\nT;0;49:3:2:ٱللَّهُ قُلُوبَهُمۡ لِلتَّقۡوَىٰۚ لَهُم مَّغۡفِرَةࣱ وَأَجۡرٌ عَظِيمٌ¦49:4:1:إِنَّ ٱلَّذِينَ\nT;0;49:4:2:يُنَادُونَكَ مِن وَرَآءِ ٱلۡحُجُرَٰتِ أَكۡثَرُهُمۡ لَا يَعۡقِلُونَ',
  '26;52;1;\nT;0;49:5:1:وَلَوۡ أَنَّهُمۡ صَبَرُواْ حَتَّىٰ تَخۡرُجَ إِلَيۡهِمۡ لَكَانَ خَيۡرࣰا لَّهُمۡۚ وَٱللَّهُ غَفُورࣱ\nT;0;49:5:2:رَّحِيمࣱ¦49:6:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن جَآءَكُمۡ فَاسِقُۢ بِنَبَإࣲ فَتَبَيَّنُوٓاْ أَن\nT;0;49:6:2:تُصِيبُواْ قَوۡمَۢا بِجَهَٰلَةࣲ فَتُصۡبِحُواْ عَلَىٰ مَا فَعَلۡتُمۡ نَٰدِمِينَ\nT;0;49:7:1:وَٱعۡلَمُوٓاْ أَنَّ فِيكُمۡ رَسُولَ ٱللَّهِۚ لَوۡ يُطِيعُكُمۡ فِي كَثِيرࣲ مِّنَ ٱلۡأَمۡرِ لَعَنِتُّمۡ\nT;0;49:7:0:وَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيۡكُمُ ٱلۡإِيمَٰنَ وَزَيَّنَهُۥ فِي قُلُوبِكُمۡ وَكَرَّهَ\nT;0;49:7:2:إِلَيۡكُمُ ٱلۡكُفۡرَ وَٱلۡفُسُوقَ وَٱلۡعِصۡيَانَۚ أُوْلَٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ\nT;0;49:8:3:فَضۡلࣰا مِّنَ ٱللَّهِ وَنِعۡمَةࣰۚ وَٱللَّهُ عَلِيمٌ حَكِيمࣱ¦49:9:1:وَإِن طَآئِفَتَانِ\nT;0;49:9:0:مِنَ ٱلۡمُؤۡمِنِينَ ٱقۡتَتَلُواْ فَأَصۡلِحُواْ بَيۡنَهُمَاۖ فَإِنۢ بَغَتۡ إِحۡدَىٰهُمَا\nT;0;49:9:0:عَلَى ٱلۡأُخۡرَىٰ فَقَٰتِلُواْ ٱلَّتِي تَبۡغِي حَتَّىٰ تَفِيٓءَ إِلَىٰٓ أَمۡرِ ٱللَّهِۚ فَإِن فَآءَتۡ\nT;0;49:9:2:فَأَصۡلِحُواْ بَيۡنَهُمَا بِٱلۡعَدۡلِ وَأَقۡسِطُوٓاْۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ\nT;0;49:10:1:إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةࣱ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ\nT;0;49:10:2:لَعَلَّكُمۡ تُرۡحَمُونَ¦49:11:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَسۡخَرۡ قَوۡمࣱ مِّن قَوۡمٍ\nT;0;49:11:0:عَسَىٰٓ أَن يَكُونُواْ خَيۡرࣰا مِّنۡهُمۡ وَلَا نِسَآءࣱ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيۡرࣰا\nT;0;49:11:0:مِّنۡهُنَّۖ وَلَا تَلۡمِزُوٓاْ أَنفُسَكُمۡ وَلَا تَنَابَزُواْ بِٱلۡأَلۡقَٰبِۖ بِئۡسَ ٱلِٱسۡمُ\nT;0;49:11:2:ٱلۡفُسُوقُ بَعۡدَ ٱلۡإِيمَٰنِۚ وَمَن لَّمۡ يَتُبۡ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ',
  '26;52;1;207\nT;0;49:12:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱجۡتَنِبُواْ كَثِيرࣰا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ\nT;0;49:12:0:إِثۡمࣱۖ وَلَا تَجَسَّسُواْ وَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن\nT;0;49:12:0:يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتࣰا فَكَرِهۡتُمُوهُۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ\nT;0;49:12:2:تَوَّابࣱ رَّحِيمࣱ¦49:13:1:يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَٰكُم مِّن ذَكَرࣲ وَأُنثَىٰ وَجَعَلۡنَٰكُمۡ\nT;0;49:13:0:شُعُوبࣰا وَقَبَآئِلَ لِتَعَارَفُوٓاْۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ إِنَّ ٱللَّهَ\nT;0;49:13:2:عَلِيمٌ خَبِيرࣱ¦49:14:1:۞ قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُواْ وَلَٰكِن\nT;0;49:14:0:قُولُوٓاْ أَسۡلَمۡنَا وَلَمَّا يَدۡخُلِ ٱلۡإِيمَٰنُ فِي قُلُوبِكُمۡۖ وَإِن تُطِيعُواْ ٱللَّهَ\nT;0;49:14:2:وَرَسُولَهُۥ لَا يَلِتۡكُم مِّنۡ أَعۡمَٰلِكُمۡ شَيۡـًٔاۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمٌ\nT;0;49:15:1:إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمۡ يَرۡتَابُواْ\nT;0;49:15:0:وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِۚ أُوْلَٰٓئِكَ هُمُ\nT;0;49:15:2:ٱلصَّٰدِقُونَ¦49:16:1:قُلۡ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمۡ وَٱللَّهُ يَعۡلَمُ مَا فِي\nT;0;49:16:2:ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمࣱ¦49:17:1:يَمُنُّونَ\nT;0;49:17:0:عَلَيۡكَ أَنۡ أَسۡلَمُواْۖ قُل لَّا تَمُنُّواْ عَلَيَّ إِسۡلَٰمَكُمۖ بَلِ ٱللَّهُ يَمُنُّ\nT;0;49:17:2:عَلَيۡكُمۡ أَنۡ هَدَىٰكُمۡ لِلۡإِيمَٰنِ إِن كُنتُمۡ صَٰدِقِينَ¦49:18:1:إِنَّ ٱللَّهَ يَعۡلَمُ\nT;2;49:18:2:غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ بَصِيرُۢ بِمَا تَعۡمَلُونَ',
  '26;52;2;\nH;50\nB;50\nT;0;50:1:3:قٓۚ وَٱلۡقُرۡءَانِ ٱلۡمَجِيدِ¦50:2:1:بَلۡ عَجِبُوٓاْ أَن جَآءَهُم مُّنذِرࣱ مِّنۡهُمۡ\nT;0;50:2:2:فَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا شَيۡءٌ عَجِيبٌ¦50:3:1:أَءِذَا مِتۡنَا وَكُنَّا تُرَابࣰاۖ ذَٰلِكَ\nT;0;50:3:2:رَجۡعُۢ بَعِيدࣱ¦50:4:1:قَدۡ عَلِمۡنَا مَا تَنقُصُ ٱلۡأَرۡضُ مِنۡهُمۡۖ وَعِندَنَا كِتَٰبٌ\nT;0;50:4:2:حَفِيظُۢ¦50:5:3:بَلۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَهُمۡ فِيٓ أَمۡرࣲ مَّرِيجٍ\nT;0;50:6:1:أَفَلَمۡ يَنظُرُوٓاْ إِلَى ٱلسَّمَآءِ فَوۡقَهُمۡ كَيۡفَ بَنَيۡنَٰهَا وَزَيَّنَّٰهَا\nT;0;50:6:2:وَمَا لَهَا مِن فُرُوجࣲ¦50:7:1:وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ\nT;0;50:7:2:وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجِۭ بَهِيجࣲ¦50:8:1:تَبۡصِرَةࣰ وَذِكۡرَىٰ لِكُلِّ عَبۡدࣲ\nT;0;50:8:2:مُّنِيبࣲ¦50:9:1:وَنَزَّلۡنَا مِنَ ٱلسَّمَآءِ مَآءࣰ مُّبَٰرَكࣰا فَأَنۢبَتۡنَا بِهِۦ جَنَّٰتࣲ\nT;0;50:9:2:وَحَبَّ ٱلۡحَصِيدِ¦50:10:3:وَٱلنَّخۡلَ بَاسِقَٰتࣲ لَّهَا طَلۡعࣱ نَّضِيدࣱ¦50:11:1:رِّزۡقࣰا\nT;0;50:11:2:لِّلۡعِبَادِۖ وَأَحۡيَيۡنَا بِهِۦ بَلۡدَةࣰ مَّيۡتࣰاۚ كَذَٰلِكَ ٱلۡخُرُوجُ¦50:12:1:كَذَّبَتۡ قَبۡلَهُمۡ\nT;0;50:12:2:قَوۡمُ نُوحࣲ وَأَصۡحَٰبُ ٱلرَّسِّ وَثَمُودُ¦50:13:3:وَعَادࣱ وَفِرۡعَوۡنُ وَإِخۡوَٰنُ لُوطࣲ\nT;0;50:14:3:وَأَصۡحَٰبُ ٱلۡأَيۡكَةِ وَقَوۡمُ تُبَّعࣲۚ كُلࣱّ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ\nT;0;50:15:3:أَفَعَيِينَا بِٱلۡخَلۡقِ ٱلۡأَوَّلِۚ بَلۡ هُمۡ فِي لَبۡسࣲ مِّنۡ خَلۡقࣲ جَدِيدࣲ',
  '26;52;2;208\nT;0;50:16:1:وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ وَنَعۡلَمُ مَا تُوَسۡوِسُ بِهِۦ نَفۡسُهُۥۖ وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ\nT;0;50:16:2:مِنۡ حَبۡلِ ٱلۡوَرِيدِ¦50:17:1:إِذۡ يَتَلَقَّى ٱلۡمُتَلَقِّيَانِ عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ\nT;0;50:17:2:قَعِيدࣱ¦50:18:3:مَّا يَلۡفِظُ مِن قَوۡلٍ إِلَّا لَدَيۡهِ رَقِيبٌ عَتِيدࣱ¦50:19:1:وَجَآءَتۡ سَكۡرَةُ\nT;0;50:19:2:ٱلۡمَوۡتِ بِٱلۡحَقِّۖ ذَٰلِكَ مَا كُنتَ مِنۡهُ تَحِيدُ¦50:20:1:وَنُفِخَ فِي ٱلصُّورِۚ ذَٰلِكَ يَوۡمُ\nT;0;50:20:2:ٱلۡوَعِيدِ¦50:21:3:وَجَآءَتۡ كُلُّ نَفۡسࣲ مَّعَهَا سَآئِقࣱ وَشَهِيدࣱ¦50:22:1:لَّقَدۡ كُنتَ\nT;0;50:22:2:فِي غَفۡلَةࣲ مِّنۡ هَٰذَا فَكَشَفۡنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلۡيَوۡمَ حَدِيدࣱ\nT;0;50:23:3:وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَيَّ عَتِيدٌ¦50:24:3:أَلۡقِيَا فِي جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدࣲ\nT;0;50:25:3:مَّنَّاعࣲ لِّلۡخَيۡرِ مُعۡتَدࣲ مُّرِيبٍ¦50:26:1:ٱلَّذِي جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ\nT;0;50:26:2:فَأَلۡقِيَاهُ فِي ٱلۡعَذَابِ ٱلشَّدِيدِ¦50:27:1:۞ قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطۡغَيۡتُهُۥ وَلَٰكِن\nT;0;50:27:2:كَانَ فِي ضَلَٰلِۭ بَعِيدࣲ¦50:28:1:قَالَ لَا تَخۡتَصِمُواْ لَدَيَّ وَقَدۡ قَدَّمۡتُ إِلَيۡكُم\nT;0;50:28:2:بِٱلۡوَعِيدِ¦50:29:3:مَا يُبَدَّلُ ٱلۡقَوۡلُ لَدَيَّ وَمَآ أَنَا۠ بِظَلَّٰمࣲ لِّلۡعَبِيدِ¦50:30:1:يَوۡمَ\nT;0;50:30:2:نَقُولُ لِجَهَنَّمَ هَلِ ٱمۡتَلَأۡتِ وَتَقُولُ هَلۡ مِن مَّزِيدࣲ¦50:31:1:وَأُزۡلِفَتِ ٱلۡجَنَّةُ\nT;0;50:31:2:لِلۡمُتَّقِينَ غَيۡرَ بَعِيدٍ¦50:32:3:هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظࣲ\nT;0;50:33:3:مَّنۡ خَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِ وَجَآءَ بِقَلۡبࣲ مُّنِيبٍ¦50:34:1:ٱدۡخُلُوهَا\nT;0;50:34:2:بِسَلَٰمࣲۖ ذَٰلِكَ يَوۡمُ ٱلۡخُلُودِ¦50:35:3:لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيۡنَا مَزِيدࣱ',
  '26;52;3;\nT;0;50:36:1:وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَشَدُّ مِنۡهُم بَطۡشࣰا فَنَقَّبُواْ\nT;0;50:36:2:فِي ٱلۡبِلَٰدِ هَلۡ مِن مَّحِيصٍ¦50:37:1:إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِمَن\nT;0;50:37:2:كَانَ لَهُۥ قَلۡبٌ أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِيدࣱ¦50:38:1:وَلَقَدۡ خَلَقۡنَا\nT;0;50:38:0:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامࣲ وَمَا مَسَّنَا\nT;0;50:38:2:مِن لُّغُوبࣲ¦50:39:1:فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ\nT;0;50:39:2:قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ¦50:40:1:وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ\nT;0;50:40:2:وَأَدۡبَٰرَ ٱلسُّجُودِ¦50:41:3:وَٱسۡتَمِعۡ يَوۡمَ يُنَادِ ٱلۡمُنَادِ مِن مَّكَانࣲ قَرِيبࣲ\nT;0;50:42:3:يَوۡمَ يَسۡمَعُونَ ٱلصَّيۡحَةَ بِٱلۡحَقِّۚ ذَٰلِكَ يَوۡمُ ٱلۡخُرُوجِ¦50:43:1:إِنَّا\nT;0;50:43:2:نَحۡنُ نُحۡيِۦ وَنُمِيتُ وَإِلَيۡنَا ٱلۡمَصِيرُ¦50:44:1:يَوۡمَ تَشَقَّقُ ٱلۡأَرۡضُ\nT;0;50:44:2:عَنۡهُمۡ سِرَاعࣰاۚ ذَٰلِكَ حَشۡرٌ عَلَيۡنَا يَسِيرࣱ¦50:45:1:نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَۖ\nT;2;50:45:2:وَمَآ أَنتَ عَلَيۡهِم بِجَبَّارࣲۖ فَذَكِّرۡ بِٱلۡقُرۡءَانِ مَن يَخَافُ وَعِيدِ\nH;51\nB;51\nT;0;51:1:3:وَٱلذَّٰرِيَٰتِ ذَرۡوࣰا¦51:2:3:فَٱلۡحَٰمِلَٰتِ وِقۡرࣰا¦51:3:3:فَٱلۡجَٰرِيَٰتِ يُسۡرࣰا\nT;0;51:4:3:فَٱلۡمُقَسِّمَٰتِ أَمۡرًا¦51:5:3:إِنَّمَا تُوعَدُونَ لَصَادِقࣱ¦51:6:3:وَإِنَّ ٱلدِّينَ لَوَٰقِعࣱ',
  '26;52;3;\nT;0;51:7:3:وَٱلسَّمَآءِ ذَاتِ ٱلۡحُبُكِ¦51:8:3:إِنَّكُمۡ لَفِي قَوۡلࣲ مُّخۡتَلِفࣲ¦51:9:1:يُؤۡفَكُ عَنۡهُ مَنۡ\nT;0;51:9:2:أُفِكَ¦51:10:3:قُتِلَ ٱلۡخَرَّٰصُونَ¦51:11:3:ٱلَّذِينَ هُمۡ فِي غَمۡرَةࣲ سَاهُونَ¦51:12:1:يَسۡـَٔلُونَ\nT;0;51:12:2:أَيَّانَ يَوۡمُ ٱلدِّينِ¦51:13:3:يَوۡمَ هُمۡ عَلَى ٱلنَّارِ يُفۡتَنُونَ¦51:14:1:ذُوقُواْ فِتۡنَتَكُمۡ هَٰذَا\nT;0;51:14:2:ٱلَّذِي كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ¦51:15:3:إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتࣲ وَعُيُونٍ\nT;0;51:16:3:ءَاخِذِينَ مَآ ءَاتَىٰهُمۡ رَبُّهُمۡۚ إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُحۡسِنِينَ\nT;0;51:17:3:كَانُواْ قَلِيلࣰا مِّنَ ٱلَّيۡلِ مَا يَهۡجَعُونَ¦51:18:3:وَبِٱلۡأَسۡحَارِ هُمۡ يَسۡتَغۡفِرُونَ\nT;0;51:19:3:وَفِيٓ أَمۡوَٰلِهِمۡ حَقࣱّ لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ¦51:20:1:وَفِي ٱلۡأَرۡضِ ءَايَٰتࣱ\nT;0;51:20:2:لِّلۡمُوقِنِينَ¦51:21:3:وَفِيٓ أَنفُسِكُمۡۚ أَفَلَا تُبۡصِرُونَ¦51:22:1:وَفِي ٱلسَّمَآءِ رِزۡقُكُمۡ\nT;0;51:22:2:وَمَا تُوعَدُونَ¦51:23:1:فَوَرَبِّ ٱلسَّمَآءِ وَٱلۡأَرۡضِ إِنَّهُۥ لَحَقࣱّ مِّثۡلَ مَآ أَنَّكُمۡ\nT;0;51:23:2:تَنطِقُونَ¦51:24:3:هَلۡ أَتَىٰكَ حَدِيثُ ضَيۡفِ إِبۡرَٰهِيمَ ٱلۡمُكۡرَمِينَ¦51:25:1:إِذۡ\nT;0;51:25:2:دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمࣰاۖ قَالَ سَلَٰمࣱ قَوۡمࣱ مُّنكَرُونَ¦51:26:1:فَرَاغَ إِلَىٰٓ\nT;0;51:26:2:أَهۡلِهِۦ فَجَآءَ بِعِجۡلࣲ سَمِينࣲ¦51:27:3:فَقَرَّبَهُۥٓ إِلَيۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ\nT;0;51:28:3:فَأَوۡجَسَ مِنۡهُمۡ خِيفَةࣰۖ قَالُواْ لَا تَخَفۡۖ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمࣲ\nT;0;51:29:3:فَأَقۡبَلَتِ ٱمۡرَأَتُهُۥ فِي صَرَّةࣲ فَصَكَّتۡ وَجۡهَهَا وَقَالَتۡ عَجُوزٌ عَقِيمࣱ\nT;0;51:30:3:قَالُواْ كَذَٰلِكِ قَالَ رَبُّكِۖ إِنَّهُۥ هُوَ ٱلۡحَكِيمُ ٱلۡعَلِيمُ',
  '27;53;0;209\nT;0;51:31:3:۞ قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ¦51:32:1:قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمࣲ\nT;0;51:32:2:مُّجۡرِمِينَ¦51:33:3:لِنُرۡسِلَ عَلَيۡهِمۡ حِجَارَةࣰ مِّن طِينࣲ¦51:34:1:مُّسَوَّمَةً عِندَ رَبِّكَ\nT;0;51:34:2:لِلۡمُسۡرِفِينَ¦51:35:3:فَأَخۡرَجۡنَا مَن كَانَ فِيهَا مِنَ ٱلۡمُؤۡمِنِينَ¦51:36:1:فَمَا وَجَدۡنَا\nT;0;51:36:2:فِيهَا غَيۡرَ بَيۡتࣲ مِّنَ ٱلۡمُسۡلِمِينَ¦51:37:1:وَتَرَكۡنَا فِيهَآ ءَايَةࣰ لِّلَّذِينَ يَخَافُونَ\nT;0;51:37:2:ٱلۡعَذَابَ ٱلۡأَلِيمَ¦51:38:1:وَفِي مُوسَىٰٓ إِذۡ أَرۡسَلۡنَٰهُ إِلَىٰ فِرۡعَوۡنَ بِسُلۡطَٰنࣲ\nT;0;51:38:2:مُّبِينࣲ¦51:39:3:فَتَوَلَّىٰ بِرُكۡنِهِۦ وَقَالَ سَٰحِرٌ أَوۡ مَجۡنُونࣱ¦51:40:1:فَأَخَذۡنَٰهُ وَجُنُودَهُۥ\nT;0;51:40:2:فَنَبَذۡنَٰهُمۡ فِي ٱلۡيَمِّ وَهُوَ مُلِيمࣱ¦51:41:1:وَفِي عَادٍ إِذۡ أَرۡسَلۡنَا عَلَيۡهِمُ ٱلرِّيحَ\nT;0;51:41:2:ٱلۡعَقِيمَ¦51:42:3:مَا تَذَرُ مِن شَيۡءٍ أَتَتۡ عَلَيۡهِ إِلَّا جَعَلَتۡهُ كَٱلرَّمِيمِ\nT;0;51:43:3:وَفِي ثَمُودَ إِذۡ قِيلَ لَهُمۡ تَمَتَّعُواْ حَتَّىٰ حِينࣲ¦51:44:1:فَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ\nT;0;51:44:2:فَأَخَذَتۡهُمُ ٱلصَّٰعِقَةُ وَهُمۡ يَنظُرُونَ¦51:45:1:فَمَا ٱسۡتَطَٰعُواْ مِن قِيَامࣲ\nT;0;51:45:2:وَمَا كَانُواْ مُنتَصِرِينَ¦51:46:1:وَقَوۡمَ نُوحࣲ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ قَوۡمࣰا\nT;0;51:46:2:فَٰسِقِينَ¦51:47:3:وَٱلسَّمَآءَ بَنَيۡنَٰهَا بِأَيۡيْدࣲ وَإِنَّا لَمُوسِعُونَ¦51:48:1:وَٱلۡأَرۡضَ\nT;0;51:48:2:فَرَشۡنَٰهَا فَنِعۡمَ ٱلۡمَٰهِدُونَ¦51:49:1:وَمِن كُلِّ شَيۡءٍ خَلَقۡنَا زَوۡجَيۡنِ\nT;0;51:49:2:لَعَلَّكُمۡ تَذَكَّرُونَ¦51:50:3:فَفِرُّوٓاْ إِلَى ٱللَّهِۖ إِنِّي لَكُم مِّنۡهُ نَذِيرࣱ مُّبِينࣱ\nT;0;51:51:3:وَلَا تَجۡعَلُواْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۖ إِنِّي لَكُم مِّنۡهُ نَذِيرࣱ مُّبِينࣱ',
  '27;53;0;\nT;0;51:52:1:كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبۡلِهِم مِّن رَّسُولٍ إِلَّا قَالُواْ سَاحِرٌ\nT;0;51:52:2:أَوۡ مَجۡنُونٌ¦51:53:3:أَتَوَاصَوۡاْ بِهِۦۚ بَلۡ هُمۡ قَوۡمࣱ طَاغُونَ¦51:54:1:فَتَوَلَّ عَنۡهُمۡ\nT;0;51:54:2:فَمَآ أَنتَ بِمَلُومࣲ¦51:55:3:وَذَكِّرۡ فَإِنَّ ٱلذِّكۡرَىٰ تَنفَعُ ٱلۡمُؤۡمِنِينَ¦51:56:1:وَمَا\nT;0;51:56:2:خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ¦51:57:1:مَآ أُرِيدُ مِنۡهُم مِّن رِّزۡقࣲ\nT;0;51:57:2:وَمَآ أُرِيدُ أَن يُطۡعِمُونِ¦51:58:3:إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلۡقُوَّةِ ٱلۡمَتِينُ\nT;0;51:59:1:فَإِنَّ لِلَّذِينَ ظَلَمُواْ ذَنُوبࣰا مِّثۡلَ ذَنُوبِ أَصۡحَٰبِهِمۡ فَلَا\nT;2;51:59:2:يَسۡتَعۡجِلُونِ¦51:60:3:فَوَيۡلࣱ لِّلَّذِينَ كَفَرُواْ مِن يَوۡمِهِمُ ٱلَّذِي يُوعَدُونَ\nH;52\nB;52\nT;0;52:1:3:وَٱلطُّورِ¦52:2:3:وَكِتَٰبࣲ مَّسۡطُورࣲ¦52:3:3:فِي رَقࣲّ مَّنشُورࣲ¦52:4:1:وَٱلۡبَيۡتِ\nT;0;52:4:2:ٱلۡمَعۡمُورِ¦52:5:3:وَٱلسَّقۡفِ ٱلۡمَرۡفُوعِ¦52:6:3:وَٱلۡبَحۡرِ ٱلۡمَسۡجُورِ¦52:7:1:إِنَّ\nT;0;52:7:2:عَذَابَ رَبِّكَ لَوَٰقِعࣱ¦52:8:3:مَّا لَهُۥ مِن دَافِعࣲ¦52:9:1:يَوۡمَ تَمُورُ ٱلسَّمَآءُ\nT;0;52:9:2:مَوۡرࣰا¦52:10:3:وَتَسِيرُ ٱلۡجِبَالُ سَيۡرࣰا¦52:11:3:فَوَيۡلࣱ يَوۡمَئِذࣲ لِّلۡمُكَذِّبِينَ\nT;0;52:12:3:ٱلَّذِينَ هُمۡ فِي خَوۡضࣲ يَلۡعَبُونَ¦52:13:1:يَوۡمَ يُدَعُّونَ إِلَىٰ نَارِ\nT;0;52:13:2:جَهَنَّمَ دَعًّا¦52:14:3:هَٰذِهِ ٱلنَّارُ ٱلَّتِي كُنتُم بِهَا تُكَذِّبُونَ',
  '27;53;0;210\nT;0;52:15:3:أَفَسِحۡرٌ هَٰذَآ أَمۡ أَنتُمۡ لَا تُبۡصِرُونَ¦52:16:1:ٱصۡلَوۡهَا فَٱصۡبِرُوٓاْ\nT;0;52:16:2:أَوۡ لَا تَصۡبِرُواْ سَوَآءٌ عَلَيۡكُمۡۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ\nT;0;52:17:3:إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتࣲ وَنَعِيمࣲ¦52:18:1:فَٰكِهِينَ بِمَآ ءَاتَىٰهُمۡ رَبُّهُمۡ\nT;0;52:18:2:وَوَقَىٰهُمۡ رَبُّهُمۡ عَذَابَ ٱلۡجَحِيمِ¦52:19:1:كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا\nT;0;52:19:2:كُنتُمۡ تَعۡمَلُونَ¦52:20:1:مُتَّكِـِٔينَ عَلَىٰ سُرُرࣲ مَّصۡفُوفَةࣲۖ وَزَوَّجۡنَٰهُم\nT;0;52:20:2:بِحُورٍ عِينࣲ¦52:21:1:وَٱلَّذِينَ ءَامَنُواْ وَٱتَّبَعَتۡهُمۡ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلۡحَقۡنَا\nT;0;52:21:0:بِهِمۡ ذُرِّيَّتَهُمۡ وَمَآ أَلَتۡنَٰهُم مِّنۡ عَمَلِهِم مِّن شَيۡءࣲۚ كُلُّ ٱمۡرِيِٕۭ بِمَا\nT;0;52:21:2:كَسَبَ رَهِينࣱ¦52:22:3:وَأَمۡدَدۡنَٰهُم بِفَٰكِهَةࣲ وَلَحۡمࣲ مِّمَّا يَشۡتَهُونَ\nT;0;52:23:3:يَتَنَٰزَعُونَ فِيهَا كَأۡسࣰا لَّا لَغۡوࣱ فِيهَا وَلَا تَأۡثِيمࣱ¦52:24:1:۞ وَيَطُوفُ عَلَيۡهِمۡ\nT;0;52:24:2:غِلۡمَانࣱ لَّهُمۡ كَأَنَّهُمۡ لُؤۡلُؤࣱ مَّكۡنُونࣱ¦52:25:1:وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ\nT;0;52:25:2:بَعۡضࣲ يَتَسَآءَلُونَ¦52:26:3:قَالُوٓاْ إِنَّا كُنَّا قَبۡلُ فِيٓ أَهۡلِنَا مُشۡفِقِينَ\nT;0;52:27:3:فَمَنَّ ٱللَّهُ عَلَيۡنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ¦52:28:1:إِنَّا كُنَّا\nT;0;52:28:2:مِن قَبۡلُ نَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِيمُ¦52:29:1:فَذَكِّرۡ فَمَآ أَنتَ بِنِعۡمَتِ\nT;0;52:29:2:رَبِّكَ بِكَاهِنࣲ وَلَا مَجۡنُونٍ¦52:30:1:أَمۡ يَقُولُونَ شَاعِرࣱ نَّتَرَبَّصُ بِهِۦ رَيۡبَ\nT;0;52:30:2:ٱلۡمَنُونِ¦52:31:3:قُلۡ تَرَبَّصُواْ فَإِنِّي مَعَكُم مِّنَ ٱلۡمُتَرَبِّصِينَ',
  '27;53;1;\nT;0;52:32:3:أَمۡ تَأۡمُرُهُمۡ أَحۡلَٰمُهُم بِهَٰذَآۚ أَمۡ هُمۡ قَوۡمࣱ طَاغُونَ¦52:33:1:أَمۡ يَقُولُونَ\nT;0;52:33:2:تَقَوَّلَهُۥۚ بَل لَّا يُؤۡمِنُونَ¦52:34:1:فَلۡيَأۡتُواْ بِحَدِيثࣲ مِّثۡلِهِۦٓ إِن كَانُواْ\nT;0;52:34:2:صَٰدِقِينَ¦52:35:3:أَمۡ خُلِقُواْ مِنۡ غَيۡرِ شَيۡءٍ أَمۡ هُمُ ٱلۡخَٰلِقُونَ\nT;0;52:36:3:أَمۡ خَلَقُواْ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۚ بَل لَّا يُوقِنُونَ¦52:37:1:أَمۡ عِندَهُمۡ\nT;0;52:37:2:خَزَآئِنُ رَبِّكَ أَمۡ هُمُ ٱلۡمُصَۣيۡطِرُونَ¦52:38:1:أَمۡ لَهُمۡ سُلَّمࣱ\nT;0;52:38:2:يَسۡتَمِعُونَ فِيهِۖ فَلۡيَأۡتِ مُسۡتَمِعُهُم بِسُلۡطَٰنࣲ مُّبِينٍ\nT;0;52:39:3:أَمۡ لَهُ ٱلۡبَنَٰتُ وَلَكُمُ ٱلۡبَنُونَ¦52:40:1:أَمۡ تَسۡـَٔلُهُمۡ أَجۡرࣰا فَهُم مِّن مَّغۡرَمࣲ\nT;0;52:40:2:مُّثۡقَلُونَ¦52:41:3:أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ¦52:42:1:أَمۡ يُرِيدُونَ\nT;0;52:42:2:كَيۡدࣰاۖ فَٱلَّذِينَ كَفَرُواْ هُمُ ٱلۡمَكِيدُونَ¦52:43:1:أَمۡ لَهُمۡ إِلَٰهٌ غَيۡرُ ٱللَّهِۚ\nT;0;52:43:2:سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ¦52:44:1:وَإِن يَرَوۡاْ كِسۡفࣰا مِّنَ ٱلسَّمَآءِ سَاقِطࣰا\nT;0;52:44:2:يَقُولُواْ سَحَابࣱ مَّرۡكُومࣱ¦52:45:1:فَذَرۡهُمۡ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي فِيهِ\nT;0;52:45:2:يُصۡعَقُونَ¦52:46:3:يَوۡمَ لَا يُغۡنِي عَنۡهُمۡ كَيۡدُهُمۡ شَيۡـࣰٔا وَلَا هُمۡ يُنصَرُونَ\nT;0;52:47:1:وَإِنَّ لِلَّذِينَ ظَلَمُواْ عَذَابࣰا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكۡثَرَهُمۡ\nT;0;52:47:2:لَا يَعۡلَمُونَ¦52:48:1:وَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِنَّكَ بِأَعۡيُنِنَاۖ وَسَبِّحۡ بِحَمۡدِ\nT;2;52:48:2:رَبِّكَ حِينَ تَقُومُ¦52:49:3:وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَإِدۡبَٰرَ ٱلنُّجُومِ',
  '27;53;1;211\nH;53\nB;53\nT;0;53:1:3:وَٱلنَّجۡمِ إِذَا هَوَىٰ¦53:2:3:مَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ¦53:3:1:وَمَا يَنطِقُ عَنِ\nT;0;53:3:2:ٱلۡهَوَىٰٓ¦53:4:3:إِنۡ هُوَ إِلَّا وَحۡيࣱ يُوحَىٰ¦53:5:3:عَلَّمَهُۥ شَدِيدُ ٱلۡقُوَىٰ¦53:6:1:ذُو مِرَّةࣲ\nT;0;53:6:2:فَٱسۡتَوَىٰ¦53:7:3:وَهُوَ بِٱلۡأُفُقِ ٱلۡأَعۡلَىٰ¦53:8:3:ثُمَّ دَنَا فَتَدَلَّىٰ¦53:9:1:فَكَانَ قَابَ\nT;0;53:9:2:قَوۡسَيۡنِ أَوۡ أَدۡنَىٰ¦53:10:3:فَأَوۡحَىٰٓ إِلَىٰ عَبۡدِهِۦ مَآ أَوۡحَىٰ¦53:11:1:مَا كَذَبَ ٱلۡفُؤَادُ\nT;0;53:11:2:مَا رَأَىٰٓ¦53:12:3:أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ¦53:13:3:وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ\nT;0;53:14:3:عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ¦53:15:3:عِندَهَا جَنَّةُ ٱلۡمَأۡوَىٰٓ¦53:16:1:إِذۡ يَغۡشَى ٱلسِّدۡرَةَ\nT;0;53:16:2:مَا يَغۡشَىٰ¦53:17:3:مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ¦53:18:1:لَقَدۡ رَأَىٰ مِنۡ ءَايَٰتِ رَبِّهِ\nT;0;53:18:2:ٱلۡكُبۡرَىٰٓ¦53:19:3:أَفَرَءَيۡتُمُ ٱللَّٰتَ وَٱلۡعُزَّىٰ¦53:20:3:وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلۡأُخۡرَىٰٓ\nT;0;53:21:3:أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلۡأُنثَىٰ¦53:22:3:تِلۡكَ إِذࣰا قِسۡمَةࣱ ضِيزَىٰٓ¦53:23:1:إِنۡ هِيَ إِلَّآ أَسۡمَآءࣱ\nT;0;53:23:0:سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِن يَتَّبِعُونَ إِلَّا\nT;0;53:23:2:ٱلظَّنَّ وَمَا تَهۡوَى ٱلۡأَنفُسُۖ وَلَقَدۡ جَآءَهُم مِّن رَّبِّهِمُ ٱلۡهُدَىٰٓ¦53:24:1:أَمۡ لِلۡإِنسَٰنِ\nT;0;53:24:2:مَا تَمَنَّىٰ¦53:25:3:فَلِلَّهِ ٱلۡأٓخِرَةُ وَٱلۡأُولَىٰ¦53:26:1:۞ وَكَم مِّن مَّلَكࣲ فِي ٱلسَّمَٰوَٰتِ\nT;0;53:26:2:لَا تُغۡنِي شَفَٰعَتُهُمۡ شَيۡـًٔا إِلَّا مِنۢ بَعۡدِ أَن يَأۡذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرۡضَىٰٓ',
  '27;53;2;\nT;0;53:27:3:إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ لَيُسَمُّونَ ٱلۡمَلَٰٓئِكَةَ تَسۡمِيَةَ ٱلۡأُنثَىٰ\nT;0;53:28:1:وَمَا لَهُم بِهِۦ مِنۡ عِلۡمٍۖ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّۖ وَإِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ\nT;0;53:28:2:ٱلۡحَقِّ شَيۡـࣰٔا¦53:29:1:فَأَعۡرِضۡ عَن مَّن تَوَلَّىٰ عَن ذِكۡرِنَا وَلَمۡ يُرِدۡ إِلَّا ٱلۡحَيَوٰةَ\nT;0;53:29:2:ٱلدُّنۡيَا¦53:30:1:ذَٰلِكَ مَبۡلَغُهُم مِّنَ ٱلۡعِلۡمِۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن\nT;0;53:30:2:سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِمَنِ ٱهۡتَدَىٰ¦53:31:1:وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي\nT;0;53:31:0:ٱلۡأَرۡضِ لِيَجۡزِيَ ٱلَّذِينَ أَسَٰٓـُٔواْ بِمَا عَمِلُواْ وَيَجۡزِيَ ٱلَّذِينَ أَحۡسَنُواْ\nT;0;53:31:2:بِٱلۡحُسۡنَى¦53:32:1:ٱلَّذِينَ يَجۡتَنِبُونَ كَبَٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ إِلَّا ٱللَّمَمَۚ\nT;0;53:32:0:إِنَّ رَبَّكَ وَٰسِعُ ٱلۡمَغۡفِرَةِۚ هُوَ أَعۡلَمُ بِكُمۡ إِذۡ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ\nT;0;53:32:0:وَإِذۡ أَنتُمۡ أَجِنَّةࣱ فِي بُطُونِ أُمَّهَٰتِكُمۡۖ فَلَا تُزَكُّوٓاْ أَنفُسَكُمۡۖ هُوَ أَعۡلَمُ\nT;0;53:32:2:بِمَنِ ٱتَّقَىٰٓ¦53:33:3:أَفَرَءَيۡتَ ٱلَّذِي تَوَلَّىٰ¦53:34:3:وَأَعۡطَىٰ قَلِيلࣰا وَأَكۡدَىٰٓ\nT;0;53:35:3:أَعِندَهُۥ عِلۡمُ ٱلۡغَيۡبِ فَهُوَ يَرَىٰٓ¦53:36:1:أَمۡ لَمۡ يُنَبَّأۡ بِمَا فِي صُحُفِ\nT;0;53:36:2:مُوسَىٰ¦53:37:3:وَإِبۡرَٰهِيمَ ٱلَّذِي وَفَّىٰٓ¦53:38:3:أَلَّا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰ\nT;0;53:39:3:وَأَن لَّيۡسَ لِلۡإِنسَٰنِ إِلَّا مَا سَعَىٰ¦53:40:3:وَأَنَّ سَعۡيَهُۥ سَوۡفَ يُرَىٰ\nT;0;53:41:3:ثُمَّ يُجۡزَىٰهُ ٱلۡجَزَآءَ ٱلۡأَوۡفَىٰ¦53:42:3:وَأَنَّ إِلَىٰ رَبِّكَ ٱلۡمُنتَهَىٰ\nT;0;53:43:3:وَأَنَّهُۥ هُوَ أَضۡحَكَ وَأَبۡكَىٰ¦53:44:3:وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحۡيَا',
  '27;53;2;\nT;0;53:45:3:وَأَنَّهُۥ خَلَقَ ٱلزَّوۡجَيۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰ¦53:46:3:مِن نُّطۡفَةٍ إِذَا تُمۡنَىٰ\nT;0;53:47:3:وَأَنَّ عَلَيۡهِ ٱلنَّشۡأَةَ ٱلۡأُخۡرَىٰ¦53:48:3:وَأَنَّهُۥ هُوَ أَغۡنَىٰ وَأَقۡنَىٰ¦53:49:1:وَأَنَّهُۥ هُوَ\nT;0;53:49:2:رَبُّ ٱلشِّعۡرَىٰ¦53:50:3:وَأَنَّهُۥٓ أَهۡلَكَ عَادًا ٱلۡأُولَىٰ¦53:51:1:وَثَمُودَاْ فَمَآ\nT;0;53:51:2:أَبۡقَىٰ¦53:52:3:وَقَوۡمَ نُوحࣲ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ هُمۡ أَظۡلَمَ وَأَطۡغَىٰ\nT;0;53:53:3:وَٱلۡمُؤۡتَفِكَةَ أَهۡوَىٰ¦53:54:3:فَغَشَّىٰهَا مَا غَشَّىٰ¦53:55:1:فَبِأَيِّ ءَالَآءِ رَبِّكَ\nT;0;53:55:2:تَتَمَارَىٰ¦53:56:3:هَٰذَا نَذِيرࣱ مِّنَ ٱلنُّذُرِ ٱلۡأُولَىٰٓ¦53:57:3:أَزِفَتِ ٱلۡأٓزِفَةُ\nT;0;53:58:3:لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ¦53:59:1:أَفَمِنۡ هَٰذَا ٱلۡحَدِيثِ\nT;0;53:59:2:تَعۡجَبُونَ¦53:60:3:وَتَضۡحَكُونَ وَلَا تَبۡكُونَ¦53:61:3:وَأَنتُمۡ سَٰمِدُونَ\nT;2;53:62:3:فَٱسۡجُدُواْۤ لِلَّهِۤ وَٱعۡبُدُواْ۩\nH;54\nB;54\nT;0;54:1:3:ٱقۡتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلۡقَمَرُ¦54:2:1:وَإِن يَرَوۡاْ ءَايَةࣰ يُعۡرِضُواْ وَيَقُولُواْ\nT;0;54:2:2:سِحۡرࣱ مُّسۡتَمِرࣱّ¦54:3:3:وَكَذَّبُواْ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡۚ وَكُلُّ أَمۡرࣲ مُّسۡتَقِرࣱّ\nT;0;54:4:3:وَلَقَدۡ جَآءَهُم مِّنَ ٱلۡأَنۢبَآءِ مَا فِيهِ مُزۡدَجَرٌ¦54:5:1:حِكۡمَةُۢ بَٰلِغَةࣱۖ فَمَا تُغۡنِ\nT;0;54:5:2:ٱلنُّذُرُ¦54:6:3:فَتَوَلَّ عَنۡهُمۡۘ يَوۡمَ يَدۡعُ ٱلدَّاعِ إِلَىٰ شَيۡءࣲ نُّكُرٍ',
  '27;53;2;212\nT;0;54:7:3:خُشَّعًا أَبۡصَٰرُهُمۡ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ كَأَنَّهُمۡ جَرَادࣱ مُّنتَشِرࣱ\nT;0;54:8:3:مُّهۡطِعِينَ إِلَى ٱلدَّاعِۖ يَقُولُ ٱلۡكَٰفِرُونَ هَٰذَا يَوۡمٌ عَسِرࣱ¦54:9:1:۞ كَذَّبَتۡ\nT;0;54:9:2:قَبۡلَهُمۡ قَوۡمُ نُوحࣲ فَكَذَّبُواْ عَبۡدَنَا وَقَالُواْ مَجۡنُونࣱ وَٱزۡدُجِرَ¦54:10:1:فَدَعَا\nT;0;54:10:2:رَبَّهُۥٓ أَنِّي مَغۡلُوبࣱ فَٱنتَصِرۡ¦54:11:3:فَفَتَحۡنَآ أَبۡوَٰبَ ٱلسَّمَآءِ بِمَآءࣲ مُّنۡهَمِرࣲ\nT;0;54:12:3:وَفَجَّرۡنَا ٱلۡأَرۡضَ عُيُونࣰا فَٱلۡتَقَى ٱلۡمَآءُ عَلَىٰٓ أَمۡرࣲ قَدۡ قُدِرَ\nT;0;54:13:3:وَحَمَلۡنَٰهُ عَلَىٰ ذَاتِ أَلۡوَٰحࣲ وَدُسُرࣲ¦54:14:1:تَجۡرِي بِأَعۡيُنِنَا جَزَآءࣰ لِّمَن كَانَ\nT;0;54:14:2:كُفِرَ¦54:15:3:وَلَقَد تَّرَكۡنَٰهَآ ءَايَةࣰ فَهَلۡ مِن مُّدَّكِرࣲ¦54:16:1:فَكَيۡفَ كَانَ\nT;0;54:16:2:عَذَابِي وَنُذُرِ¦54:17:3:وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ\nT;0;54:18:3:كَذَّبَتۡ عَادࣱ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ¦54:19:1:إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ رِيحࣰا\nT;0;54:19:2:صَرۡصَرࣰا فِي يَوۡمِ نَحۡسࣲ مُّسۡتَمِرࣲّ¦54:20:1:تَنزِعُ ٱلنَّاسَ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلࣲ\nT;0;54:20:2:مُّنقَعِرࣲ¦54:21:3:فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ¦54:22:1:وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ\nT;0;54:22:2:لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ¦54:23:3:كَذَّبَتۡ ثَمُودُ بِٱلنُّذُرِ¦54:24:1:فَقَالُوٓاْ أَبَشَرࣰا\nT;0;54:24:2:مِّنَّا وَٰحِدࣰا نَّتَّبِعُهُۥٓ إِنَّآ إِذࣰا لَّفِي ضَلَٰلࣲ وَسُعُرٍ¦54:25:1:أَءُلۡقِيَ ٱلذِّكۡرُ عَلَيۡهِ مِنۢ\nT;0;54:25:2:بَيۡنِنَا بَلۡ هُوَ كَذَّابٌ أَشِرࣱ¦54:26:3:سَيَعۡلَمُونَ غَدࣰا مَّنِ ٱلۡكَذَّابُ ٱلۡأَشِرُ\nT;0;54:27:3:إِنَّا مُرۡسِلُواْ ٱلنَّاقَةِ فِتۡنَةࣰ لَّهُمۡ فَٱرۡتَقِبۡهُمۡ وَٱصۡطَبِرۡ',
  '27;53;3;\nT;0;54:28:3:وَنَبِّئۡهُمۡ أَنَّ ٱلۡمَآءَ قِسۡمَةُۢ بَيۡنَهُمۡۖ كُلُّ شِرۡبࣲ مُّحۡتَضَرࣱ¦54:29:1:فَنَادَوۡاْ صَاحِبَهُمۡ\nT;0;54:29:2:فَتَعَاطَىٰ فَعَقَرَ¦54:30:3:فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ¦54:31:1:إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ\nT;0;54:31:2:صَيۡحَةࣰ وَٰحِدَةࣰ فَكَانُواْ كَهَشِيمِ ٱلۡمُحۡتَظِرِ¦54:32:1:وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ\nT;0;54:32:2:لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ¦54:33:3:كَذَّبَتۡ قَوۡمُ لُوطِۭ بِٱلنُّذُرِ¦54:34:1:إِنَّآ أَرۡسَلۡنَا\nT;0;54:34:2:عَلَيۡهِمۡ حَاصِبًا إِلَّآ ءَالَ لُوطࣲۖ نَّجَّيۡنَٰهُم بِسَحَرࣲ¦54:35:1:نِّعۡمَةࣰ مِّنۡ عِندِنَاۚ\nT;0;54:35:2:كَذَٰلِكَ نَجۡزِي مَن شَكَرَ¦54:36:1:وَلَقَدۡ أَنذَرَهُم بَطۡشَتَنَا فَتَمَارَوۡاْ\nT;0;54:36:2:بِٱلنُّذُرِ¦54:37:1:وَلَقَدۡ رَٰوَدُوهُ عَن ضَيۡفِهِۦ فَطَمَسۡنَآ أَعۡيُنَهُمۡ فَذُوقُواْ\nT;0;54:37:2:عَذَابِي وَنُذُرِ¦54:38:3:وَلَقَدۡ صَبَّحَهُم بُكۡرَةً عَذَابࣱ مُّسۡتَقِرࣱّ¦54:39:1:فَذُوقُواْ\nT;0;54:39:2:عَذَابِي وَنُذُرِ¦54:40:3:وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ\nT;0;54:41:3:وَلَقَدۡ جَآءَ ءَالَ فِرۡعَوۡنَ ٱلنُّذُرُ¦54:42:1:كَذَّبُواْ بِـَٔايَٰتِنَا كُلِّهَا فَأَخَذۡنَٰهُمۡ\nT;0;54:42:2:أَخۡذَ عَزِيزࣲ مُّقۡتَدِرٍ¦54:43:1:أَكُفَّارُكُمۡ خَيۡرࣱ مِّنۡ أُوْلَٰٓئِكُمۡ أَمۡ لَكُم بَرَآءَةࣱ\nT;0;54:43:2:فِي ٱلزُّبُرِ¦54:44:3:أَمۡ يَقُولُونَ نَحۡنُ جَمِيعࣱ مُّنتَصِرࣱ¦54:45:1:سَيُهۡزَمُ ٱلۡجَمۡعُ\nT;0;54:45:2:وَيُوَلُّونَ ٱلدُّبُرَ¦54:46:3:بَلِ ٱلسَّاعَةُ مَوۡعِدُهُمۡ وَٱلسَّاعَةُ أَدۡهَىٰ وَأَمَرُّ\nT;0;54:47:3:إِنَّ ٱلۡمُجۡرِمِينَ فِي ضَلَٰلࣲ وَسُعُرࣲ¦54:48:1:يَوۡمَ يُسۡحَبُونَ فِي ٱلنَّارِ عَلَىٰ\nT;0;54:48:2:وُجُوهِهِمۡ ذُوقُواْ مَسَّ سَقَرَ¦54:49:3:إِنَّا كُلَّ شَيۡءٍ خَلَقۡنَٰهُ بِقَدَرࣲ',
  '27;53;3;213\nT;0;54:50:3:وَمَآ أَمۡرُنَآ إِلَّا وَٰحِدَةࣱ كَلَمۡحِۭ بِٱلۡبَصَرِ¦54:51:1:وَلَقَدۡ أَهۡلَكۡنَآ\nT;0;54:51:2:أَشۡيَاعَكُمۡ فَهَلۡ مِن مُّدَّكِرࣲ¦54:52:3:وَكُلُّ شَيۡءࣲ فَعَلُوهُ فِي ٱلزُّبُرِ\nT;0;54:53:3:وَكُلُّ صَغِيرࣲ وَكَبِيرࣲ مُّسۡتَطَرٌ¦54:54:1:إِنَّ ٱلۡمُتَّقِينَ فِي\nT;2;54:54:2:جَنَّٰتࣲ وَنَهَرࣲ¦54:55:3:فِي مَقۡعَدِ صِدۡقٍ عِندَ مَلِيكࣲ مُّقۡتَدِرِۭ\nH;55\nB;55\nT;0;55:1:3:ٱلرَّحۡمَٰنُ¦55:2:3:عَلَّمَ ٱلۡقُرۡءَانَ¦55:3:3:خَلَقَ ٱلۡإِنسَٰنَ¦55:4:3:عَلَّمَهُ ٱلۡبَيَانَ\nT;0;55:5:3:ٱلشَّمۡسُ وَٱلۡقَمَرُ بِحُسۡبَانࣲ¦55:6:3:وَٱلنَّجۡمُ وَٱلشَّجَرُ يَسۡجُدَانِ\nT;0;55:7:3:وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلۡمِيزَانَ¦55:8:3:أَلَّا تَطۡغَوۡاْ فِي ٱلۡمِيزَانِ\nT;0;55:9:3:وَأَقِيمُواْ ٱلۡوَزۡنَ بِٱلۡقِسۡطِ وَلَا تُخۡسِرُواْ ٱلۡمِيزَانَ¦55:10:1:وَٱلۡأَرۡضَ\nT;0;55:10:2:وَضَعَهَا لِلۡأَنَامِ¦55:11:3:فِيهَا فَٰكِهَةࣱ وَٱلنَّخۡلُ ذَاتُ ٱلۡأَكۡمَامِ\nT;0;55:12:3:وَٱلۡحَبُّ ذُو ٱلۡعَصۡفِ وَٱلرَّيۡحَانُ¦55:13:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ\nT;0;55:14:3:خَلَقَ ٱلۡإِنسَٰنَ مِن صَلۡصَٰلࣲ كَٱلۡفَخَّارِ¦55:15:1:وَخَلَقَ ٱلۡجَآنَّ مِن\nT;0;55:15:2:مَّارِجࣲ مِّن نَّارࣲ¦55:16:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ¦55:17:1:رَبُّ\nT;0;55:17:2:ٱلۡمَشۡرِقَيۡنِ وَرَبُّ ٱلۡمَغۡرِبَيۡنِ¦55:18:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ',
  '27;54;0;\nT;0;55:19:3:مَرَجَ ٱلۡبَحۡرَيۡنِ يَلۡتَقِيَانِ¦55:20:3:بَيۡنَهُمَا بَرۡزَخࣱ لَّا يَبۡغِيَانِ¦55:21:1:فَبِأَيِّ ءَالَآءِ\nT;0;55:21:2:رَبِّكُمَا تُكَذِّبَانِ¦55:22:3:يَخۡرُجُ مِنۡهُمَا ٱللُّؤۡلُؤُ وَٱلۡمَرۡجَانُ¦55:23:1:فَبِأَيِّ ءَالَآءِ\nT;0;55:23:2:رَبِّكُمَا تُكَذِّبَانِ¦55:24:3:وَلَهُ ٱلۡجَوَارِ ٱلۡمُنشَـَٔاتُ فِي ٱلۡبَحۡرِ كَٱلۡأَعۡلَٰمِ\nT;0;55:25:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ¦55:26:3:كُلُّ مَنۡ عَلَيۡهَا فَانࣲ¦55:27:1:وَيَبۡقَىٰ وَجۡهُ\nT;0;55:27:2:رَبِّكَ ذُو ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ¦55:28:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ\nT;0;55:29:3:يَسۡـَٔلُهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ كُلَّ يَوۡمٍ هُوَ فِي شَأۡنࣲ¦55:30:1:فَبِأَيِّ\nT;0;55:30:2:ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ¦55:31:3:سَنَفۡرُغُ لَكُمۡ أَيُّهَ ٱلثَّقَلَانِ¦55:32:1:فَبِأَيِّ\nT;0;55:32:2:ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ¦55:33:1:يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ إِنِ ٱسۡتَطَعۡتُمۡ\nT;0;55:33:0:أَن تَنفُذُواْ مِنۡ أَقۡطَارِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ فَٱنفُذُواْۚ لَا تَنفُذُونَ\nT;0;55:33:2:إِلَّا بِسُلۡطَٰنࣲ¦55:34:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ¦55:35:1:يُرۡسَلُ عَلَيۡكُمَا\nT;0;55:35:2:شُوَاظࣱ مِّن نَّارࣲ وَنُحَاسࣱ فَلَا تَنتَصِرَانِ¦55:36:1:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا\nT;0;55:36:2:تُكَذِّبَانِ¦55:37:3:فَإِذَا ٱنشَقَّتِ ٱلسَّمَآءُ فَكَانَتۡ وَرۡدَةࣰ كَٱلدِّهَانِ\nT;0;55:38:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ¦55:39:1:فَيَوۡمَئِذࣲ لَّا يُسۡـَٔلُ عَن\nT;0;55:39:2:ذَنۢبِهِۦٓ إِنسࣱ وَلَا جَآنࣱّ¦55:40:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ\nT;0;55:41:3:يُعۡرَفُ ٱلۡمُجۡرِمُونَ بِسِيمَٰهُمۡ فَيُؤۡخَذُ بِٱلنَّوَٰصِي وَٱلۡأَقۡدَامِ',
  '27;54;0;\nT;0;55:42:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ¦55:43:1:هَٰذِهِۦ جَهَنَّمُ ٱلَّتِي يُكَذِّبُ بِهَا\nT;0;55:43:2:ٱلۡمُجۡرِمُونَ¦55:44:3:يَطُوفُونَ بَيۡنَهَا وَبَيۡنَ حَمِيمٍ ءَانࣲ¦55:45:1:فَبِأَيِّ ءَالَآءِ\nT;0;55:45:2:رَبِّكُمَا تُكَذِّبَانِ¦55:46:3:وَلِمَنۡ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ¦55:47:1:فَبِأَيِّ ءَالَآءِ\nT;0;55:47:2:رَبِّكُمَا تُكَذِّبَانِ¦55:48:3:ذَوَاتَآ أَفۡنَانࣲ¦55:49:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ\nT;0;55:50:3:فِيهِمَا عَيۡنَانِ تَجۡرِيَانِ¦55:51:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ¦55:52:1:فِيهِمَا\nT;0;55:52:2:مِن كُلِّ فَٰكِهَةࣲ زَوۡجَانِ¦55:53:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ¦55:54:1:مُتَّكِـِٔينَ\nT;0;55:54:2:عَلَىٰ فُرُشِۭ بَطَآئِنُهَا مِنۡ إِسۡتَبۡرَقࣲۚ وَجَنَى ٱلۡجَنَّتَيۡنِ دَانࣲ¦55:55:1:فَبِأَيِّ\nT;0;55:55:2:ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ¦55:56:1:فِيهِنَّ قَٰصِرَٰتُ ٱلطَّرۡفِ لَمۡ يَطۡمِثۡهُنَّ\nT;0;55:56:2:إِنسࣱ قَبۡلَهُمۡ وَلَا جَآنࣱّ¦55:57:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ¦55:58:1:كَأَنَّهُنَّ\nT;0;55:58:2:ٱلۡيَاقُوتُ وَٱلۡمَرۡجَانُ¦55:59:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ\nT;0;55:60:3:هَلۡ جَزَآءُ ٱلۡإِحۡسَٰنِ إِلَّا ٱلۡإِحۡسَٰنُ¦55:61:1:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا\nT;0;55:61:2:تُكَذِّبَانِ¦55:62:3:وَمِن دُونِهِمَا جَنَّتَانِ¦55:63:1:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا\nT;0;55:63:2:تُكَذِّبَانِ¦55:64:3:مُدۡهَآمَّتَانِ¦55:65:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ\nT;0;55:66:3:فِيهِمَا عَيۡنَانِ نَضَّاخَتَانِ¦55:67:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ\nT;0;55:68:3:فِيهِمَا فَٰكِهَةࣱ وَنَخۡلࣱ وَرُمَّانࣱ¦55:69:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ',
  '27;54;0;214\nT;0;55:70:3:فِيهِنَّ خَيۡرَٰتٌ حِسَانࣱ¦55:71:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ\nT;0;55:72:3:حُورࣱ مَّقۡصُورَٰتࣱ فِي ٱلۡخِيَامِ¦55:73:1:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا\nT;0;55:73:2:تُكَذِّبَانِ¦55:74:3:لَمۡ يَطۡمِثۡهُنَّ إِنسࣱ قَبۡلَهُمۡ وَلَا جَآنࣱّ¦55:75:1:فَبِأَيِّ\nT;0;55:75:2:ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ¦55:76:1:مُتَّكِـِٔينَ عَلَىٰ رَفۡرَفٍ خُضۡرࣲ\nT;0;55:76:2:وَعَبۡقَرِيٍّ حِسَانࣲ¦55:77:3:فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ\nT;2;55:78:3:تَبَٰرَكَ ٱسۡمُ رَبِّكَ ذِي ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ\nH;56\nB;56\nT;0;56:1:3:إِذَا وَقَعَتِ ٱلۡوَاقِعَةُ¦56:2:3:لَيۡسَ لِوَقۡعَتِهَا كَاذِبَةٌ¦56:3:3:خَافِضَةࣱ رَّافِعَةٌ\nT;0;56:4:3:إِذَا رُجَّتِ ٱلۡأَرۡضُ رَجࣰّا¦56:5:3:وَبُسَّتِ ٱلۡجِبَالُ بَسࣰّا¦56:6:1:فَكَانَتۡ\nT;0;56:6:2:هَبَآءࣰ مُّنۢبَثࣰّا¦56:7:3:وَكُنتُمۡ أَزۡوَٰجࣰا ثَلَٰثَةࣰ¦56:8:1:فَأَصۡحَٰبُ ٱلۡمَيۡمَنَةِ\nT;0;56:8:2:مَآ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ¦56:9:1:وَأَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ مَآ أَصۡحَٰبُ\nT;0;56:9:2:ٱلۡمَشۡـَٔمَةِ¦56:10:3:وَٱلسَّٰبِقُونَ ٱلسَّٰبِقُونَ¦56:11:3:أُوْلَٰٓئِكَ ٱلۡمُقَرَّبُونَ\nT;0;56:12:3:فِي جَنَّٰتِ ٱلنَّعِيمِ¦56:13:3:ثُلَّةࣱ مِّنَ ٱلۡأَوَّلِينَ¦56:14:3:وَقَلِيلࣱ مِّنَ ٱلۡأٓخِرِينَ\nT;0;56:15:3:عَلَىٰ سُرُرࣲ مَّوۡضُونَةࣲ¦56:16:3:مُّتَّكِـِٔينَ عَلَيۡهَا مُتَقَٰبِلِينَ',
  '27;54;1;\nT;0;56:17:3:يَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنࣱ مُّخَلَّدُونَ¦56:18:1:بِأَكۡوَابࣲ وَأَبَارِيقَ وَكَأۡسࣲ\nT;0;56:18:2:مِّن مَّعِينࣲ¦56:19:3:لَّا يُصَدَّعُونَ عَنۡهَا وَلَا يُنزِفُونَ¦56:20:1:وَفَٰكِهَةࣲ مِّمَّا\nT;0;56:20:2:يَتَخَيَّرُونَ¦56:21:3:وَلَحۡمِ طَيۡرࣲ مِّمَّا يَشۡتَهُونَ¦56:22:3:وَحُورٌ عِينࣱ¦56:23:1:كَأَمۡثَٰلِ\nT;0;56:23:2:ٱللُّؤۡلُوِٕ ٱلۡمَكۡنُونِ¦56:24:3:جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ¦56:25:1:لَا يَسۡمَعُونَ\nT;0;56:25:2:فِيهَا لَغۡوࣰا وَلَا تَأۡثِيمًا¦56:26:3:إِلَّا قِيلࣰا سَلَٰمࣰا سَلَٰمࣰا¦56:27:1:وَأَصۡحَٰبُ ٱلۡيَمِينِ مَآ\nT;0;56:27:2:أَصۡحَٰبُ ٱلۡيَمِينِ¦56:28:3:فِي سِدۡرࣲ مَّخۡضُودࣲ¦56:29:3:وَطَلۡحࣲ مَّنضُودࣲ¦56:30:1:وَظِلࣲّ\nT;0;56:30:2:مَّمۡدُودࣲ¦56:31:3:وَمَآءࣲ مَّسۡكُوبࣲ¦56:32:3:وَفَٰكِهَةࣲ كَثِيرَةࣲ¦56:33:1:لَّا مَقۡطُوعَةࣲ\nT;0;56:33:2:وَلَا مَمۡنُوعَةࣲ¦56:34:3:وَفُرُشࣲ مَّرۡفُوعَةٍ¦56:35:3:إِنَّآ أَنشَأۡنَٰهُنَّ إِنشَآءࣰ\nT;0;56:36:3:فَجَعَلۡنَٰهُنَّ أَبۡكَارًا¦56:37:3:عُرُبًا أَتۡرَابࣰا¦56:38:3:لِّأَصۡحَٰبِ ٱلۡيَمِينِ¦56:39:1:ثُلَّةࣱ\nT;0;56:39:2:مِّنَ ٱلۡأَوَّلِينَ¦56:40:3:وَثُلَّةࣱ مِّنَ ٱلۡأٓخِرِينَ¦56:41:1:وَأَصۡحَٰبُ ٱلشِّمَالِ مَآ\nT;0;56:41:2:أَصۡحَٰبُ ٱلشِّمَالِ¦56:42:3:فِي سَمُومࣲ وَحَمِيمࣲ¦56:43:3:وَظِلࣲّ مِّن يَحۡمُومࣲ\nT;0;56:44:3:لَّا بَارِدࣲ وَلَا كَرِيمٍ¦56:45:3:إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُتۡرَفِينَ¦56:46:1:وَكَانُواْ\nT;0;56:46:2:يُصِرُّونَ عَلَى ٱلۡحِنثِ ٱلۡعَظِيمِ¦56:47:1:وَكَانُواْ يَقُولُونَ أَئِذَا مِتۡنَا وَكُنَّا\nT;0;56:47:2:تُرَابࣰا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ¦56:48:3:أَوَءَابَآؤُنَا ٱلۡأَوَّلُونَ¦56:49:1:قُلۡ إِنَّ\nT;0;56:49:2:ٱلۡأَوَّلِينَ وَٱلۡأٓخِرِينَ¦56:50:3:لَمَجۡمُوعُونَ إِلَىٰ مِيقَٰتِ يَوۡمࣲ مَّعۡلُومࣲ',
  '27;54;1;215\nT;0;56:51:3:ثُمَّ إِنَّكُمۡ أَيُّهَا ٱلضَّآلُّونَ ٱلۡمُكَذِّبُونَ¦56:52:3:لَأٓكِلُونَ مِن شَجَرࣲ مِّن زَقُّومࣲ\nT;0;56:53:3:فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ¦56:54:3:فَشَٰرِبُونَ عَلَيۡهِ مِنَ ٱلۡحَمِيمِ¦56:55:1:فَشَٰرِبُونَ\nT;0;56:55:2:شُرۡبَ ٱلۡهِيمِ¦56:56:3:هَٰذَا نُزُلُهُمۡ يَوۡمَ ٱلدِّينِ¦56:57:1:نَحۡنُ خَلَقۡنَٰكُمۡ فَلَوۡلَا\nT;0;56:57:2:تُصَدِّقُونَ¦56:58:3:أَفَرَءَيۡتُم مَّا تُمۡنُونَ¦56:59:1:ءَأَنتُمۡ تَخۡلُقُونَهُۥٓ أَمۡ نَحۡنُ\nT;0;56:59:2:ٱلۡخَٰلِقُونَ¦56:60:3:نَحۡنُ قَدَّرۡنَا بَيۡنَكُمُ ٱلۡمَوۡتَ وَمَا نَحۡنُ بِمَسۡبُوقِينَ\nT;0;56:61:3:عَلَىٰٓ أَن نُّبَدِّلَ أَمۡثَٰلَكُمۡ وَنُنشِئَكُمۡ فِي مَا لَا تَعۡلَمُونَ¦56:62:1:وَلَقَدۡ\nT;0;56:62:2:عَلِمۡتُمُ ٱلنَّشۡأَةَ ٱلۡأُولَىٰ فَلَوۡلَا تَذَكَّرُونَ¦56:63:1:أَفَرَءَيۡتُم مَّا\nT;0;56:63:2:تَحۡرُثُونَ¦56:64:3:ءَأَنتُمۡ تَزۡرَعُونَهُۥٓ أَمۡ نَحۡنُ ٱلزَّٰرِعُونَ¦56:65:1:لَوۡ نَشَآءُ لَجَعَلۡنَٰهُ\nT;0;56:65:2:حُطَٰمࣰا فَظَلۡتُمۡ تَفَكَّهُونَ¦56:66:3:إِنَّا لَمُغۡرَمُونَ¦56:67:1:بَلۡ نَحۡنُ\nT;0;56:67:2:مَحۡرُومُونَ¦56:68:3:أَفَرَءَيۡتُمُ ٱلۡمَآءَ ٱلَّذِي تَشۡرَبُونَ¦56:69:1:ءَأَنتُمۡ أَنزَلۡتُمُوهُ\nT;0;56:69:2:مِنَ ٱلۡمُزۡنِ أَمۡ نَحۡنُ ٱلۡمُنزِلُونَ¦56:70:1:لَوۡ نَشَآءُ جَعَلۡنَٰهُ أُجَاجࣰا فَلَوۡلَا\nT;0;56:70:2:تَشۡكُرُونَ¦56:71:3:أَفَرَءَيۡتُمُ ٱلنَّارَ ٱلَّتِي تُورُونَ¦56:72:1:ءَأَنتُمۡ أَنشَأۡتُمۡ\nT;0;56:72:2:شَجَرَتَهَآ أَمۡ نَحۡنُ ٱلۡمُنشِـُٔونَ¦56:73:1:نَحۡنُ جَعَلۡنَٰهَا تَذۡكِرَةࣰ وَمَتَٰعࣰا\nT;0;56:73:2:لِّلۡمُقۡوِينَ¦56:74:3:فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ¦56:75:1:۞ فَلَآ أُقۡسِمُ\nT;0;56:75:2:بِمَوَٰقِعِ ٱلنُّجُومِ¦56:76:3:وَإِنَّهُۥ لَقَسَمࣱ لَّوۡ تَعۡلَمُونَ عَظِيمٌ',
  '27;54;2;\nT;0;56:77:3:إِنَّهُۥ لَقُرۡءَانࣱ كَرِيمࣱ¦56:78:3:فِي كِتَٰبࣲ مَّكۡنُونࣲ¦56:79:1:لَّا يَمَسُّهُۥٓ إِلَّا\nT;0;56:79:2:ٱلۡمُطَهَّرُونَ¦56:80:3:تَنزِيلࣱ مِّن رَّبِّ ٱلۡعَٰلَمِينَ¦56:81:1:أَفَبِهَٰذَا ٱلۡحَدِيثِ\nT;0;56:81:2:أَنتُم مُّدۡهِنُونَ¦56:82:3:وَتَجۡعَلُونَ رِزۡقَكُمۡ أَنَّكُمۡ تُكَذِّبُونَ¦56:83:1:فَلَوۡلَآ\nT;0;56:83:2:إِذَا بَلَغَتِ ٱلۡحُلۡقُومَ¦56:84:3:وَأَنتُمۡ حِينَئِذࣲ تَنظُرُونَ¦56:85:1:وَنَحۡنُ أَقۡرَبُ\nT;0;56:85:2:إِلَيۡهِ مِنكُمۡ وَلَٰكِن لَّا تُبۡصِرُونَ¦56:86:3:فَلَوۡلَآ إِن كُنتُمۡ غَيۡرَ مَدِينِينَ\nT;0;56:87:3:تَرۡجِعُونَهَآ إِن كُنتُمۡ صَٰدِقِينَ¦56:88:3:فَأَمَّآ إِن كَانَ مِنَ ٱلۡمُقَرَّبِينَ\nT;0;56:89:3:فَرَوۡحࣱ وَرَيۡحَانࣱ وَجَنَّتُ نَعِيمࣲ¦56:90:1:وَأَمَّآ إِن كَانَ مِنۡ أَصۡحَٰبِ\nT;0;56:90:2:ٱلۡيَمِينِ¦56:91:3:فَسَلَٰمࣱ لَّكَ مِنۡ أَصۡحَٰبِ ٱلۡيَمِينِ¦56:92:1:وَأَمَّآ إِن كَانَ مِنَ\nT;0;56:92:2:ٱلۡمُكَذِّبِينَ ٱلضَّآلِّينَ¦56:93:3:فَنُزُلࣱ مِّنۡ حَمِيمࣲ¦56:94:3:وَتَصۡلِيَةُ جَحِيمٍ\nT;2;56:95:3:إِنَّ هَٰذَا لَهُوَ حَقُّ ٱلۡيَقِينِ¦56:96:3:فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ\nH;57\nB;57\nT;0;57:1:3:سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ¦57:2:1:لَهُۥ مُلۡكُ\nT;0;57:2:2:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ وَيُمِيتُۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرٌ¦57:3:1:هُوَ\nT;0;57:3:2:ٱلۡأَوَّلُ وَٱلۡأٓخِرُ وَٱلظَّٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٌ',
  '27;54;2;\nT;0;57:4:1:هُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامࣲ ثُمَّ ٱسۡتَوَىٰ\nT;0;57:4:0:عَلَى ٱلۡعَرۡشِۖ يَعۡلَمُ مَا يَلِجُ فِي ٱلۡأَرۡضِ وَمَا يَخۡرُجُ مِنۡهَا وَمَا يَنزِلُ مِنَ\nT;0;57:4:0:ٱلسَّمَآءِ وَمَا يَعۡرُجُ فِيهَاۖ وَهُوَ مَعَكُمۡ أَيۡنَ مَا كُنتُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ\nT;0;57:4:2:بَصِيرࣱ¦57:5:3:لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ\nT;0;57:6:1:يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۚ وَهُوَ عَلِيمُۢ بِذَاتِ\nT;0;57:6:2:ٱلصُّدُورِ¦57:7:1:ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُواْ مِمَّا جَعَلَكُم\nT;0;57:7:2:مُّسۡتَخۡلَفِينَ فِيهِۖ فَٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَأَنفَقُواْ لَهُمۡ أَجۡرࣱ كَبِيرࣱ\nT;0;57:8:1:وَمَا لَكُمۡ لَا تُؤۡمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ يَدۡعُوكُمۡ لِتُؤۡمِنُواْ بِرَبِّكُمۡ وَقَدۡ\nT;0;57:8:2:أَخَذَ مِيثَٰقَكُمۡ إِن كُنتُم مُّؤۡمِنِينَ¦57:9:1:هُوَ ٱلَّذِي يُنَزِّلُ عَلَىٰ عَبۡدِهِۦٓ\nT;0;57:9:0:ءَايَٰتِۭ بَيِّنَٰتࣲ لِّيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَإِنَّ ٱللَّهَ بِكُمۡ\nT;0;57:9:2:لَرَءُوفࣱ رَّحِيمࣱ¦57:10:1:وَمَا لَكُمۡ أَلَّا تُنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ\nT;0;57:10:0:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ لَا يَسۡتَوِي مِنكُم مَّنۡ أَنفَقَ مِن قَبۡلِ ٱلۡفَتۡحِ\nT;0;57:10:0:وَقَٰتَلَۚ أُوْلَٰٓئِكَ أَعۡظَمُ دَرَجَةࣰ مِّنَ ٱلَّذِينَ أَنفَقُواْ مِنۢ بَعۡدُ وَقَٰتَلُواْۚ\nT;0;57:10:2:وَكُلࣰّا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ¦57:11:1:مَّن ذَا\nT;0;57:11:2:ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنࣰا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجۡرࣱ كَرِيمࣱ',
  '27;54;2;216\nT;0;57:12:1:يَوۡمَ تَرَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ يَسۡعَىٰ نُورُهُم بَيۡنَ أَيۡدِيهِمۡ\nT;0;57:12:0:وَبِأَيۡمَٰنِهِمۖ بُشۡرَىٰكُمُ ٱلۡيَوۡمَ جَنَّٰتࣱ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ\nT;0;57:12:2:فِيهَاۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ¦57:13:1:يَوۡمَ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ\nT;0;57:13:0:لِلَّذِينَ ءَامَنُواْ ٱنظُرُونَا نَقۡتَبِسۡ مِن نُّورِكُمۡ قِيلَ ٱرۡجِعُواْ وَرَآءَكُمۡ\nT;0;57:13:0:فَٱلۡتَمِسُواْ نُورࣰاۖ فَضُرِبَ بَيۡنَهُم بِسُورࣲ لَّهُۥ بَابُۢ بَاطِنُهُۥ فِيهِ ٱلرَّحۡمَةُ\nT;0;57:13:2:وَظَٰهِرُهُۥ مِن قِبَلِهِ ٱلۡعَذَابُ¦57:14:1:يُنَادُونَهُمۡ أَلَمۡ نَكُن مَّعَكُمۡۖ قَالُواْ بَلَىٰ\nT;0;57:14:0:وَلَٰكِنَّكُمۡ فَتَنتُمۡ أَنفُسَكُمۡ وَتَرَبَّصۡتُمۡ وَٱرۡتَبۡتُمۡ وَغَرَّتۡكُمُ ٱلۡأَمَانِيُّ\nT;0;57:14:2:حَتَّىٰ جَآءَ أَمۡرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلۡغَرُورُ¦57:15:1:فَٱلۡيَوۡمَ لَا يُؤۡخَذُ مِنكُمۡ\nT;0;57:15:0:فِدۡيَةࣱ وَلَا مِنَ ٱلَّذِينَ كَفَرُواْۚ مَأۡوَىٰكُمُ ٱلنَّارُۖ هِيَ مَوۡلَىٰكُمۡۖ\nT;0;57:15:2:وَبِئۡسَ ٱلۡمَصِيرُ¦57:16:1:۞ أَلَمۡ يَأۡنِ لِلَّذِينَ ءَامَنُوٓاْ أَن تَخۡشَعَ\nT;0;57:16:0:قُلُوبُهُمۡ لِذِكۡرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلۡحَقِّ وَلَا يَكُونُواْ كَٱلَّذِينَ\nT;0;57:16:0:أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلُ فَطَالَ عَلَيۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡۖ وَكَثِيرࣱ\nT;0;57:16:2:مِّنۡهُمۡ فَٰسِقُونَ¦57:17:1:ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ قَدۡ بَيَّنَّا\nT;0;57:17:2:لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ¦57:18:1:إِنَّ ٱلۡمُصَّدِّقِينَ وَٱلۡمُصَّدِّقَٰتِ\nT;0;57:18:2:وَأَقۡرَضُواْ ٱللَّهَ قَرۡضًا حَسَنࣰا يُضَٰعَفُ لَهُمۡ وَلَهُمۡ أَجۡرࣱ كَرِيمࣱ',
  '27;54;3;\nT;0;57:19:1:وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦٓ أُوْلَٰٓئِكَ هُمُ ٱلصِّدِّيقُونَۖ وَٱلشُّهَدَآءُ\nT;0;57:19:0:عِندَ رَبِّهِمۡ لَهُمۡ أَجۡرُهُمۡ وَنُورُهُمۡۖ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ\nT;0;57:19:2:بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ¦57:20:1:ٱعۡلَمُوٓاْ أَنَّمَا ٱلۡحَيَوٰةُ\nT;0;57:20:0:ٱلدُّنۡيَا لَعِبࣱ وَلَهۡوࣱ وَزِينَةࣱ وَتَفَاخُرُۢ بَيۡنَكُمۡ وَتَكَاثُرࣱ فِي ٱلۡأَمۡوَٰلِ\nT;0;57:20:0:وَٱلۡأَوۡلَٰدِۖ كَمَثَلِ غَيۡثٍ أَعۡجَبَ ٱلۡكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ\nT;0;57:20:0:مُصۡفَرࣰّا ثُمَّ يَكُونُ حُطَٰمࣰاۖ وَفِي ٱلۡأٓخِرَةِ عَذَابࣱ شَدِيدࣱ وَمَغۡفِرَةࣱ\nT;0;57:20:2:مِّنَ ٱللَّهِ وَرِضۡوَٰنࣱۚ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ\nT;0;57:21:1:سَابِقُوٓاْ إِلَىٰ مَغۡفِرَةࣲ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا كَعَرۡضِ ٱلسَّمَآءِ\nT;0;57:21:0:وَٱلۡأَرۡضِ أُعِدَّتۡ لِلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ ذَٰلِكَ فَضۡلُ\nT;0;57:21:2:ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ¦57:22:1:مَآ أَصَابَ\nT;0;57:22:0:مِن مُّصِيبَةࣲ فِي ٱلۡأَرۡضِ وَلَا فِيٓ أَنفُسِكُمۡ إِلَّا فِي كِتَٰبࣲ مِّن\nT;0;57:22:2:قَبۡلِ أَن نَّبۡرَأَهَآۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرࣱ¦57:23:1:لِّكَيۡلَا\nT;0;57:23:0:تَأۡسَوۡاْ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡۗ وَٱللَّهُ\nT;0;57:23:2:لَا يُحِبُّ كُلَّ مُخۡتَالࣲ فَخُورٍ¦57:24:1:ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ\nT;0;57:24:2:ٱلنَّاسَ بِٱلۡبُخۡلِۗ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ',
  '27;54;3;\nT;0;57:25:1:لَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ\nT;0;57:25:0:وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ\nT;0;57:25:0:بَأۡسࣱ شَدِيدࣱ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ\nT;0;57:25:2:بِٱلۡغَيۡبِۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزࣱ¦57:26:1:وَلَقَدۡ أَرۡسَلۡنَا نُوحࣰا وَإِبۡرَٰهِيمَ\nT;0;57:26:0:وَجَعَلۡنَا فِي ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَۖ فَمِنۡهُم مُّهۡتَدࣲۖ\nT;0;57:26:2:وَكَثِيرࣱ مِّنۡهُمۡ فَٰسِقُونَ¦57:27:1:ثُمَّ قَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم\nT;0;57:27:0:بِرُسُلِنَا وَقَفَّيۡنَا بِعِيسَى ٱبۡنِ مَرۡيَمَ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَۖ وَجَعَلۡنَا\nT;0;57:27:0:فِي قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأۡفَةࣰ وَرَحۡمَةࣰۚ وَرَهۡبَانِيَّةً\nT;0;57:27:0:ٱبۡتَدَعُوهَا مَا كَتَبۡنَٰهَا عَلَيۡهِمۡ إِلَّا ٱبۡتِغَآءَ رِضۡوَٰنِ ٱللَّهِ\nT;0;57:27:0:فَمَا رَعَوۡهَا حَقَّ رِعَايَتِهَاۖ فَـَٔاتَيۡنَا ٱلَّذِينَ ءَامَنُواْ مِنۡهُمۡ أَجۡرَهُمۡۖ\nT;0;57:27:2:وَكَثِيرࣱ مِّنۡهُمۡ فَٰسِقُونَ¦57:28:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ\nT;0;57:28:0:وَءَامِنُواْ بِرَسُولِهِۦ يُؤۡتِكُمۡ كِفۡلَيۡنِ مِن رَّحۡمَتِهِۦ وَيَجۡعَل لَّكُمۡ نُورࣰا\nT;0;57:28:2:تَمۡشُونَ بِهِۦ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِيمࣱ¦57:29:1:لِّئَلَّا يَعۡلَمَ\nT;0;57:29:0:أَهۡلُ ٱلۡكِتَٰبِ أَلَّا يَقۡدِرُونَ عَلَىٰ شَيۡءࣲ مِّن فَضۡلِ ٱللَّهِ وَأَنَّ\nT;2;57:29:2:ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ',
  '28;55;0;217\nH;58\nB;58\nT;0;58:1:1:قَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّتِي تُجَٰدِلُكَ فِي زَوۡجِهَا وَتَشۡتَكِيٓ إِلَى ٱللَّهِ\nT;0;58:1:2:وَٱللَّهُ يَسۡمَعُ تَحَاوُرَكُمَآۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ¦58:2:1:ٱلَّذِينَ يُظَٰهِرُونَ\nT;0;58:2:0:مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمۡۖ إِنۡ أُمَّهَٰتُهُمۡ إِلَّا ٱلَّٰٓـِٔي\nT;0;58:2:0:وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَيَقُولُونَ مُنكَرࣰا مِّنَ ٱلۡقَوۡلِ وَزُورࣰاۚ وَإِنَّ\nT;0;58:2:2:ٱللَّهَ لَعَفُوٌّ غَفُورࣱ¦58:3:1:وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمۡ ثُمَّ يَعُودُونَ\nT;0;58:3:0:لِمَا قَالُواْ فَتَحۡرِيرُ رَقَبَةࣲ مِّن قَبۡلِ أَن يَتَمَآسَّاۚ ذَٰلِكُمۡ تُوعَظُونَ\nT;0;58:3:2:بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ¦58:4:1:فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ\nT;0;58:4:0:مُتَتَابِعَيۡنِ مِن قَبۡلِ أَن يَتَمَآسَّاۖ فَمَن لَّمۡ يَسۡتَطِعۡ فَإِطۡعَامُ سِتِّينَ\nT;0;58:4:0:مِسۡكِينࣰاۚ ذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ\nT;0;58:4:2:وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٌ¦58:5:1:إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ\nT;0;58:5:0:كُبِتُواْ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَقَدۡ أَنزَلۡنَآ ءَايَٰتِۭ بَيِّنَٰتࣲۚ\nT;0;58:5:2:وَلِلۡكَٰفِرِينَ عَذَابࣱ مُّهِينࣱ¦58:6:1:يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعࣰا فَيُنَبِّئُهُم\nT;0;58:6:2:بِمَا عَمِلُوٓاْۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ شَهِيدٌ',
  '28;55;0;\nT;0;58:7:1:أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ مَا يَكُونُ مِن\nT;0;58:7:0:نَّجۡوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ وَلَآ أَدۡنَىٰ\nT;0;58:7:0:مِن ذَٰلِكَ وَلَآ أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَيۡنَ مَا كَانُواْۖ ثُمَّ يُنَبِّئُهُم بِمَا\nT;0;58:7:2:عَمِلُواْ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ¦58:8:1:أَلَمۡ تَرَ إِلَى ٱلَّذِينَ\nT;0;58:8:0:نُهُواْ عَنِ ٱلنَّجۡوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُواْ عَنۡهُ وَيَتَنَٰجَوۡنَ بِٱلۡإِثۡمِ\nT;0;58:8:0:وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِۖ وَإِذَا جَآءُوكَ حَيَّوۡكَ بِمَا لَمۡ يُحَيِّكَ\nT;0;58:8:0:بِهِ ٱللَّهُ وَيَقُولُونَ فِيٓ أَنفُسِهِمۡ لَوۡلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُۚ حَسۡبُهُمۡ\nT;0;58:8:2:جَهَنَّمُ يَصۡلَوۡنَهَاۖ فَبِئۡسَ ٱلۡمَصِيرُ¦58:9:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا\nT;0;58:9:0:تَنَٰجَيۡتُمۡ فَلَا تَتَنَٰجَوۡاْ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِ\nT;0;58:9:2:وَتَنَٰجَوۡاْ بِٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ¦58:10:1:إِنَّمَا\nT;0;58:10:0:ٱلنَّجۡوَىٰ مِنَ ٱلشَّيۡطَٰنِ لِيَحۡزُنَ ٱلَّذِينَ ءَامَنُواْ وَلَيۡسَ بِضَآرِّهِمۡ\nT;0;58:10:2:شَيۡـًٔا إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ¦58:11:1:يَٰٓأَيُّهَا\nT;0;58:11:0:ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ\nT;0;58:11:0:ٱللَّهُ لَكُمۡۖ وَإِذَا قِيلَ ٱنشُزُواْ فَٱنشُزُواْ يَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ\nT;0;58:11:2:وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتࣲۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ',
  '28;55;0;218\nT;0;58:12:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَٰجَيۡتُمُ ٱلرَّسُولَ فَقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ\nT;0;58:12:0:صَدَقَةࣰۚ ذَٰلِكَ خَيۡرࣱ لَّكُمۡ وَأَطۡهَرُۚ فَإِن لَّمۡ تَجِدُواْ فَإِنَّ ٱللَّهَ غَفُورࣱ\nT;0;58:12:2:رَّحِيمٌ¦58:13:1:ءَأَشۡفَقۡتُمۡ أَن تُقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ صَدَقَٰتࣲۚ فَإِذۡ لَمۡ\nT;0;58:13:0:تَفۡعَلُواْ وَتَابَ ٱللَّهُ عَلَيۡكُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱللَّهَ\nT;0;58:13:2:وَرَسُولَهُۥۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ¦58:14:1:۞ أَلَمۡ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوۡاْ\nT;0;58:14:0:قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِم مَّا هُم مِّنكُمۡ وَلَا مِنۡهُمۡ وَيَحۡلِفُونَ عَلَى ٱلۡكَذِبِ\nT;0;58:14:2:وَهُمۡ يَعۡلَمُونَ¦58:15:1:أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابࣰا شَدِيدًاۖ إِنَّهُمۡ سَآءَ مَا كَانُواْ\nT;0;58:15:2:يَعۡمَلُونَ¦58:16:1:ٱتَّخَذُوٓاْ أَيۡمَٰنَهُمۡ جُنَّةࣰ فَصَدُّواْ عَن سَبِيلِ ٱللَّهِ فَلَهُمۡ\nT;0;58:16:2:عَذَابࣱ مُّهِينࣱ¦58:17:1:لَّن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ\nT;0;58:17:2:شَيۡـًٔاۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ¦58:18:1:يَوۡمَ يَبۡعَثُهُمُ\nT;0;58:18:0:ٱللَّهُ جَمِيعࣰا فَيَحۡلِفُونَ لَهُۥ كَمَا يَحۡلِفُونَ لَكُمۡ وَيَحۡسَبُونَ أَنَّهُمۡ\nT;0;58:18:2:عَلَىٰ شَيۡءٍۚ أَلَآ إِنَّهُمۡ هُمُ ٱلۡكَٰذِبُونَ¦58:19:1:ٱسۡتَحۡوَذَ عَلَيۡهِمُ ٱلشَّيۡطَٰنُ\nT;0;58:19:0:فَأَنسَىٰهُمۡ ذِكۡرَ ٱللَّهِۚ أُوْلَٰٓئِكَ حِزۡبُ ٱلشَّيۡطَٰنِۚ أَلَآ إِنَّ حِزۡبَ ٱلشَّيۡطَٰنِ\nT;0;58:19:2:هُمُ ٱلۡخَٰسِرُونَ¦58:20:1:إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُوْلَٰٓئِكَ فِي\nT;0;58:20:2:ٱلۡأَذَلِّينَ¦58:21:3:كَتَبَ ٱللَّهُ لَأَغۡلِبَنَّ أَنَا۠ وَرُسُلِيٓۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزࣱ',
  '28;55;1;\nT;0;58:22:1:لَّا تَجِدُ قَوۡمࣰا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ\nT;0;58:22:0:ٱللَّهَ وَرَسُولَهُۥ وَلَوۡ كَانُوٓاْ ءَابَآءَهُمۡ أَوۡ أَبۡنَآءَهُمۡ أَوۡ إِخۡوَٰنَهُمۡ\nT;0;58:22:0:أَوۡ عَشِيرَتَهُمۡۚ أُوْلَٰٓئِكَ كَتَبَ فِي قُلُوبِهِمُ ٱلۡإِيمَٰنَ وَأَيَّدَهُم\nT;0;58:22:0:بِرُوحࣲ مِّنۡهُۖ وَيُدۡخِلُهُمۡ جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ\nT;0;58:22:0:خَٰلِدِينَ فِيهَاۚ رَضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ أُوْلَٰٓئِكَ حِزۡبُ\nT;2;58:22:2:ٱللَّهِۚ أَلَآ إِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡمُفۡلِحُونَ\nH;59\nB;59\nT;0;59:1:1:سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ\nT;0;59:1:2:ٱلۡحَكِيمُ¦59:2:1:هُوَ ٱلَّذِيٓ أَخۡرَجَ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن\nT;0;59:2:0:دِيَٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ مَا ظَنَنتُمۡ أَن يَخۡرُجُواْۖ وَظَنُّوٓاْ أَنَّهُم مَّانِعَتُهُمۡ\nT;0;59:2:0:حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ وَقَذَفَ\nT;0;59:2:0:فِي قُلُوبِهِمُ ٱلرُّعۡبَۚ يُخۡرِبُونَ بُيُوتَهُم بِأَيۡدِيهِمۡ وَأَيۡدِي ٱلۡمُؤۡمِنِينَ\nT;0;59:2:2:فَٱعۡتَبِرُواْ يَٰٓأُوْلِي ٱلۡأَبۡصَٰرِ¦59:3:1:وَلَوۡلَآ أَن كَتَبَ ٱللَّهُ عَلَيۡهِمُ\nT;0;59:3:2:ٱلۡجَلَآءَ لَعَذَّبَهُمۡ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابُ ٱلنَّارِ',
  '28;55;1;\nT;0;59:4:1:ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ\nT;0;59:4:2:ٱلۡعِقَابِ¦59:5:1:مَا قَطَعۡتُم مِّن لِّينَةٍ أَوۡ تَرَكۡتُمُوهَا قَآئِمَةً عَلَىٰٓ\nT;0;59:5:2:أُصُولِهَا فَبِإِذۡنِ ٱللَّهِ وَلِيُخۡزِيَ ٱلۡفَٰسِقِينَ¦59:6:1:وَمَآ أَفَآءَ ٱللَّهُ\nT;0;59:6:0:عَلَىٰ رَسُولِهِۦ مِنۡهُمۡ فَمَآ أَوۡجَفۡتُمۡ عَلَيۡهِ مِنۡ خَيۡلࣲ وَلَا رِكَابࣲ\nT;0;59:6:0:وَلَٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ\nT;0;59:6:2:قَدِيرࣱ¦59:7:1:مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡ أَهۡلِ ٱلۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ\nT;0;59:7:0:وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ كَيۡ لَا يَكُونَ\nT;0;59:7:0:دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا\nT;0;59:7:2:نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُواْۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ\nT;0;59:8:1:لِلۡفُقَرَآءِ ٱلۡمُهَٰجِرِينَ ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأَمۡوَٰلِهِمۡ\nT;0;59:8:0:يَبۡتَغُونَ فَضۡلࣰا مِّنَ ٱللَّهِ وَرِضۡوَٰنࣰا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ\nT;0;59:8:2:أُوْلَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ¦59:9:1:وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِيمَٰنَ مِن\nT;0;59:9:0:قَبۡلِهِمۡ يُحِبُّونَ مَنۡ هَاجَرَ إِلَيۡهِمۡ وَلَا يَجِدُونَ فِي صُدُورِهِمۡ\nT;0;59:9:0:حَاجَةࣰ مِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةࣱۚ\nT;0;59:9:2:وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ',
  '28;55;1;219\nT;0;59:10:1:وَٱلَّذِينَ جَآءُو مِنۢ بَعۡدِهِمۡ يَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا\nT;0;59:10:0:ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ وَلَا تَجۡعَلۡ فِي قُلُوبِنَا غِلࣰّا لِّلَّذِينَ\nT;0;59:10:2:ءَامَنُواْ رَبَّنَآ إِنَّكَ رَءُوفࣱ رَّحِيمٌ¦59:11:1:۞ أَلَمۡ تَرَ إِلَى ٱلَّذِينَ\nT;0;59:11:0:نَافَقُواْ يَقُولُونَ لِإِخۡوَٰنِهِمُ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ\nT;0;59:11:0:لَئِنۡ أُخۡرِجۡتُمۡ لَنَخۡرُجَنَّ مَعَكُمۡ وَلَا نُطِيعُ فِيكُمۡ أَحَدًا أَبَدࣰا\nT;0;59:11:2:وَإِن قُوتِلۡتُمۡ لَنَنصُرَنَّكُمۡ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ\nT;0;59:12:1:لَئِنۡ أُخۡرِجُواْ لَا يَخۡرُجُونَ مَعَهُمۡ وَلَئِن قُوتِلُواْ لَا يَنصُرُونَهُمۡ\nT;0;59:12:2:وَلَئِن نَّصَرُوهُمۡ لَيُوَلُّنَّ ٱلۡأَدۡبَٰرَ ثُمَّ لَا يُنصَرُونَ¦59:13:1:لَأَنتُمۡ\nT;0;59:13:0:أَشَدُّ رَهۡبَةࣰ فِي صُدُورِهِم مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمࣱ\nT;0;59:13:2:لَّا يَفۡقَهُونَ¦59:14:1:لَا يُقَٰتِلُونَكُمۡ جَمِيعًا إِلَّا فِي قُرࣰى مُّحَصَّنَةٍ\nT;0;59:14:0:أَوۡ مِن وَرَآءِ جُدُرِۭۚ بَأۡسُهُم بَيۡنَهُمۡ شَدِيدࣱۚ تَحۡسَبُهُمۡ جَمِيعࣰا\nT;0;59:14:2:وَقُلُوبُهُمۡ شَتَّىٰۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا يَعۡقِلُونَ¦59:15:1:كَمَثَلِ\nT;0;59:15:0:ٱلَّذِينَ مِن قَبۡلِهِمۡ قَرِيبࣰاۖ ذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ\nT;0;59:15:2:أَلِيمࣱ¦59:16:1:كَمَثَلِ ٱلشَّيۡطَٰنِ إِذۡ قَالَ لِلۡإِنسَٰنِ ٱكۡفُرۡ فَلَمَّا\nT;0;59:16:2:كَفَرَ قَالَ إِنِّي بَرِيٓءࣱ مِّنكَ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ',
  '28;55;2;\nT;0;59:17:1:فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِي ٱلنَّارِ خَٰلِدَيۡنِ فِيهَاۚ\nT;0;59:17:2:وَذَٰلِكَ جَزَٰٓؤُاْ ٱلظَّٰلِمِينَ¦59:18:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ\nT;0;59:18:0:ٱتَّقُواْ ٱللَّهَ وَلۡتَنظُرۡ نَفۡسࣱ مَّا قَدَّمَتۡ لِغَدࣲۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ\nT;0;59:18:2:ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ¦59:19:1:وَلَا تَكُونُواْ كَٱلَّذِينَ\nT;0;59:19:2:نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ أُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ\nT;0;59:20:1:لَا يَسۡتَوِيٓ أَصۡحَٰبُ ٱلنَّارِ وَأَصۡحَٰبُ ٱلۡجَنَّةِۚ أَصۡحَٰبُ\nT;0;59:20:2:ٱلۡجَنَّةِ هُمُ ٱلۡفَآئِزُونَ¦59:21:1:لَوۡ أَنزَلۡنَا هَٰذَا ٱلۡقُرۡءَانَ\nT;0;59:21:0:عَلَىٰ جَبَلࣲ لَّرَأَيۡتَهُۥ خَٰشِعࣰا مُّتَصَدِّعࣰا مِّنۡ خَشۡيَةِ ٱللَّهِۚ\nT;0;59:21:2:وَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِ لَعَلَّهُمۡ يَتَفَكَّرُونَ\nT;0;59:22:1:هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۖ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۖ\nT;0;59:22:2:هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ¦59:23:1:هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡمَلِكُ\nT;0;59:23:0:ٱلۡقُدُّوسُ ٱلسَّلَٰمُ ٱلۡمُؤۡمِنُ ٱلۡمُهَيۡمِنُ ٱلۡعَزِيزُ ٱلۡجَبَّارُ\nT;0;59:23:2:ٱلۡمُتَكَبِّرُۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ¦59:24:1:هُوَ ٱللَّهُ\nT;0;59:24:0:ٱلۡخَٰلِقُ ٱلۡبَارِئُ ٱلۡمُصَوِّرُۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ يُسَبِّحُ\nT;2;59:24:2:لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ',
  '28;55;2;\nH;60\nB;60\nT;0;60:1:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّي وَعَدُوَّكُمۡ أَوۡلِيَآءَ تُلۡقُونَ إِلَيۡهِم\nT;0;60:1:0:بِٱلۡمَوَدَّةِ وَقَدۡ كَفَرُواْ بِمَا جَآءَكُم مِّنَ ٱلۡحَقِّ يُخۡرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمۡ أَن\nT;0;60:1:0:تُؤۡمِنُواْ بِٱللَّهِ رَبِّكُمۡ إِن كُنتُمۡ خَرَجۡتُمۡ جِهَٰدࣰا فِي سَبِيلِي وَٱبۡتِغَآءَ مَرۡضَاتِيۚ\nT;0;60:1:0:تُسِرُّونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَأَنَا۠ أَعۡلَمُ بِمَآ أَخۡفَيۡتُمۡ وَمَآ أَعۡلَنتُمۡۚ وَمَن\nT;0;60:1:2:يَفۡعَلۡهُ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ¦60:2:1:إِن يَثۡقَفُوكُمۡ يَكُونُواْ لَكُمۡ أَعۡدَآءࣰ\nT;0;60:2:2:وَيَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ وَأَلۡسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّواْ لَوۡ تَكۡفُرُونَ\nT;0;60:3:1:لَن تَنفَعَكُمۡ أَرۡحَامُكُمۡ وَلَآ أَوۡلَٰدُكُمۡۚ يَوۡمَ ٱلۡقِيَٰمَةِ يَفۡصِلُ بَيۡنَكُمۡۚ وَٱللَّهُ\nT;0;60:3:2:بِمَا تَعۡمَلُونَ بَصِيرࣱ¦60:4:1:قَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةࣱ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ\nT;0;60:4:0:مَعَهُۥٓ إِذۡ قَالُواْ لِقَوۡمِهِمۡ إِنَّا بُرَءَٰٓؤُاْ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ\nT;0;60:4:0:كَفَرۡنَا بِكُمۡ وَبَدَا بَيۡنَنَا وَبَيۡنَكُمُ ٱلۡعَدَٰوَةُ وَٱلۡبَغۡضَآءُ أَبَدًا حَتَّىٰ تُؤۡمِنُواْ\nT;0;60:4:0:بِٱللَّهِ وَحۡدَهُۥٓ إِلَّا قَوۡلَ إِبۡرَٰهِيمَ لِأَبِيهِ لَأَسۡتَغۡفِرَنَّ لَكَ وَمَآ أَمۡلِكُ لَكَ مِنَ\nT;0;60:4:2:ٱللَّهِ مِن شَيۡءࣲۖ رَّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَبۡنَا وَإِلَيۡكَ ٱلۡمَصِيرُ¦60:5:1:رَبَّنَا\nT;0;60:5:2:لَا تَجۡعَلۡنَا فِتۡنَةࣰ لِّلَّذِينَ كَفَرُواْ وَٱغۡفِرۡ لَنَا رَبَّنَآۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ',
  '28;55;2;220\nT;0;60:6:1:لَقَدۡ كَانَ لَكُمۡ فِيهِمۡ أُسۡوَةٌ حَسَنَةࣱ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَۚ\nT;0;60:6:2:وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ¦60:7:1:۞ عَسَى ٱللَّهُ أَن يَجۡعَلَ بَيۡنَكُمۡ\nT;0;60:7:2:وَبَيۡنَ ٱلَّذِينَ عَادَيۡتُم مِّنۡهُم مَّوَدَّةࣰۚ وَٱللَّهُ قَدِيرࣱۚ وَٱللَّهُ غَفُورࣱ رَّحِيمࣱ\nT;0;60:8:1:لَّا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمۡ يُقَٰتِلُوكُمۡ فِي ٱلدِّينِ وَلَمۡ يُخۡرِجُوكُم\nT;0;60:8:2:مِّن دِيَٰرِكُمۡ أَن تَبَرُّوهُمۡ وَتُقۡسِطُوٓاْ إِلَيۡهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ\nT;0;60:9:1:إِنَّمَا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَٰتَلُوكُمۡ فِي ٱلدِّينِ وَأَخۡرَجُوكُم مِّن\nT;0;60:9:0:دِيَٰرِكُمۡ وَظَٰهَرُواْ عَلَىٰٓ إِخۡرَاجِكُمۡ أَن تَوَلَّوۡهُمۡۚ وَمَن يَتَوَلَّهُمۡ فَأُوْلَٰٓئِكَ\nT;0;60:9:2:هُمُ ٱلظَّٰلِمُونَ¦60:10:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا جَآءَكُمُ ٱلۡمُؤۡمِنَٰتُ مُهَٰجِرَٰتࣲ\nT;0;60:10:0:فَٱمۡتَحِنُوهُنَّۖ ٱللَّهُ أَعۡلَمُ بِإِيمَٰنِهِنَّۖ فَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَٰتࣲ فَلَا\nT;0;60:10:0:تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ لَا هُنَّ حِلࣱّ لَّهُمۡ وَلَا هُمۡ يَحِلُّونَ لَهُنَّۖ وَءَاتُوهُم\nT;0;60:10:0:مَّآ أَنفَقُواْۚ وَلَا جُنَاحَ عَلَيۡكُمۡ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّۚ\nT;0;60:10:0:وَلَا تُمۡسِكُواْ بِعِصَمِ ٱلۡكَوَافِرِ وَسۡـَٔلُواْ مَآ أَنفَقۡتُمۡ وَلۡيَسۡـَٔلُواْ مَآ أَنفَقُواْۚ\nT;0;60:10:2:ذَٰلِكُمۡ حُكۡمُ ٱللَّهِ يَحۡكُمُ بَيۡنَكُمۡۖ وَٱللَّهُ عَلِيمٌ حَكِيمࣱ¦60:11:1:وَإِن فَاتَكُمۡ\nT;0;60:11:0:شَيۡءࣱ مِّنۡ أَزۡوَٰجِكُمۡ إِلَى ٱلۡكُفَّارِ فَعَاقَبۡتُمۡ فَـَٔاتُواْ ٱلَّذِينَ ذَهَبَتۡ\nT;0;60:11:2:أَزۡوَٰجُهُم مِّثۡلَ مَآ أَنفَقُواْۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ',
  '28;55;3;\nT;0;60:12:1:يَٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا جَآءَكَ ٱلۡمُؤۡمِنَٰتُ يُبَايِعۡنَكَ عَلَىٰٓ أَن لَّا يُشۡرِكۡنَ بِٱللَّهِ\nT;0;60:12:0:شَيۡـࣰٔا وَلَا يَسۡرِقۡنَ وَلَا يَزۡنِينَ وَلَا يَقۡتُلۡنَ أَوۡلَٰدَهُنَّ وَلَا يَأۡتِينَ\nT;0;60:12:0:بِبُهۡتَٰنࣲ يَفۡتَرِينَهُۥ بَيۡنَ أَيۡدِيهِنَّ وَأَرۡجُلِهِنَّ وَلَا يَعۡصِينَكَ فِي\nT;0;60:12:2:مَعۡرُوفࣲ فَبَايِعۡهُنَّ وَٱسۡتَغۡفِرۡ لَهُنَّ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ\nT;0;60:13:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِمۡ قَدۡ\nT;2;60:13:2:يَئِسُواْ مِنَ ٱلۡأٓخِرَةِ كَمَا يَئِسَ ٱلۡكُفَّارُ مِنۡ أَصۡحَٰبِ ٱلۡقُبُورِ\nH;61\nB;61\nT;0;61:1:3:سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\nT;0;61:2:3:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ\nT;0;61:3:3:كَبُرَ مَقۡتًا عِندَ ٱللَّهِ أَن تَقُولُواْ مَا لَا تَفۡعَلُونَ¦61:4:1:إِنَّ\nT;0;61:4:0:ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِي سَبِيلِهِۦ صَفࣰّا كَأَنَّهُم\nT;0;61:4:2:بُنۡيَٰنࣱ مَّرۡصُوصࣱ¦61:5:1:وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ لِمَ\nT;0;61:5:0:تُؤۡذُونَنِي وَقَد تَّعۡلَمُونَ أَنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡۖ فَلَمَّا زَاغُوٓاْ\nT;0;61:5:2:أَزَاغَ ٱللَّهُ قُلُوبَهُمۡۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ',
  '28;55;3;\nT;0;61:6:1:وَإِذۡ قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ يَٰبَنِيٓ إِسۡرَٰٓءِيلَ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُم مُّصَدِّقࣰا لِّمَا\nT;0;61:6:0:بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَمُبَشِّرَۢا بِرَسُولࣲ يَأۡتِي مِنۢ بَعۡدِي ٱسۡمُهُۥٓ أَحۡمَدُۖ فَلَمَّا\nT;0;61:6:2:جَآءَهُم بِٱلۡبَيِّنَٰتِ قَالُواْ هَٰذَا سِحۡرࣱ مُّبِينࣱ¦61:7:1:وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى\nT;0;61:7:2:ٱللَّهِ ٱلۡكَذِبَ وَهُوَ يُدۡعَىٰٓ إِلَى ٱلۡإِسۡلَٰمِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ\nT;0;61:8:1:يُرِيدُونَ لِيُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوۡ كَرِهَ\nT;0;61:8:2:ٱلۡكَٰفِرُونَ¦61:9:1:هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ\nT;0;61:9:2:عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ¦61:10:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ هَلۡ أَدُلُّكُمۡ عَلَىٰ\nT;0;61:10:2:تِجَٰرَةࣲ تُنجِيكُم مِّنۡ عَذَابٍ أَلِيمࣲ¦61:11:1:تُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ\nT;0;61:11:2:فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡۚ ذَٰلِكُمۡ خَيۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ\nT;0;61:12:1:يَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ وَيُدۡخِلۡكُمۡ جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَمَسَٰكِنَ\nT;0;61:12:2:طَيِّبَةࣰ فِي جَنَّٰتِ عَدۡنࣲۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ¦61:13:1:وَأُخۡرَىٰ تُحِبُّونَهَاۖ نَصۡرࣱ\nT;0;61:13:2:مِّنَ ٱللَّهِ وَفَتۡحࣱ قَرِيبࣱۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ¦61:14:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُوٓاْ\nT;0;61:14:0:أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ لِلۡحَوَارِيِّـۧنَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ\nT;0;61:14:0:قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِۖ فَـَٔامَنَت طَّآئِفَةࣱ مِّنۢ بَنِيٓ إِسۡرَٰٓءِيلَ\nT;2;61:14:2:وَكَفَرَت طَّآئِفَةࣱۖ فَأَيَّدۡنَا ٱلَّذِينَ ءَامَنُواْ عَلَىٰ عَدُوِّهِمۡ فَأَصۡبَحُواْ ظَٰهِرِينَ',
  '28;56;0;221\nH;62\nB;62\nT;0;62:1:1:يُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ ٱلۡمَلِكِ ٱلۡقُدُّوسِ ٱلۡعَزِيزِ\nT;0;62:1:2:ٱلۡحَكِيمِ¦62:2:1:هُوَ ٱلَّذِي بَعَثَ فِي ٱلۡأُمِّيِّـۧنَ رَسُولࣰا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ\nT;0;62:2:0:ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ\nT;0;62:2:2:مِن قَبۡلُ لَفِي ضَلَٰلࣲ مُّبِينࣲ¦62:3:1:وَءَاخَرِينَ مِنۡهُمۡ لَمَّا يَلۡحَقُواْ بِهِمۡۚ\nT;0;62:3:2:وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ¦62:4:1:ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ\nT;0;62:4:2:ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ¦62:5:1:مَثَلُ ٱلَّذِينَ حُمِّلُواْ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ\nT;0;62:5:0:يَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ بِئۡسَ مَثَلُ ٱلۡقَوۡمِ\nT;0;62:5:2:ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ\nT;0;62:6:1:قُلۡ يَٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓاْ إِن زَعَمۡتُمۡ أَنَّكُمۡ أَوۡلِيَآءُ لِلَّهِ مِن\nT;0;62:6:2:دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ¦62:7:1:وَلَا يَتَمَنَّوۡنَهُۥٓ\nT;0;62:7:2:أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ¦62:8:1:قُلۡ\nT;0;62:8:0:إِنَّ ٱلۡمَوۡتَ ٱلَّذِي تَفِرُّونَ مِنۡهُ فَإِنَّهُۥ مُلَٰقِيكُمۡۖ ثُمَّ تُرَدُّونَ\nT;0;62:8:2:إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ',
  '28;56;0;222\nT;0;62:9:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نُودِيَ لِلصَّلَوٰةِ مِن يَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡاْ\nT;0;62:9:2:إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُواْ ٱلۡبَيۡعَۚ ذَٰلِكُمۡ خَيۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ\nT;0;62:10:1:فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ\nT;0;62:10:2:مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرࣰا لَّعَلَّكُمۡ تُفۡلِحُونَ\nT;0;62:11:1:وَإِذَا رَأَوۡاْ تِجَٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوٓاْ إِلَيۡهَا وَتَرَكُوكَ قَآئِمࣰاۚ قُلۡ مَا عِندَ\nT;2;62:11:2:ٱللَّهِ خَيۡرࣱ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَٰرَةِۚ وَٱللَّهُ خَيۡرُ ٱلرَّٰزِقِينَ\nH;63\nB;63\nT;0;63:1:1:إِذَا جَآءَكَ ٱلۡمُنَٰفِقُونَ قَالُواْ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ وَٱللَّهُ يَعۡلَمُ إِنَّكَ\nT;0;63:1:2:لَرَسُولُهُۥ وَٱللَّهُ يَشۡهَدُ إِنَّ ٱلۡمُنَٰفِقِينَ لَكَٰذِبُونَ¦63:2:1:ٱتَّخَذُوٓاْ\nT;0;63:2:0:أَيۡمَٰنَهُمۡ جُنَّةࣰ فَصَدُّواْ عَن سَبِيلِ ٱللَّهِۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ\nT;0;63:2:2:يَعۡمَلُونَ¦63:3:1:ذَٰلِكَ بِأَنَّهُمۡ ءَامَنُواْ ثُمَّ كَفَرُواْ فَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ\nT;0;63:3:2:لَا يَفۡقَهُونَ¦63:4:1:۞ وَإِذَا رَأَيۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ وَإِن يَقُولُواْ\nT;0;63:4:0:تَسۡمَعۡ لِقَوۡلِهِمۡۖ كَأَنَّهُمۡ خُشُبࣱ مُّسَنَّدَةࣱۖ يَحۡسَبُونَ كُلَّ صَيۡحَةٍ\nT;0;63:4:2:عَلَيۡهِمۡۚ هُمُ ٱلۡعَدُوُّ فَٱحۡذَرۡهُمۡۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ',
  '28;56;1;\nT;0;63:5:1:وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ يَسۡتَغۡفِرۡ لَكُمۡ رَسُولُ ٱللَّهِ لَوَّوۡاْ\nT;0;63:5:2:رُءُوسَهُمۡ وَرَأَيۡتَهُمۡ يَصُدُّونَ وَهُم مُّسۡتَكۡبِرُونَ\nT;0;63:6:1:سَوَآءٌ عَلَيۡهِمۡ أَسۡتَغۡفَرۡتَ لَهُمۡ أَمۡ لَمۡ تَسۡتَغۡفِرۡ لَهُمۡ لَن\nT;0;63:6:2:يَغۡفِرَ ٱللَّهُ لَهُمۡۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ\nT;0;63:7:1:هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُواْ عَلَىٰ مَنۡ عِندَ رَسُولِ ٱللَّهِ\nT;0;63:7:0:حَتَّىٰ يَنفَضُّواْۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَٰكِنَّ\nT;0;63:7:2:ٱلۡمُنَٰفِقِينَ لَا يَفۡقَهُونَ¦63:8:1:يَقُولُونَ لَئِن رَّجَعۡنَآ إِلَى\nT;0;63:8:0:ٱلۡمَدِينَةِ لَيُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّۚ وَلِلَّهِ ٱلۡعِزَّةُ\nT;0;63:8:2:وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَعۡلَمُونَ\nT;0;63:9:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ\nT;0;63:9:0:عَن ذِكۡرِ ٱللَّهِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ\nT;0;63:9:2:ٱلۡخَٰسِرُونَ¦63:10:1:وَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن\nT;0;63:10:0:يَأۡتِيَ أَحَدَكُمُ ٱلۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡلَآ أَخَّرۡتَنِيٓ إِلَىٰٓ أَجَلࣲ\nT;0;63:10:2:قَرِيبࣲ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ¦63:11:1:وَلَن يُؤَخِّرَ\nT;2;63:11:2:ٱللَّهُ نَفۡسًا إِذَا جَآءَ أَجَلُهَاۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ',
  '28;56;1;\nH;64\nB;64\nT;0;64:1:1:يُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ لَهُ ٱلۡمُلۡكُ وَلَهُ ٱلۡحَمۡدُۖ وَهُوَ\nT;0;64:1:2:عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرٌ¦64:2:1:هُوَ ٱلَّذِي خَلَقَكُمۡ فَمِنكُمۡ كَافِرࣱ وَمِنكُم مُّؤۡمِنࣱۚ\nT;0;64:2:2:وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ¦64:3:1:خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَصَوَّرَكُمۡ\nT;0;64:3:2:فَأَحۡسَنَ صُوَرَكُمۡۖ وَإِلَيۡهِ ٱلۡمَصِيرُ¦64:4:1:يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ\nT;0;64:4:2:وَيَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ\nT;0;64:5:1:أَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُ فَذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ\nT;0;64:5:2:أَلِيمࣱ¦64:6:1:ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأۡتِيهِمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَقَالُوٓاْ أَبَشَرࣱ\nT;0;64:6:2:يَهۡدُونَنَا فَكَفَرُواْ وَتَوَلَّواْۖ وَّٱسۡتَغۡنَى ٱللَّهُۚ وَٱللَّهُ غَنِيٌّ حَمِيدࣱ¦64:7:1:زَعَمَ ٱلَّذِينَ\nT;0;64:7:0:كَفَرُوٓاْ أَن لَّن يُبۡعَثُواْۚ قُلۡ بَلَىٰ وَرَبِّي لَتُبۡعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلۡتُمۡۚ\nT;0;64:7:2:وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرࣱ¦64:8:1:فَـَٔامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِيٓ أَنزَلۡنَاۚ\nT;0;64:8:2:وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ¦64:9:1:يَوۡمَ يَجۡمَعُكُمۡ لِيَوۡمِ ٱلۡجَمۡعِۖ ذَٰلِكَ يَوۡمُ ٱلتَّغَابُنِۗ\nT;0;64:9:0:وَمَن يُؤۡمِنۢ بِٱللَّهِ وَيَعۡمَلۡ صَٰلِحࣰا يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُدۡخِلۡهُ جَنَّٰتࣲ\nT;0;64:9:2:تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدࣰاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ',
  '28;56;1;\nT;0;64:10:1:وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ\nT;0;64:10:2:أَصۡحَٰبُ ٱلنَّارِ خَٰلِدِينَ فِيهَاۖ وَبِئۡسَ ٱلۡمَصِيرُ\nT;0;64:11:1:مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ\nT;0;64:11:2:يَهۡدِ قَلۡبَهُۥۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمࣱ¦64:12:1:وَأَطِيعُواْ ٱللَّهَ\nT;0;64:12:0:وَأَطِيعُواْ ٱلرَّسُولَۚ فَإِن تَوَلَّيۡتُمۡ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ\nT;0;64:12:2:ٱلۡمُبِينُ¦64:13:1:ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ\nT;0;64:13:2:ٱلۡمُؤۡمِنُونَ¦64:14:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ مِنۡ أَزۡوَٰجِكُمۡ\nT;0;64:14:0:وَأَوۡلَٰدِكُمۡ عَدُوࣰّا لَّكُمۡ فَٱحۡذَرُوهُمۡۚ وَإِن تَعۡفُواْ\nT;0;64:14:2:وَتَصۡفَحُواْ وَتَغۡفِرُواْ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمٌ¦64:15:1:إِنَّمَآ\nT;0;64:15:0:أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةࣱۚ وَٱللَّهُ عِندَهُۥٓ أَجۡرٌ\nT;0;64:15:2:عَظِيمࣱ¦64:16:1:فَٱتَّقُواْ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُواْ وَأَطِيعُواْ\nT;0;64:16:0:وَأَنفِقُواْ خَيۡرࣰا لِّأَنفُسِكُمۡۗ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ\nT;0;64:16:2:فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ¦64:17:1:إِن تُقۡرِضُواْ ٱللَّهَ قَرۡضًا\nT;0;64:17:0:حَسَنࣰا يُضَٰعِفۡهُ لَكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ شَكُورٌ\nT;2;64:17:2:حَلِيمٌ¦64:18:3:عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلۡحَكِيمُ',
  '28;56;2;223\nH;65\nB;65\nT;0;65:1:1:يَٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحۡصُواْ ٱلۡعِدَّةَۖ\nT;0;65:1:0:وَٱتَّقُواْ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخۡرُجۡنَ إِلَّآ أَن\nT;0;65:1:0:يَأۡتِينَ بِفَٰحِشَةࣲ مُّبَيِّنَةࣲۚ وَتِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ\nT;0;65:1:2:فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ لَا تَدۡرِي لَعَلَّ ٱللَّهَ يُحۡدِثُ بَعۡدَ ذَٰلِكَ أَمۡرࣰا\nT;0;65:2:1:فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفࣲ\nT;0;65:2:0:وَأَشۡهِدُواْ ذَوَيۡ عَدۡلࣲ مِّنكُمۡ وَأَقِيمُواْ ٱلشَّهَٰدَةَ لِلَّهِۚ ذَٰلِكُمۡ يُوعَظُ بِهِۦ\nT;0;65:2:2:مَن كَانَ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجࣰا\nT;0;65:3:1:وَيَرۡزُقۡهُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُۚ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓۚ\nT;0;65:3:2:إِنَّ ٱللَّهَ بَٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَيۡءࣲ قَدۡرࣰا¦65:4:1:وَٱلَّٰٓـِٔي يَئِسۡنَ\nT;0;65:4:0:مِنَ ٱلۡمَحِيضِ مِن نِّسَآئِكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشۡهُرࣲ\nT;0;65:4:0:وَٱلَّٰٓـِٔي لَمۡ يَحِضۡنَۚ وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّۚ\nT;0;65:4:2:وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ يُسۡرࣰا¦65:5:1:ذَٰلِكَ أَمۡرُ ٱللَّهِ أَنزَلَهُۥٓ\nT;0;65:5:2:إِلَيۡكُمۡۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُعۡظِمۡ لَهُۥٓ أَجۡرًا',
  '28;56;2;\nT;0;65:6:1:أَسۡكِنُوهُنَّ مِنۡ حَيۡثُ سَكَنتُم مِّن وُجۡدِكُمۡ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُواْ\nT;0;65:6:0:عَلَيۡهِنَّۚ وَإِن كُنَّ أُوْلَٰتِ حَمۡلࣲ فَأَنفِقُواْ عَلَيۡهِنَّ حَتَّىٰ يَضَعۡنَ حَمۡلَهُنَّۚ فَإِنۡ\nT;0;65:6:0:أَرۡضَعۡنَ لَكُمۡ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأۡتَمِرُواْ بَيۡنَكُم بِمَعۡرُوفࣲۖ وَإِن\nT;0;65:6:2:تَعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُۥٓ أُخۡرَىٰ¦65:7:1:لِيُنفِقۡ ذُو سَعَةࣲ مِّن سَعَتِهِۦۖ وَمَن\nT;0;65:7:0:قُدِرَ عَلَيۡهِ رِزۡقُهُۥ فَلۡيُنفِقۡ مِمَّآ ءَاتَىٰهُ ٱللَّهُۚ لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا\nT;0;65:7:2:مَآ ءَاتَىٰهَاۚ سَيَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرࣲ يُسۡرࣰا¦65:8:1:وَكَأَيِّن مِّن قَرۡيَةٍ عَتَتۡ\nT;0;65:8:0:عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبۡنَٰهَا حِسَابࣰا شَدِيدࣰا وَعَذَّبۡنَٰهَا عَذَابࣰا\nT;0;65:8:2:نُّكۡرࣰا¦65:9:3:فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَٰقِبَةُ أَمۡرِهَا خُسۡرًا¦65:10:1:أَعَدَّ ٱللَّهُ\nT;0;65:10:0:لَهُمۡ عَذَابࣰا شَدِيدࣰاۖ فَٱتَّقُواْ ٱللَّهَ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ ٱلَّذِينَ ءَامَنُواْۚ قَدۡ أَنزَلَ\nT;0;65:10:2:ٱللَّهُ إِلَيۡكُمۡ ذِكۡرࣰا¦65:11:1:رَّسُولࣰا يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتࣲ لِّيُخۡرِجَ\nT;0;65:11:0:ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَمَن يُؤۡمِنۢ\nT;0;65:11:0:بِٱللَّهِ وَيَعۡمَلۡ صَٰلِحࣰا يُدۡخِلۡهُ جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ\nT;0;65:11:2:فِيهَآ أَبَدࣰاۖ قَدۡ أَحۡسَنَ ٱللَّهُ لَهُۥ رِزۡقًا¦65:12:1:ٱللَّهُ ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتࣲ\nT;0;65:12:0:وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ يَتَنَزَّلُ ٱلۡأَمۡرُ بَيۡنَهُنَّ لِتَعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَلَىٰ\nT;2;65:12:2:كُلِّ شَيۡءࣲ قَدِيرࣱ وَأَنَّ ٱللَّهَ قَدۡ أَحَاطَ بِكُلِّ شَيۡءٍ عِلۡمَۢا',
  '28;56;3;224\nH;66\nB;66\nT;0;66:1:1:يَٰٓأَيُّهَا ٱلنَّبِيُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِي مَرۡضَاتَ أَزۡوَٰجِكَۚ وَٱللَّهُ\nT;0;66:1:2:غَفُورࣱ رَّحِيمࣱ¦66:2:1:قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَيۡمَٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ\nT;0;66:2:2:ٱلۡعَلِيمُ ٱلۡحَكِيمُ¦66:3:1:وَإِذۡ أَسَرَّ ٱلنَّبِيُّ إِلَىٰ بَعۡضِ أَزۡوَٰجِهِۦ حَدِيثࣰا فَلَمَّا\nT;0;66:3:0:نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَيۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضࣲۖ فَلَمَّا\nT;0;66:3:2:نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَٰذَاۖ قَالَ نَبَّأَنِيَ ٱلۡعَلِيمُ ٱلۡخَبِيرُ¦66:4:1:إِن\nT;0;66:4:0:تَتُوبَآ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَٰهَرَا عَلَيۡهِ فَإِنَّ ٱللَّهَ\nT;0;66:4:0:هُوَ مَوۡلَىٰهُ وَجِبۡرِيلُ وَصَٰلِحُ ٱلۡمُؤۡمِنِينَۖ وَٱلۡمَلَٰٓئِكَةُ بَعۡدَ ذَٰلِكَ\nT;0;66:4:2:ظَهِيرٌ¦66:5:1:عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبۡدِلَهُۥٓ أَزۡوَٰجًا خَيۡرࣰا مِّنكُنَّ\nT;0;66:5:0:مُسۡلِمَٰتࣲ مُّؤۡمِنَٰتࣲ قَٰنِتَٰتࣲ تَٰٓئِبَٰتٍ عَٰبِدَٰتࣲ سَٰٓئِحَٰتࣲ ثَيِّبَٰتࣲ\nT;0;66:5:2:وَأَبۡكَارࣰا¦66:6:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارࣰا\nT;0;66:6:0:وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَيۡهَا مَلَٰٓئِكَةٌ غِلَاظࣱ شِدَادࣱ\nT;0;66:6:2:لَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ¦66:7:1:يَٰٓأَيُّهَا ٱلَّذِينَ\nT;0;66:7:2:كَفَرُواْ لَا تَعۡتَذِرُواْ ٱلۡيَوۡمَۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ',
  '28;56;3;\nT;0;66:8:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ٱللَّهِ تَوۡبَةࣰ نَّصُوحًا عَسَىٰ رَبُّكُمۡ\nT;0;66:8:0:أَن يُكَفِّرَ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيُدۡخِلَكُمۡ جَنَّٰتࣲ تَجۡرِي\nT;0;66:8:0:مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يَوۡمَ لَا يُخۡزِي ٱللَّهُ ٱلنَّبِيَّ وَٱلَّذِينَ ءَامَنُواْ\nT;0;66:8:0:مَعَهُۥۖ نُورُهُمۡ يَسۡعَىٰ بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۡ يَقُولُونَ رَبَّنَآ\nT;0;66:8:2:أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ\nT;0;66:9:1:يَٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ\nT;0;66:9:2:وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ¦66:10:1:ضَرَبَ ٱللَّهُ مَثَلࣰا\nT;0;66:10:0:لِّلَّذِينَ كَفَرُواْ ٱمۡرَأَتَ نُوحࣲ وَٱمۡرَأَتَ لُوطࣲۖ كَانَتَا تَحۡتَ\nT;0;66:10:0:عَبۡدَيۡنِ مِنۡ عِبَادِنَا صَٰلِحَيۡنِ فَخَانَتَاهُمَا فَلَمۡ يُغۡنِيَا عَنۡهُمَا\nT;0;66:10:2:مِنَ ٱللَّهِ شَيۡـࣰٔا وَقِيلَ ٱدۡخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ\nT;0;66:11:1:وَضَرَبَ ٱللَّهُ مَثَلࣰا لِّلَّذِينَ ءَامَنُواْ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ\nT;0;66:11:0:قَالَتۡ رَبِّ ٱبۡنِ لِي عِندَكَ بَيۡتࣰا فِي ٱلۡجَنَّةِ وَنَجِّنِي مِن فِرۡعَوۡنَ\nT;0;66:11:2:وَعَمَلِهِۦ وَنَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ¦66:12:1:وَمَرۡيَمَ ٱبۡنَتَ\nT;0;66:12:0:عِمۡرَٰنَ ٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهِ مِن رُّوحِنَا\nT;2;66:12:2:وَصَدَّقَتۡ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتۡ مِنَ ٱلۡقَٰنِتِينَ',
  '29;57;0;225\nH;67\nB;67\nT;0;67:1:3:تَبَٰرَكَ ٱلَّذِي بِيَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرٌ¦67:2:1:ٱلَّذِي خَلَقَ\nT;0;67:2:2:ٱلۡمَوۡتَ وَٱلۡحَيَوٰةَ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلࣰاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡغَفُورُ\nT;0;67:3:1:ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتࣲ طِبَاقࣰاۖ مَّا تَرَىٰ فِي خَلۡقِ ٱلرَّحۡمَٰنِ مِن\nT;0;67:3:2:تَفَٰوُتࣲۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورࣲ¦67:4:1:ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَيۡنِ\nT;0;67:4:2:يَنقَلِبۡ إِلَيۡكَ ٱلۡبَصَرُ خَاسِئࣰا وَهُوَ حَسِيرࣱ¦67:5:1:وَلَقَدۡ زَيَّنَّا ٱلسَّمَآءَ\nT;0;67:5:0:ٱلدُّنۡيَا بِمَصَٰبِيحَ وَجَعَلۡنَٰهَا رُجُومࣰا لِّلشَّيَٰطِينِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ\nT;0;67:5:2:ٱلسَّعِيرِ¦67:6:3:وَلِلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ عَذَابُ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمَصِيرُ\nT;0;67:7:3:إِذَآ أُلۡقُواْ فِيهَا سَمِعُواْ لَهَا شَهِيقࣰا وَهِيَ تَفُورُ¦67:8:1:تَكَادُ تَمَيَّزُ\nT;0;67:8:2:مِنَ ٱلۡغَيۡظِۖ كُلَّمَآ أُلۡقِيَ فِيهَا فَوۡجࣱ سَأَلَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ نَذِيرࣱ\nT;0;67:9:1:قَالُواْ بَلَىٰ قَدۡ جَآءَنَا نَذِيرࣱ فَكَذَّبۡنَا وَقُلۡنَا مَا نَزَّلَ ٱللَّهُ مِن شَيۡءٍ إِنۡ أَنتُمۡ\nT;0;67:9:2:إِلَّا فِي ضَلَٰلࣲ كَبِيرࣲ¦67:10:1:وَقَالُواْ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِيٓ أَصۡحَٰبِ\nT;0;67:10:2:ٱلسَّعِيرِ¦67:11:3:فَٱعۡتَرَفُواْ بِذَنۢبِهِمۡ فَسُحۡقࣰا لِّأَصۡحَٰبِ ٱلسَّعِيرِ¦67:12:1:إِنَّ\nT;0;67:12:2:ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِيرࣱ',
  '29;57;0;\nT;0;67:13:3:وَأَسِرُّواْ قَوۡلَكُمۡ أَوِ ٱجۡهَرُواْ بِهِۦٓۖ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ¦67:14:1:أَلَا\nT;0;67:14:2:يَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ¦67:15:1:هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ\nT;0;67:15:2:ذَلُولࣰا فَٱمۡشُواْ فِي مَنَاكِبِهَا وَكُلُواْ مِن رِّزۡقِهِۦۖ وَإِلَيۡهِ ٱلنُّشُورُ\nT;0;67:16:3:ءَأَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِيَ تَمُورُ\nT;0;67:17:1:أَمۡ أَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يُرۡسِلَ عَلَيۡكُمۡ حَاصِبࣰاۖ فَسَتَعۡلَمُونَ\nT;0;67:17:2:كَيۡفَ نَذِيرِ¦67:18:3:وَلَقَدۡ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَكَيۡفَ كَانَ نَكِيرِ\nT;0;67:19:1:أَوَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ فَوۡقَهُمۡ صَٰٓفَّٰتࣲ وَيَقۡبِضۡنَۚ مَا يُمۡسِكُهُنَّ إِلَّا\nT;0;67:19:2:ٱلرَّحۡمَٰنُۚ إِنَّهُۥ بِكُلِّ شَيۡءِۭ بَصِيرٌ¦67:20:1:أَمَّنۡ هَٰذَا ٱلَّذِي هُوَ جُندࣱ لَّكُمۡ\nT;0;67:20:2:يَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَٰنِۚ إِنِ ٱلۡكَٰفِرُونَ إِلَّا فِي غُرُورٍ¦67:21:1:أَمَّنۡ هَٰذَا\nT;0;67:21:2:ٱلَّذِي يَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّواْ فِي عُتُوࣲّ وَنُفُورٍ¦67:22:1:أَفَمَن\nT;0;67:22:0:يَمۡشِي مُكِبًّا عَلَىٰ وَجۡهِهِۦٓ أَهۡدَىٰٓ أَمَّن يَمۡشِي سَوِيًّا عَلَىٰ صِرَٰطࣲ\nT;0;67:22:2:مُّسۡتَقِيمࣲ¦67:23:1:قُلۡ هُوَ ٱلَّذِيٓ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ\nT;0;67:23:2:وَٱلۡأَفۡـِٔدَةَۚ قَلِيلࣰا مَّا تَشۡكُرُونَ¦67:24:1:قُلۡ هُوَ ٱلَّذِي ذَرَأَكُمۡ فِي\nT;0;67:24:2:ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ¦67:25:1:وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ\nT;0;67:25:2:صَٰدِقِينَ¦67:26:3:قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرࣱ مُّبِينࣱ',
  '29;57;0;226\nT;0;67:27:1:فَلَمَّا رَأَوۡهُ زُلۡفَةࣰ سِيٓـَٔتۡ وُجُوهُ ٱلَّذِينَ كَفَرُواْ وَقِيلَ هَٰذَا ٱلَّذِي كُنتُم\nT;0;67:27:2:بِهِۦ تَدَّعُونَ¦67:28:1:قُلۡ أَرَءَيۡتُمۡ إِنۡ أَهۡلَكَنِيَ ٱللَّهُ وَمَن مَّعِيَ أَوۡ رَحِمَنَا\nT;0;67:28:2:فَمَن يُجِيرُ ٱلۡكَٰفِرِينَ مِنۡ عَذَابٍ أَلِيمࣲ¦67:29:1:قُلۡ هُوَ ٱلرَّحۡمَٰنُ\nT;0;67:29:2:ءَامَنَّا بِهِۦ وَعَلَيۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِي ضَلَٰلࣲ مُّبِينࣲ\nT;2;67:30:3:قُلۡ أَرَءَيۡتُمۡ إِنۡ أَصۡبَحَ مَآؤُكُمۡ غَوۡرࣰا فَمَن يَأۡتِيكُم بِمَآءࣲ مَّعِينِۭ\nH;68\nB;68\nT;0;68:1:3:نٓۚ وَٱلۡقَلَمِ وَمَا يَسۡطُرُونَ¦68:2:3:مَآ أَنتَ بِنِعۡمَةِ رَبِّكَ بِمَجۡنُونࣲ¦68:3:1:وَإِنَّ\nT;0;68:3:2:لَكَ لَأَجۡرًا غَيۡرَ مَمۡنُونࣲ¦68:4:3:وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمࣲ¦68:5:1:فَسَتُبۡصِرُ\nT;0;68:5:2:وَيُبۡصِرُونَ¦68:6:3:بِأَييِّكُمُ ٱلۡمَفۡتُونُ¦68:7:1:إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ\nT;0;68:7:2:عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ¦68:8:3:فَلَا تُطِعِ ٱلۡمُكَذِّبِينَ\nT;0;68:9:3:وَدُّواْ لَوۡ تُدۡهِنُ فَيُدۡهِنُونَ¦68:10:3:وَلَا تُطِعۡ كُلَّ حَلَّافࣲ مَّهِينٍ\nT;0;68:11:3:هَمَّازࣲ مَّشَّآءِۭ بِنَمِيمࣲ¦68:12:3:مَّنَّاعࣲ لِّلۡخَيۡرِ مُعۡتَدٍ أَثِيمٍ\nT;0;68:13:3:عُتُلِّۭ بَعۡدَ ذَٰلِكَ زَنِيمٍ¦68:14:3:أَن كَانَ ذَا مَالࣲ وَبَنِينَ¦68:15:1:إِذَا تُتۡلَىٰ عَلَيۡهِ\nT;0;68:15:2:ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ¦68:16:3:سَنَسِمُهُۥ عَلَى ٱلۡخُرۡطُومِ',
  '29;57;1;\nT;0;68:17:3:إِنَّا بَلَوۡنَٰهُمۡ كَمَا بَلَوۡنَآ أَصۡحَٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُواْ لَيَصۡرِمُنَّهَا مُصۡبِحِينَ¦68:18:1:وَلَا\nT;0;68:18:2:يَسۡتَثۡنُونَ¦68:19:3:فَطَافَ عَلَيۡهَا طَآئِفࣱ مِّن رَّبِّكَ وَهُمۡ نَآئِمُونَ¦68:20:1:فَأَصۡبَحَتۡ\nT;0;68:20:2:كَٱلصَّرِيمِ¦68:21:3:فَتَنَادَوۡاْ مُصۡبِحِينَ¦68:22:1:أَنِ ٱغۡدُواْ عَلَىٰ حَرۡثِكُمۡ إِن كُنتُمۡ\nT;0;68:22:2:صَٰرِمِينَ¦68:23:3:فَٱنطَلَقُواْ وَهُمۡ يَتَخَٰفَتُونَ¦68:24:1:أَن لَّا يَدۡخُلَنَّهَا ٱلۡيَوۡمَ عَلَيۡكُم\nT;0;68:24:2:مِّسۡكِينࣱ¦68:25:3:وَغَدَوۡاْ عَلَىٰ حَرۡدࣲ قَٰدِرِينَ¦68:26:1:فَلَمَّا رَأَوۡهَا قَالُوٓاْ إِنَّا\nT;0;68:26:2:لَضَآلُّونَ¦68:27:3:بَلۡ نَحۡنُ مَحۡرُومُونَ¦68:28:1:قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا\nT;0;68:28:2:تُسَبِّحُونَ¦68:29:3:قَالُواْ سُبۡحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ¦68:30:1:فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ\nT;0;68:30:2:بَعۡضࣲ يَتَلَٰوَمُونَ¦68:31:3:قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا طَٰغِينَ¦68:32:1:عَسَىٰ رَبُّنَآ أَن يُبۡدِلَنَا\nT;0;68:32:2:خَيۡرࣰا مِّنۡهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ¦68:33:1:كَذَٰلِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ\nT;0;68:33:2:أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ¦68:34:3:إِنَّ لِلۡمُتَّقِينَ عِندَ رَبِّهِمۡ جَنَّٰتِ ٱلنَّعِيمِ\nT;0;68:35:3:أَفَنَجۡعَلُ ٱلۡمُسۡلِمِينَ كَٱلۡمُجۡرِمِينَ¦68:36:3:مَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ¦68:37:1:أَمۡ لَكُمۡ\nT;0;68:37:2:كِتَٰبࣱ فِيهِ تَدۡرُسُونَ¦68:38:3:إِنَّ لَكُمۡ فِيهِ لَمَا تَخَيَّرُونَ¦68:39:1:أَمۡ لَكُمۡ أَيۡمَٰنٌ عَلَيۡنَا\nT;0;68:39:2:بَٰلِغَةٌ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ إِنَّ لَكُمۡ لَمَا تَحۡكُمُونَ¦68:40:1:سَلۡهُمۡ أَيُّهُم بِذَٰلِكَ\nT;0;68:40:2:زَعِيمٌ¦68:41:3:أَمۡ لَهُمۡ شُرَكَآءُ فَلۡيَأۡتُواْ بِشُرَكَآئِهِمۡ إِن كَانُواْ صَٰدِقِينَ¦68:42:1:يَوۡمَ\nT;0;68:42:2:يُكۡشَفُ عَن سَاقࣲ وَيُدۡعَوۡنَ إِلَى ٱلسُّجُودِ فَلَا يَسۡتَطِيعُونَ',
  '29;57;1;227\nT;0;68:43:1:خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةࣱۖ وَقَدۡ كَانُواْ يُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ\nT;0;68:43:2:سَٰلِمُونَ¦68:44:1:فَذَرۡنِي وَمَن يُكَذِّبُ بِهَٰذَا ٱلۡحَدِيثِۖ سَنَسۡتَدۡرِجُهُم\nT;0;68:44:2:مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ¦68:45:3:وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ¦68:46:1:أَمۡ تَسۡـَٔلُهُمۡ\nT;0;68:46:2:أَجۡرࣰا فَهُم مِّن مَّغۡرَمࣲ مُّثۡقَلُونَ¦68:47:3:أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ\nT;0;68:48:1:فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ\nT;0;68:48:2:وَهُوَ مَكۡظُومࣱ¦68:49:1:لَّوۡلَآ أَن تَدَٰرَكَهُۥ نِعۡمَةࣱ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَآءِ\nT;0;68:49:2:وَهُوَ مَذۡمُومࣱ¦68:50:3:فَٱجۡتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ\nT;0;68:51:1:وَإِن يَكَادُ ٱلَّذِينَ كَفَرُواْ لَيُزۡلِقُونَكَ بِأَبۡصَٰرِهِمۡ لَمَّا سَمِعُواْ\nT;2;68:51:2:ٱلذِّكۡرَ وَيَقُولُونَ إِنَّهُۥ لَمَجۡنُونࣱ¦68:52:3:وَمَا هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَٰلَمِينَ\nH;69\nB;69\nT;0;69:1:3:ٱلۡحَآقَّةُ¦69:2:3:مَا ٱلۡحَآقَّةُ¦69:3:3:وَمَآ أَدۡرَىٰكَ مَا ٱلۡحَآقَّةُ¦69:4:1:كَذَّبَتۡ ثَمُودُ وَعَادُۢ\nT;0;69:4:2:بِٱلۡقَارِعَةِ¦69:5:3:فَأَمَّا ثَمُودُ فَأُهۡلِكُواْ بِٱلطَّاغِيَةِ¦69:6:1:وَأَمَّا عَادࣱ فَأُهۡلِكُواْ بِرِيحࣲ\nT;0;69:6:2:صَرۡصَرٍ عَاتِيَةࣲ¦69:7:1:سَخَّرَهَا عَلَيۡهِمۡ سَبۡعَ لَيَالࣲ وَثَمَٰنِيَةَ أَيَّامٍ حُسُومࣰاۖ فَتَرَى\nT;0;69:7:2:ٱلۡقَوۡمَ فِيهَا صَرۡعَىٰ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٍ خَاوِيَةࣲ¦69:8:3:فَهَلۡ تَرَىٰ لَهُم مِّنۢ بَاقِيَةࣲ',
  '29;57;2;\nT;0;69:9:3:وَجَآءَ فِرۡعَوۡنُ وَمَن قَبۡلَهُۥ وَٱلۡمُؤۡتَفِكَٰتُ بِٱلۡخَاطِئَةِ¦69:10:1:فَعَصَوۡاْ رَسُولَ\nT;0;69:10:2:رَبِّهِمۡ فَأَخَذَهُمۡ أَخۡذَةࣰ رَّابِيَةً¦69:11:1:إِنَّا لَمَّا طَغَا ٱلۡمَآءُ حَمَلۡنَٰكُمۡ فِي\nT;0;69:11:2:ٱلۡجَارِيَةِ¦69:12:3:لِنَجۡعَلَهَا لَكُمۡ تَذۡكِرَةࣰ وَتَعِيَهَآ أُذُنࣱ وَٰعِيَةࣱ¦69:13:1:فَإِذَا نُفِخَ\nT;0;69:13:2:فِي ٱلصُّورِ نَفۡخَةࣱ وَٰحِدَةࣱ¦69:14:1:وَحُمِلَتِ ٱلۡأَرۡضُ وَٱلۡجِبَالُ فَدُكَّتَا دَكَّةࣰ\nT;0;69:14:2:وَٰحِدَةࣰ¦69:15:3:فَيَوۡمَئِذࣲ وَقَعَتِ ٱلۡوَاقِعَةُ¦69:16:1:وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِيَ يَوۡمَئِذࣲ\nT;0;69:16:2:وَاهِيَةࣱ¦69:17:1:وَٱلۡمَلَكُ عَلَىٰٓ أَرۡجَآئِهَاۚ وَيَحۡمِلُ عَرۡشَ رَبِّكَ فَوۡقَهُمۡ يَوۡمَئِذࣲ\nT;0;69:17:2:ثَمَٰنِيَةࣱ¦69:18:3:يَوۡمَئِذࣲ تُعۡرَضُونَ لَا تَخۡفَىٰ مِنكُمۡ خَافِيَةࣱ¦69:19:1:فَأَمَّا مَنۡ أُوتِيَ\nT;0;69:19:2:كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقۡرَءُواْ كِتَٰبِيَهۡ¦69:20:1:إِنِّي ظَنَنتُ أَنِّي مُلَٰقٍ\nT;0;69:20:2:حِسَابِيَهۡ¦69:21:3:فَهُوَ فِي عِيشَةࣲ رَّاضِيَةࣲ¦69:22:3:فِي جَنَّةٍ عَالِيَةࣲ¦69:23:1:قُطُوفُهَا\nT;0;69:23:2:دَانِيَةࣱ¦69:24:3:كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَآ أَسۡلَفۡتُمۡ فِي ٱلۡأَيَّامِ ٱلۡخَالِيَةِ\nT;0;69:25:3:وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُوتَ كِتَٰبِيَهۡ¦69:26:1:وَلَمۡ أَدۡرِ\nT;0;69:26:2:مَا حِسَابِيَهۡ¦69:27:3:يَٰلَيۡتَهَا كَانَتِ ٱلۡقَاضِيَةَ¦69:28:3:مَآ أَغۡنَىٰ عَنِّي مَالِيَهۡۜ¦69:29:1:هَلَكَ\nT;0;69:29:2:عَنِّي سُلۡطَٰنِيَهۡ¦69:30:3:خُذُوهُ فَغُلُّوهُ¦69:31:3:ثُمَّ ٱلۡجَحِيمَ صَلُّوهُ¦69:32:1:ثُمَّ فِي سِلۡسِلَةࣲ\nT;0;69:32:2:ذَرۡعُهَا سَبۡعُونَ ذِرَاعࣰا فَٱسۡلُكُوهُ¦69:33:3:إِنَّهُۥ كَانَ لَا يُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِيمِ\nT;0;69:34:3:وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ¦69:35:3:فَلَيۡسَ لَهُ ٱلۡيَوۡمَ هَٰهُنَا حَمِيمࣱ',
  '29;57;2;\nT;0;69:36:3:وَلَا طَعَامٌ إِلَّا مِنۡ غِسۡلِينࣲ¦69:37:3:لَّا يَأۡكُلُهُۥٓ إِلَّا ٱلۡخَٰطِـُٔونَ¦69:38:1:فَلَآ أُقۡسِمُ بِمَا\nT;0;69:38:2:تُبۡصِرُونَ¦69:39:3:وَمَا لَا تُبۡصِرُونَ¦69:40:3:إِنَّهُۥ لَقَوۡلُ رَسُولࣲ كَرِيمࣲ¦69:41:1:وَمَا هُوَ بِقَوۡلِ\nT;0;69:41:2:شَاعِرࣲۚ قَلِيلࣰا مَّا تُؤۡمِنُونَ¦69:42:3:وَلَا بِقَوۡلِ كَاهِنࣲۚ قَلِيلࣰا مَّا تَذَكَّرُونَ\nT;0;69:43:3:تَنزِيلࣱ مِّن رَّبِّ ٱلۡعَٰلَمِينَ¦69:44:3:وَلَوۡ تَقَوَّلَ عَلَيۡنَا بَعۡضَ ٱلۡأَقَاوِيلِ\nT;0;69:45:3:لَأَخَذۡنَا مِنۡهُ بِٱلۡيَمِينِ¦69:46:3:ثُمَّ لَقَطَعۡنَا مِنۡهُ ٱلۡوَتِينَ¦69:47:1:فَمَا مِنكُم\nT;0;69:47:2:مِّنۡ أَحَدٍ عَنۡهُ حَٰجِزِينَ¦69:48:3:وَإِنَّهُۥ لَتَذۡكِرَةࣱ لِّلۡمُتَّقِينَ¦69:49:1:وَإِنَّا\nT;0;69:49:2:لَنَعۡلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ¦69:50:3:وَإِنَّهُۥ لَحَسۡرَةٌ عَلَى ٱلۡكَٰفِرِينَ\nT;2;69:51:3:وَإِنَّهُۥ لَحَقُّ ٱلۡيَقِينِ¦69:52:3:فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ\nH;70\nB;70\nT;0;70:1:3:سَأَلَ سَآئِلُۢ بِعَذَابࣲ وَاقِعࣲ¦70:2:3:لِّلۡكَٰفِرِينَ لَيۡسَ لَهُۥ دَافِعࣱ\nT;0;70:3:3:مِّنَ ٱللَّهِ ذِي ٱلۡمَعَارِجِ¦70:4:1:تَعۡرُجُ ٱلۡمَلَٰٓئِكَةُ وَٱلرُّوحُ إِلَيۡهِ فِي\nT;0;70:4:2:يَوۡمࣲ كَانَ مِقۡدَارُهُۥ خَمۡسِينَ أَلۡفَ سَنَةࣲ¦70:5:3:فَٱصۡبِرۡ صَبۡرࣰا جَمِيلًا\nT;0;70:6:3:إِنَّهُمۡ يَرَوۡنَهُۥ بَعِيدࣰا¦70:7:3:وَنَرَىٰهُ قَرِيبࣰا¦70:8:1:يَوۡمَ تَكُونُ ٱلسَّمَآءُ\nT;0;70:8:2:كَٱلۡمُهۡلِ¦70:9:3:وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ¦70:10:3:وَلَا يَسۡـَٔلُ حَمِيمٌ حَمِيمࣰا',
  '29;57;2;228\nT;0;70:11:3:يُبَصَّرُونَهُمۡۚ يَوَدُّ ٱلۡمُجۡرِمُ لَوۡ يَفۡتَدِي مِنۡ عَذَابِ يَوۡمِئِذِۭ بِبَنِيهِ\nT;0;70:12:3:وَصَٰحِبَتِهِۦ وَأَخِيهِ¦70:13:3:وَفَصِيلَتِهِ ٱلَّتِي تُـٔۡوِيهِ¦70:14:1:وَمَن فِي ٱلۡأَرۡضِ جَمِيعࣰا\nT;0;70:14:2:ثُمَّ يُنجِيهِ¦70:15:3:كَلَّآۖ إِنَّهَا لَظَىٰ¦70:16:3:نَزَّاعَةࣰ لِّلشَّوَىٰ¦70:17:1:تَدۡعُواْ مَنۡ أَدۡبَرَ\nT;0;70:17:2:وَتَوَلَّىٰ¦70:18:3:وَجَمَعَ فَأَوۡعَىٰٓ¦70:19:3:۞ إِنَّ ٱلۡإِنسَٰنَ خُلِقَ هَلُوعًا¦70:20:1:إِذَا مَسَّهُ ٱلشَّرُّ\nT;0;70:20:2:جَزُوعࣰا¦70:21:3:وَإِذَا مَسَّهُ ٱلۡخَيۡرُ مَنُوعًا¦70:22:3:إِلَّا ٱلۡمُصَلِّينَ¦70:23:1:ٱلَّذِينَ هُمۡ\nT;0;70:23:2:عَلَىٰ صَلَاتِهِمۡ دَآئِمُونَ¦70:24:3:وَٱلَّذِينَ فِيٓ أَمۡوَٰلِهِمۡ حَقࣱّ مَّعۡلُومࣱ¦70:25:1:لِّلسَّآئِلِ\nT;0;70:25:2:وَٱلۡمَحۡرُومِ¦70:26:3:وَٱلَّذِينَ يُصَدِّقُونَ بِيَوۡمِ ٱلدِّينِ¦70:27:1:وَٱلَّذِينَ هُم مِّنۡ عَذَابِ\nT;0;70:27:2:رَبِّهِم مُّشۡفِقُونَ¦70:28:3:إِنَّ عَذَابَ رَبِّهِمۡ غَيۡرُ مَأۡمُونࣲ¦70:29:1:وَٱلَّذِينَ هُمۡ\nT;0;70:29:2:لِفُرُوجِهِمۡ حَٰفِظُونَ¦70:30:1:إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ\nT;0;70:30:2:غَيۡرُ مَلُومِينَ¦70:31:3:فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡعَادُونَ¦70:32:1:وَٱلَّذِينَ\nT;0;70:32:2:هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ¦70:33:3:وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمۡ قَآئِمُونَ\nT;0;70:34:3:وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ¦70:35:3:أُوْلَٰٓئِكَ فِي جَنَّٰتࣲ مُّكۡرَمُونَ\nT;0;70:36:3:فَمَالِ ٱلَّذِينَ كَفَرُواْ قِبَلَكَ مُهۡطِعِينَ¦70:37:1:عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ\nT;0;70:37:2:عِزِينَ¦70:38:3:أَيَطۡمَعُ كُلُّ ٱمۡرِيࣲٕ مِّنۡهُمۡ أَن يُدۡخَلَ جَنَّةَ نَعِيمࣲ¦70:39:1:كَلَّآۖ إِنَّا خَلَقۡنَٰهُم\nT;0;70:39:2:مِّمَّا يَعۡلَمُونَ¦70:40:3:فَلَآ أُقۡسِمُ بِرَبِّ ٱلۡمَشَٰرِقِ وَٱلۡمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ',
  '29;57;3;\nT;0;70:41:3:عَلَىٰٓ أَن نُّبَدِّلَ خَيۡرࣰا مِّنۡهُمۡ وَمَا نَحۡنُ بِمَسۡبُوقِينَ¦70:42:1:فَذَرۡهُمۡ\nT;0;70:42:2:يَخُوضُواْ وَيَلۡعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي يُوعَدُونَ¦70:43:1:يَوۡمَ\nT;0;70:43:2:يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ سِرَاعࣰا كَأَنَّهُمۡ إِلَىٰ نُصُبࣲ يُوفِضُونَ\nT;2;70:44:3:خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةࣱۚ ذَٰلِكَ ٱلۡيَوۡمُ ٱلَّذِي كَانُواْ يُوعَدُونَ\nH;71\nB;71\nT;0;71:1:1:إِنَّآ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ أَنۡ أَنذِرۡ قَوۡمَكَ مِن قَبۡلِ أَن يَأۡتِيَهُمۡ\nT;0;71:1:2:عَذَابٌ أَلِيمࣱ¦71:2:3:قَالَ يَٰقَوۡمِ إِنِّي لَكُمۡ نَذِيرࣱ مُّبِينٌ¦71:3:1:أَنِ ٱعۡبُدُواْ\nT;0;71:3:2:ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ¦71:4:1:يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرۡكُمۡ\nT;0;71:4:2:إِلَىٰٓ أَجَلࣲ مُّسَمًّىۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُۚ لَوۡ كُنتُمۡ تَعۡلَمُونَ\nT;0;71:5:3:قَالَ رَبِّ إِنِّي دَعَوۡتُ قَوۡمِي لَيۡلࣰا وَنَهَارࣰا¦71:6:1:فَلَمۡ يَزِدۡهُمۡ دُعَآءِيٓ إِلَّا\nT;0;71:6:2:فِرَارࣰا¦71:7:1:وَإِنِّي كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَلُوٓاْ أَصَٰبِعَهُمۡ فِيٓ\nT;0;71:7:2:ءَاذَانِهِمۡ وَٱسۡتَغۡشَوۡاْ ثِيَابَهُمۡ وَأَصَرُّواْ وَٱسۡتَكۡبَرُواْ ٱسۡتِكۡبَارࣰا\nT;0;71:8:3:ثُمَّ إِنِّي دَعَوۡتُهُمۡ جِهَارࣰا¦71:9:1:ثُمَّ إِنِّيٓ أَعۡلَنتُ لَهُمۡ وَأَسۡرَرۡتُ\nT;0;71:9:2:لَهُمۡ إِسۡرَارࣰا¦71:10:3:فَقُلۡتُ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارࣰا',
  '29;57;3;\nT;0;71:11:3:يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارࣰا¦71:12:1:وَيُمۡدِدۡكُم بِأَمۡوَٰلࣲ وَبَنِينَ وَيَجۡعَل\nT;0;71:12:2:لَّكُمۡ جَنَّٰتࣲ وَيَجۡعَل لَّكُمۡ أَنۡهَٰرࣰا¦71:13:3:مَّا لَكُمۡ لَا تَرۡجُونَ لِلَّهِ وَقَارࣰا\nT;0;71:14:3:وَقَدۡ خَلَقَكُمۡ أَطۡوَارًا¦71:15:1:أَلَمۡ تَرَوۡاْ كَيۡفَ خَلَقَ ٱللَّهُ سَبۡعَ سَمَٰوَٰتࣲ\nT;0;71:15:2:طِبَاقࣰا¦71:16:3:وَجَعَلَ ٱلۡقَمَرَ فِيهِنَّ نُورࣰا وَجَعَلَ ٱلشَّمۡسَ سِرَاجࣰا\nT;0;71:17:3:وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلۡأَرۡضِ نَبَاتࣰا¦71:18:1:ثُمَّ يُعِيدُكُمۡ فِيهَا وَيُخۡرِجُكُمۡ\nT;0;71:18:2:إِخۡرَاجࣰا¦71:19:3:وَٱللَّهُ جَعَلَ لَكُمُ ٱلۡأَرۡضَ بِسَاطࣰا¦71:20:1:لِّتَسۡلُكُواْ مِنۡهَا\nT;0;71:20:2:سُبُلࣰا فِجَاجࣰا¦71:21:1:قَالَ نُوحࣱ رَّبِّ إِنَّهُمۡ عَصَوۡنِي وَٱتَّبَعُواْ مَن لَّمۡ يَزِدۡهُ\nT;0;71:21:2:مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارࣰا¦71:22:3:وَمَكَرُواْ مَكۡرࣰا كُبَّارࣰا¦71:23:1:وَقَالُواْ\nT;0;71:23:0:لَا تَذَرُنَّ ءَالِهَتَكُمۡ وَلَا تَذَرُنَّ وَدࣰّا وَلَا سُوَاعࣰا وَلَا يَغُوثَ وَيَعُوقَ\nT;0;71:23:2:وَنَسۡرࣰا¦71:24:3:وَقَدۡ أَضَلُّواْ كَثِيرࣰاۖ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا ضَلَٰلࣰا\nT;0;71:25:1:مِّمَّا خَطِيٓـَٰٔتِهِمۡ أُغۡرِقُواْ فَأُدۡخِلُواْ نَارࣰا فَلَمۡ يَجِدُواْ لَهُم مِّن دُونِ\nT;0;71:25:2:ٱللَّهِ أَنصَارࣰا¦71:26:1:وَقَالَ نُوحࣱ رَّبِّ لَا تَذَرۡ عَلَى ٱلۡأَرۡضِ مِنَ ٱلۡكَٰفِرِينَ\nT;0;71:26:2:دَيَّارًا¦71:27:1:إِنَّكَ إِن تَذَرۡهُمۡ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُوٓاْ إِلَّا فَاجِرࣰا\nT;0;71:27:2:كَفَّارࣰا¦71:28:1:رَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيۡتِيَ مُؤۡمِنࣰا\nT;2;71:28:2:وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۖ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا تَبَارَۢا',
  '29;58;0;229\nH;72\nB;72\nT;0;72:1:1:قُلۡ أُوحِيَ إِلَيَّ أَنَّهُ ٱسۡتَمَعَ نَفَرࣱ مِّنَ ٱلۡجِنِّ فَقَالُوٓاْ إِنَّا سَمِعۡنَا قُرۡءَانًا\nT;0;72:1:2:عَجَبࣰا¦72:2:3:يَهۡدِيٓ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَآ أَحَدࣰا\nT;0;72:3:3:وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةࣰ وَلَا وَلَدࣰا¦72:4:1:وَأَنَّهُۥ كَانَ\nT;0;72:4:2:يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطࣰا¦72:5:1:وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلۡإِنسُ\nT;0;72:5:2:وَٱلۡجِنُّ عَلَى ٱللَّهِ كَذِبࣰا¦72:6:1:وَأَنَّهُۥ كَانَ رِجَالࣱ مِّنَ ٱلۡإِنسِ يَعُوذُونَ بِرِجَالࣲ\nT;0;72:6:2:مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقࣰا¦72:7:1:وَأَنَّهُمۡ ظَنُّواْ كَمَا ظَنَنتُمۡ أَن لَّن يَبۡعَثَ\nT;0;72:7:2:ٱللَّهُ أَحَدࣰا¦72:8:1:وَأَنَّا لَمَسۡنَا ٱلسَّمَآءَ فَوَجَدۡنَٰهَا مُلِئَتۡ حَرَسࣰا\nT;0;72:8:2:شَدِيدࣰا وَشُهُبࣰا¦72:9:1:وَأَنَّا كُنَّا نَقۡعُدُ مِنۡهَا مَقَٰعِدَ لِلسَّمۡعِۖ فَمَن\nT;0;72:9:2:يَسۡتَمِعِ ٱلۡأٓنَ يَجِدۡ لَهُۥ شِهَابࣰا رَّصَدࣰا¦72:10:1:وَأَنَّا لَا نَدۡرِيٓ أَشَرٌّ أُرِيدَ\nT;0;72:10:2:بِمَن فِي ٱلۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدࣰا¦72:11:1:وَأَنَّا مِنَّا ٱلصَّٰلِحُونَ\nT;0;72:11:2:وَمِنَّا دُونَ ذَٰلِكَۖ كُنَّا طَرَآئِقَ قِدَدࣰا¦72:12:1:وَأَنَّا ظَنَنَّآ أَن لَّن نُّعۡجِزَ\nT;0;72:12:2:ٱللَّهَ فِي ٱلۡأَرۡضِ وَلَن نُّعۡجِزَهُۥ هَرَبࣰا¦72:13:1:وَأَنَّا لَمَّا سَمِعۡنَا ٱلۡهُدَىٰٓ\nT;0;72:13:2:ءَامَنَّا بِهِۦۖ فَمَن يُؤۡمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخۡسࣰا وَلَا رَهَقࣰا',
  '29;58;0;\nT;0;72:14:1:وَأَنَّا مِنَّا ٱلۡمُسۡلِمُونَ وَمِنَّا ٱلۡقَٰسِطُونَۖ فَمَنۡ أَسۡلَمَ فَأُوْلَٰٓئِكَ\nT;0;72:14:2:تَحَرَّوۡاْ رَشَدࣰا¦72:15:3:وَأَمَّا ٱلۡقَٰسِطُونَ فَكَانُواْ لِجَهَنَّمَ حَطَبࣰا\nT;0;72:16:3:وَأَلَّوِ ٱسۡتَقَٰمُواْ عَلَى ٱلطَّرِيقَةِ لَأَسۡقَيۡنَٰهُم مَّآءً غَدَقࣰا¦72:17:1:لِّنَفۡتِنَهُمۡ\nT;0;72:17:2:فِيهِۚ وَمَن يُعۡرِضۡ عَن ذِكۡرِ رَبِّهِۦ يَسۡلُكۡهُ عَذَابࣰا صَعَدࣰا¦72:18:1:وَأَنَّ\nT;0;72:18:2:ٱلۡمَسَٰجِدَ لِلَّهِ فَلَا تَدۡعُواْ مَعَ ٱللَّهِ أَحَدࣰا¦72:19:1:وَأَنَّهُۥ لَمَّا قَامَ عَبۡدُ ٱللَّهِ\nT;0;72:19:2:يَدۡعُوهُ كَادُواْ يَكُونُونَ عَلَيۡهِ لِبَدࣰا¦72:20:1:قُلۡ إِنَّمَآ أَدۡعُواْ رَبِّي وَلَآ أُشۡرِكُ\nT;0;72:20:2:بِهِۦٓ أَحَدࣰا¦72:21:3:قُلۡ إِنِّي لَآ أَمۡلِكُ لَكُمۡ ضَرࣰّا وَلَا رَشَدࣰا¦72:22:1:قُلۡ إِنِّي\nT;0;72:22:2:لَن يُجِيرَنِي مِنَ ٱللَّهِ أَحَدࣱ وَلَنۡ أَجِدَ مِن دُونِهِۦ مُلۡتَحَدًا¦72:23:1:إِلَّا بَلَٰغࣰا\nT;0;72:23:0:مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦۚ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ\nT;0;72:23:2:خَٰلِدِينَ فِيهَآ أَبَدًا¦72:24:1:حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ فَسَيَعۡلَمُونَ\nT;0;72:24:2:مَنۡ أَضۡعَفُ نَاصِرࣰا وَأَقَلُّ عَدَدࣰا¦72:25:1:قُلۡ إِنۡ أَدۡرِيٓ أَقَرِيبࣱ مَّا تُوعَدُونَ\nT;0;72:25:2:أَمۡ يَجۡعَلُ لَهُۥ رَبِّيٓ أَمَدًا¦72:26:1:عَٰلِمُ ٱلۡغَيۡبِ فَلَا يُظۡهِرُ عَلَىٰ غَيۡبِهِۦٓ\nT;0;72:26:2:أَحَدًا¦72:27:1:إِلَّا مَنِ ٱرۡتَضَىٰ مِن رَّسُولࣲ فَإِنَّهُۥ يَسۡلُكُ مِنۢ بَيۡنِ\nT;0;72:27:2:يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ رَصَدࣰا¦72:28:1:لِّيَعۡلَمَ أَن قَدۡ أَبۡلَغُواْ رِسَٰلَٰتِ\nT;2;72:28:2:رَبِّهِمۡ وَأَحَاطَ بِمَا لَدَيۡهِمۡ وَأَحۡصَىٰ كُلَّ شَيۡءٍ عَدَدَۢا',
  '29;58;0;\nH;73\nB;73\nT;0;73:1:3:يَٰٓأَيُّهَا ٱلۡمُزَّمِّلُ¦73:2:3:قُمِ ٱلَّيۡلَ إِلَّا قَلِيلࣰا¦73:3:3:نِّصۡفَهُۥٓ أَوِ ٱنقُصۡ مِنۡهُ قَلِيلًا\nT;0;73:4:3:أَوۡ زِدۡ عَلَيۡهِ وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِيلًا¦73:5:1:إِنَّا سَنُلۡقِي عَلَيۡكَ قَوۡلࣰا\nT;0;73:5:2:ثَقِيلًا¦73:6:3:إِنَّ نَاشِئَةَ ٱلَّيۡلِ هِيَ أَشَدُّ وَطۡـࣰٔا وَأَقۡوَمُ قِيلًا¦73:7:1:إِنَّ لَكَ فِي\nT;0;73:7:2:ٱلنَّهَارِ سَبۡحࣰا طَوِيلࣰا¦73:8:3:وَٱذۡكُرِ ٱسۡمَ رَبِّكَ وَتَبَتَّلۡ إِلَيۡهِ تَبۡتِيلࣰا\nT;0;73:9:3:رَّبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذۡهُ وَكِيلࣰا¦73:10:1:وَٱصۡبِرۡ\nT;0;73:10:2:عَلَىٰ مَا يَقُولُونَ وَٱهۡجُرۡهُمۡ هَجۡرࣰا جَمِيلࣰا¦73:11:1:وَذَرۡنِي وَٱلۡمُكَذِّبِينَ\nT;0;73:11:2:أُوْلِي ٱلنَّعۡمَةِ وَمَهِّلۡهُمۡ قَلِيلًا¦73:12:3:إِنَّ لَدَيۡنَآ أَنكَالࣰا وَجَحِيمࣰا\nT;0;73:13:3:وَطَعَامࣰا ذَا غُصَّةࣲ وَعَذَابًا أَلِيمࣰا¦73:14:1:يَوۡمَ تَرۡجُفُ ٱلۡأَرۡضُ وَٱلۡجِبَالُ\nT;0;73:14:2:وَكَانَتِ ٱلۡجِبَالُ كَثِيبࣰا مَّهِيلًا¦73:15:1:إِنَّآ أَرۡسَلۡنَآ إِلَيۡكُمۡ رَسُولࣰا شَٰهِدًا\nT;0;73:15:2:عَلَيۡكُمۡ كَمَآ أَرۡسَلۡنَآ إِلَىٰ فِرۡعَوۡنَ رَسُولࣰا¦73:16:1:فَعَصَىٰ فِرۡعَوۡنُ ٱلرَّسُولَ\nT;0;73:16:2:فَأَخَذۡنَٰهُ أَخۡذࣰا وَبِيلࣰا¦73:17:1:فَكَيۡفَ تَتَّقُونَ إِن كَفَرۡتُمۡ يَوۡمࣰا\nT;0;73:17:2:يَجۡعَلُ ٱلۡوِلۡدَٰنَ شِيبًا¦73:18:3:ٱلسَّمَآءُ مُنفَطِرُۢ بِهِۦۚ كَانَ وَعۡدُهُۥ مَفۡعُولًا\nT;0;73:19:3:إِنَّ هَٰذِهِۦ تَذۡكِرَةࣱۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا',
  '29;58;1;230\nT;0;73:20:1:۞ إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَيِ ٱلَّيۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةࣱ\nT;0;73:20:0:مِّنَ ٱلَّذِينَ مَعَكَۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ\nT;0;73:20:0:عَلَيۡكُمۡۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ\nT;0;73:20:0:وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ\nT;0;73:20:0:يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنۡهُۚ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ\nT;0;73:20:0:ٱلزَّكَوٰةَ وَأَقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنࣰاۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرࣲ تَجِدُوهُ\nT;2;73:20:2:عِندَ ٱللَّهِ هُوَ خَيۡرࣰا وَأَعۡظَمَ أَجۡرࣰاۚ وَٱسۡتَغۡفِرُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمُۢ\nH;74\nB;74\nT;0;74:1:3:يَٰٓأَيُّهَا ٱلۡمُدَّثِّرُ¦74:2:3:قُمۡ فَأَنذِرۡ¦74:3:3:وَرَبَّكَ فَكَبِّرۡ¦74:4:3:وَثِيَابَكَ فَطَهِّرۡ\nT;0;74:5:3:وَٱلرُّجۡزَ فَٱهۡجُرۡ¦74:6:3:وَلَا تَمۡنُن تَسۡتَكۡثِرُ¦74:7:3:وَلِرَبِّكَ فَٱصۡبِرۡ¦74:8:1:فَإِذَا نُقِرَ\nT;0;74:8:2:فِي ٱلنَّاقُورِ¦74:9:3:فَذَٰلِكَ يَوۡمَئِذࣲ يَوۡمٌ عَسِيرٌ¦74:10:3:عَلَى ٱلۡكَٰفِرِينَ غَيۡرُ يَسِيرࣲ\nT;0;74:11:3:ذَرۡنِي وَمَنۡ خَلَقۡتُ وَحِيدࣰا¦74:12:3:وَجَعَلۡتُ لَهُۥ مَالࣰا مَّمۡدُودࣰا¦74:13:1:وَبَنِينَ\nT;0;74:13:2:شُهُودࣰا¦74:14:3:وَمَهَّدتُّ لَهُۥ تَمۡهِيدࣰا¦74:15:3:ثُمَّ يَطۡمَعُ أَنۡ أَزِيدَ¦74:16:1:كَلَّآۖ إِنَّهُۥ\nT;0;74:16:2:كَانَ لِأٓيَٰتِنَا عَنِيدࣰا¦74:17:3:سَأُرۡهِقُهُۥ صَعُودًا¦74:18:3:إِنَّهُۥ فَكَّرَ وَقَدَّرَ',
  '29;58;1;\nT;0;74:19:3:فَقُتِلَ كَيۡفَ قَدَّرَ¦74:20:3:ثُمَّ قُتِلَ كَيۡفَ قَدَّرَ¦74:21:3:ثُمَّ نَظَرَ¦74:22:3:ثُمَّ عَبَسَ وَبَسَرَ\nT;0;74:23:3:ثُمَّ أَدۡبَرَ وَٱسۡتَكۡبَرَ¦74:24:3:فَقَالَ إِنۡ هَٰذَآ إِلَّا سِحۡرࣱ يُؤۡثَرُ¦74:25:1:إِنۡ هَٰذَآ\nT;0;74:25:2:إِلَّا قَوۡلُ ٱلۡبَشَرِ¦74:26:3:سَأُصۡلِيهِ سَقَرَ¦74:27:3:وَمَآ أَدۡرَىٰكَ مَا سَقَرُ\nT;0;74:28:3:لَا تُبۡقِي وَلَا تَذَرُ¦74:29:3:لَوَّاحَةࣱ لِّلۡبَشَرِ¦74:30:3:عَلَيۡهَا تِسۡعَةَ عَشَرَ¦74:31:1:وَمَا جَعَلۡنَآ\nT;0;74:31:0:أَصۡحَٰبَ ٱلنَّارِ إِلَّا مَلَٰٓئِكَةࣰۖ وَمَا جَعَلۡنَا عِدَّتَهُمۡ إِلَّا فِتۡنَةࣰ لِّلَّذِينَ كَفَرُواْ\nT;0;74:31:0:لِيَسۡتَيۡقِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَيَزۡدَادَ ٱلَّذِينَ ءَامَنُوٓاْ إِيمَٰنࣰا وَلَا يَرۡتَابَ\nT;0;74:31:0:ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡمُؤۡمِنُونَ وَلِيَقُولَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضࣱ\nT;0;74:31:0:وَٱلۡكَٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلࣰاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ\nT;0;74:31:0:وَيَهۡدِي مَن يَشَآءُۚ وَمَا يَعۡلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَۚ وَمَا هِيَ إِلَّا ذِكۡرَىٰ\nT;0;74:31:2:لِلۡبَشَرِ¦74:32:3:كَلَّا وَٱلۡقَمَرِ¦74:33:3:وَٱلَّيۡلِ إِذۡ أَدۡبَرَ¦74:34:3:وَٱلصُّبۡحِ إِذَآ أَسۡفَرَ¦74:35:1:إِنَّهَا\nT;0;74:35:2:لَإِحۡدَى ٱلۡكُبَرِ¦74:36:3:نَذِيرࣰا لِّلۡبَشَرِ¦74:37:3:لِمَن شَآءَ مِنكُمۡ أَن يَتَقَدَّمَ أَوۡ يَتَأَخَّرَ\nT;0;74:38:3:كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ رَهِينَةٌ¦74:39:3:إِلَّآ أَصۡحَٰبَ ٱلۡيَمِينِ¦74:40:1:فِي جَنَّٰتࣲ\nT;0;74:40:2:يَتَسَآءَلُونَ¦74:41:3:عَنِ ٱلۡمُجۡرِمِينَ¦74:42:3:مَا سَلَكَكُمۡ فِي سَقَرَ¦74:43:1:قَالُواْ لَمۡ نَكُ\nT;0;74:43:2:مِنَ ٱلۡمُصَلِّينَ¦74:44:3:وَلَمۡ نَكُ نُطۡعِمُ ٱلۡمِسۡكِينَ¦74:45:1:وَكُنَّا نَخُوضُ مَعَ\nT;0;74:45:2:ٱلۡخَآئِضِينَ¦74:46:3:وَكُنَّا نُكَذِّبُ بِيَوۡمِ ٱلدِّينِ¦74:47:3:حَتَّىٰٓ أَتَىٰنَا ٱلۡيَقِينُ',
  '29;58;1;231\nT;0;74:48:3:فَمَا تَنفَعُهُمۡ شَفَٰعَةُ ٱلشَّٰفِعِينَ¦74:49:1:فَمَا لَهُمۡ عَنِ ٱلتَّذۡكِرَةِ\nT;0;74:49:2:مُعۡرِضِينَ¦74:50:3:كَأَنَّهُمۡ حُمُرࣱ مُّسۡتَنفِرَةࣱ¦74:51:3:فَرَّتۡ مِن قَسۡوَرَةِۭ\nT;0;74:52:3:بَلۡ يُرِيدُ كُلُّ ٱمۡرِيࣲٕ مِّنۡهُمۡ أَن يُؤۡتَىٰ صُحُفࣰا مُّنَشَّرَةࣰ¦74:53:1:كَلَّاۖ بَل لَّا\nT;0;74:53:2:يَخَافُونَ ٱلۡأٓخِرَةَ¦74:54:3:كَلَّآ إِنَّهُۥ تَذۡكِرَةࣱ¦74:55:3:فَمَن شَآءَ ذَكَرَهُۥ¦74:56:1:وَمَا\nT;2;74:56:2:يَذۡكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ هُوَ أَهۡلُ ٱلتَّقۡوَىٰ وَأَهۡلُ ٱلۡمَغۡفِرَةِ\nH;75\nB;75\nT;0;75:1:3:لَآ أُقۡسِمُ بِيَوۡمِ ٱلۡقِيَٰمَةِ¦75:2:3:وَلَآ أُقۡسِمُ بِٱلنَّفۡسِ ٱللَّوَّامَةِ¦75:3:1:أَيَحۡسَبُ\nT;0;75:3:2:ٱلۡإِنسَٰنُ أَلَّن نَّجۡمَعَ عِظَامَهُۥ¦75:4:3:بَلَىٰ قَٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّيَ بَنَانَهُۥ¦75:5:1:بَلۡ\nT;0;75:5:2:يُرِيدُ ٱلۡإِنسَٰنُ لِيَفۡجُرَ أَمَامَهُۥ¦75:6:3:يَسۡـَٔلُ أَيَّانَ يَوۡمُ ٱلۡقِيَٰمَةِ¦75:7:1:فَإِذَا بَرِقَ\nT;0;75:7:2:ٱلۡبَصَرُ¦75:8:3:وَخَسَفَ ٱلۡقَمَرُ¦75:9:3:وَجُمِعَ ٱلشَّمۡسُ وَٱلۡقَمَرُ¦75:10:1:يَقُولُ ٱلۡإِنسَٰنُ\nT;0;75:10:2:يَوۡمَئِذٍ أَيۡنَ ٱلۡمَفَرُّ¦75:11:3:كَلَّا لَا وَزَرَ¦75:12:3:إِلَىٰ رَبِّكَ يَوۡمَئِذٍ ٱلۡمُسۡتَقَرُّ¦75:13:1:يُنَبَّؤُاْ\nT;0;75:13:2:ٱلۡإِنسَٰنُ يَوۡمَئِذِۭ بِمَا قَدَّمَ وَأَخَّرَ¦75:14:3:بَلِ ٱلۡإِنسَٰنُ عَلَىٰ نَفۡسِهِۦ بَصِيرَةࣱ\nT;0;75:15:3:وَلَوۡ أَلۡقَىٰ مَعَاذِيرَهُۥ¦75:16:3:لَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦٓ¦75:17:1:إِنَّ عَلَيۡنَا\nT;0;75:17:2:جَمۡعَهُۥ وَقُرۡءَانَهُۥ¦75:18:3:فَإِذَا قَرَأۡنَٰهُ فَٱتَّبِعۡ قُرۡءَانَهُۥ¦75:19:3:ثُمَّ إِنَّ عَلَيۡنَا بَيَانَهُۥ',
  '29;58;2;\nT;0;75:20:3:كَلَّا بَلۡ تُحِبُّونَ ٱلۡعَاجِلَةَ¦75:21:3:وَتَذَرُونَ ٱلۡأٓخِرَةَ¦75:22:1:وُجُوهࣱ يَوۡمَئِذࣲ\nT;0;75:22:2:نَّاضِرَةٌ¦75:23:3:إِلَىٰ رَبِّهَا نَاظِرَةࣱ¦75:24:3:وَوُجُوهࣱ يَوۡمَئِذِۭ بَاسِرَةࣱ¦75:25:1:تَظُنُّ أَن يُفۡعَلَ\nT;0;75:25:2:بِهَا فَاقِرَةࣱ¦75:26:3:كَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِيَ¦75:27:3:وَقِيلَ مَنۡۜ رَاقࣲ¦75:28:1:وَظَنَّ أَنَّهُ\nT;0;75:28:2:ٱلۡفِرَاقُ¦75:29:3:وَٱلۡتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ¦75:30:3:إِلَىٰ رَبِّكَ يَوۡمَئِذٍ ٱلۡمَسَاقُ\nT;0;75:31:3:فَلَا صَدَّقَ وَلَا صَلَّىٰ¦75:32:3:وَلَٰكِن كَذَّبَ وَتَوَلَّىٰ¦75:33:1:ثُمَّ ذَهَبَ إِلَىٰٓ أَهۡلِهِۦ\nT;0;75:33:2:يَتَمَطَّىٰٓ¦75:34:3:أَوۡلَىٰ لَكَ فَأَوۡلَىٰ¦75:35:3:ثُمَّ أَوۡلَىٰ لَكَ فَأَوۡلَىٰٓ¦75:36:1:أَيَحۡسَبُ\nT;0;75:36:2:ٱلۡإِنسَٰنُ أَن يُتۡرَكَ سُدًى¦75:37:3:أَلَمۡ يَكُ نُطۡفَةࣰ مِّن مَّنِيࣲّ يُمۡنَىٰ\nT;0;75:38:3:ثُمَّ كَانَ عَلَقَةࣰ فَخَلَقَ فَسَوَّىٰ¦75:39:1:فَجَعَلَ مِنۡهُ ٱلزَّوۡجَيۡنِ ٱلذَّكَرَ\nT;2;75:39:2:وَٱلۡأُنثَىٰٓ¦75:40:3:أَلَيۡسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحۡـِۧيَ ٱلۡمَوۡتَىٰ\nH;76\nB;76\nT;0;76:1:3:هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَٰنِ حِينࣱ مِّنَ ٱلدَّهۡرِ لَمۡ يَكُن شَيۡـࣰٔا مَّذۡكُورًا¦76:2:1:إِنَّا خَلَقۡنَا\nT;0;76:2:2:ٱلۡإِنسَٰنَ مِن نُّطۡفَةٍ أَمۡشَاجࣲ نَّبۡتَلِيهِ فَجَعَلۡنَٰهُ سَمِيعَۢا بَصِيرًا¦76:3:1:إِنَّا\nT;0;76:3:2:هَدَيۡنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرࣰا وَإِمَّا كَفُورًا¦76:4:1:إِنَّآ أَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَلَٰسِلَاْ\nT;0;76:4:2:وَأَغۡلَٰلࣰا وَسَعِيرًا¦76:5:3:إِنَّ ٱلۡأَبۡرَارَ يَشۡرَبُونَ مِن كَأۡسࣲ كَانَ مِزَاجُهَا كَافُورًا',
  '29;58;2;232\nT;0;76:6:3:عَيۡنࣰا يَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفۡجِيرࣰا¦76:7:1:يُوفُونَ بِٱلنَّذۡرِ وَيَخَافُونَ\nT;0;76:7:2:يَوۡمࣰا كَانَ شَرُّهُۥ مُسۡتَطِيرࣰا¦76:8:1:وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينࣰا\nT;0;76:8:2:وَيَتِيمࣰا وَأَسِيرًا¦76:9:1:إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءࣰ\nT;0;76:9:2:وَلَا شُكُورًا¦76:10:3:إِنَّا نَخَافُ مِن رَّبِّنَا يَوۡمًا عَبُوسࣰا قَمۡطَرِيرࣰا¦76:11:1:فَوَقَىٰهُمُ ٱللَّهُ شَرَّ\nT;0;76:11:2:ذَٰلِكَ ٱلۡيَوۡمِ وَلَقَّىٰهُمۡ نَضۡرَةࣰ وَسُرُورࣰا¦76:12:1:وَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةࣰ\nT;0;76:12:2:وَحَرِيرࣰا¦76:13:1:مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۖ لَا يَرَوۡنَ فِيهَا شَمۡسࣰا\nT;0;76:13:2:وَلَا زَمۡهَرِيرࣰا¦76:14:3:وَدَانِيَةً عَلَيۡهِمۡ ظِلَٰلُهَا وَذُلِّلَتۡ قُطُوفُهَا تَذۡلِيلࣰا\nT;0;76:15:3:وَيُطَافُ عَلَيۡهِم بِـَٔانِيَةࣲ مِّن فِضَّةࣲ وَأَكۡوَابࣲ كَانَتۡ قَوَارِيرَا۠¦76:16:1:قَوَارِيرَاْ مِن فِضَّةࣲ\nT;0;76:16:2:قَدَّرُوهَا تَقۡدِيرࣰا¦76:17:3:وَيُسۡقَوۡنَ فِيهَا كَأۡسࣰا كَانَ مِزَاجُهَا زَنجَبِيلًا¦76:18:1:عَيۡنࣰا فِيهَا\nT;0;76:18:2:تُسَمَّىٰ سَلۡسَبِيلࣰا¦76:19:1:۞ وَيَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنࣱ مُّخَلَّدُونَ إِذَا رَأَيۡتَهُمۡ حَسِبۡتَهُمۡ\nT;0;76:19:2:لُؤۡلُؤࣰا مَّنثُورࣰا¦76:20:3:وَإِذَا رَأَيۡتَ ثَمَّ رَأَيۡتَ نَعِيمࣰا وَمُلۡكࣰا كَبِيرًا¦76:21:1:عَٰلِيَهُمۡ ثِيَابُ\nT;0;76:21:0:سُندُسٍ خُضۡرࣱ وَإِسۡتَبۡرَقࣱۖ وَحُلُّوٓاْ أَسَاوِرَ مِن فِضَّةࣲ وَسَقَىٰهُمۡ رَبُّهُمۡ\nT;0;76:21:2:شَرَابࣰا طَهُورًا¦76:22:3:إِنَّ هَٰذَا كَانَ لَكُمۡ جَزَآءࣰ وَكَانَ سَعۡيُكُم مَّشۡكُورًا\nT;0;76:23:3:إِنَّا نَحۡنُ نَزَّلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ تَنزِيلࣰا¦76:24:1:فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ\nT;0;76:24:2:مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورࣰا¦76:25:3:وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةࣰ وَأَصِيلࣰا',
  '29;58;3;\nT;0;76:26:3:وَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلࣰا طَوِيلًا¦76:27:1:إِنَّ هَٰٓؤُلَآءِ\nT;0;76:27:2:يُحِبُّونَ ٱلۡعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمۡ يَوۡمࣰا ثَقِيلࣰا¦76:28:1:نَّحۡنُ خَلَقۡنَٰهُمۡ\nT;0;76:28:2:وَشَدَدۡنَآ أَسۡرَهُمۡۖ وَإِذَا شِئۡنَا بَدَّلۡنَآ أَمۡثَٰلَهُمۡ تَبۡدِيلًا¦76:29:1:إِنَّ\nT;0;76:29:2:هَٰذِهِۦ تَذۡكِرَةࣱۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلࣰا¦76:30:1:وَمَا تَشَآءُونَ\nT;0;76:30:2:إِلَّآ أَن يَشَآءَ ٱللَّهُۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمࣰا¦76:31:1:يُدۡخِلُ\nT;2;76:31:2:مَن يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّٰلِمِينَ أَعَدَّ لَهُمۡ عَذَابًا أَلِيمَۢا\nH;77\nB;77\nT;0;77:1:3:وَٱلۡمُرۡسَلَٰتِ عُرۡفࣰا¦77:2:3:فَٱلۡعَٰصِفَٰتِ عَصۡفࣰا¦77:3:3:وَٱلنَّٰشِرَٰتِ نَشۡرࣰا\nT;0;77:4:3:فَٱلۡفَٰرِقَٰتِ فَرۡقࣰا¦77:5:3:فَٱلۡمُلۡقِيَٰتِ ذِكۡرًا¦77:6:3:عُذۡرًا أَوۡ نُذۡرًا¦77:7:1:إِنَّمَا\nT;0;77:7:2:تُوعَدُونَ لَوَٰقِعࣱ¦77:8:3:فَإِذَا ٱلنُّجُومُ طُمِسَتۡ¦77:9:3:وَإِذَا ٱلسَّمَآءُ فُرِجَتۡ\nT;0;77:10:3:وَإِذَا ٱلۡجِبَالُ نُسِفَتۡ¦77:11:3:وَإِذَا ٱلرُّسُلُ أُقِّتَتۡ¦77:12:3:لِأَيِّ يَوۡمٍ أُجِّلَتۡ\nT;0;77:13:3:لِيَوۡمِ ٱلۡفَصۡلِ¦77:14:3:وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلۡفَصۡلِ¦77:15:1:وَيۡلࣱ يَوۡمَئِذࣲ\nT;0;77:15:2:لِّلۡمُكَذِّبِينَ¦77:16:3:أَلَمۡ نُهۡلِكِ ٱلۡأَوَّلِينَ¦77:17:3:ثُمَّ نُتۡبِعُهُمُ ٱلۡأٓخِرِينَ\nT;0;77:18:3:كَذَٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِينَ¦77:19:3:وَيۡلࣱ يَوۡمَئِذࣲ لِّلۡمُكَذِّبِينَ',
  '29;58;3;\nT;0;77:20:3:أَلَمۡ نَخۡلُقكُّم مِّن مَّآءࣲ مَّهِينࣲ¦77:21:3:فَجَعَلۡنَٰهُ فِي قَرَارࣲ مَّكِينٍ¦77:22:1:إِلَىٰ قَدَرࣲ\nT;0;77:22:2:مَّعۡلُومࣲ¦77:23:3:فَقَدَرۡنَا فَنِعۡمَ ٱلۡقَٰدِرُونَ¦77:24:3:وَيۡلࣱ يَوۡمَئِذࣲ لِّلۡمُكَذِّبِينَ\nT;0;77:25:3:أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ كِفَاتًا¦77:26:3:أَحۡيَآءࣰ وَأَمۡوَٰتࣰا¦77:27:1:وَجَعَلۡنَا فِيهَا رَوَٰسِيَ\nT;0;77:27:2:شَٰمِخَٰتࣲ وَأَسۡقَيۡنَٰكُم مَّآءࣰ فُرَاتࣰا¦77:28:3:وَيۡلࣱ يَوۡمَئِذࣲ لِّلۡمُكَذِّبِينَ\nT;0;77:29:3:ٱنطَلِقُوٓاْ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ¦77:30:1:ٱنطَلِقُوٓاْ إِلَىٰ ظِلࣲّ ذِي ثَلَٰثِ\nT;0;77:30:2:شُعَبࣲ¦77:31:3:لَّا ظَلِيلࣲ وَلَا يُغۡنِي مِنَ ٱللَّهَبِ¦77:32:1:إِنَّهَا تَرۡمِي بِشَرَرࣲ\nT;0;77:32:2:كَٱلۡقَصۡرِ¦77:33:3:كَأَنَّهُۥ جِمَٰلَتࣱ صُفۡرࣱ¦77:34:3:وَيۡلࣱ يَوۡمَئِذࣲ لِّلۡمُكَذِّبِينَ\nT;0;77:35:3:هَٰذَا يَوۡمُ لَا يَنطِقُونَ¦77:36:3:وَلَا يُؤۡذَنُ لَهُمۡ فَيَعۡتَذِرُونَ¦77:37:1:وَيۡلࣱ يَوۡمَئِذࣲ\nT;0;77:37:2:لِّلۡمُكَذِّبِينَ¦77:38:3:هَٰذَا يَوۡمُ ٱلۡفَصۡلِۖ جَمَعۡنَٰكُمۡ وَٱلۡأَوَّلِينَ¦77:39:1:فَإِن كَانَ\nT;0;77:39:2:لَكُمۡ كَيۡدࣱ فَكِيدُونِ¦77:40:3:وَيۡلࣱ يَوۡمَئِذࣲ لِّلۡمُكَذِّبِينَ¦77:41:1:إِنَّ ٱلۡمُتَّقِينَ\nT;0;77:41:2:فِي ظِلَٰلࣲ وَعُيُونࣲ¦77:42:3:وَفَوَٰكِهَ مِمَّا يَشۡتَهُونَ¦77:43:1:كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا\nT;0;77:43:2:بِمَا كُنتُمۡ تَعۡمَلُونَ¦77:44:3:إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ¦77:45:1:وَيۡلࣱ\nT;0;77:45:2:يَوۡمَئِذࣲ لِّلۡمُكَذِّبِينَ¦77:46:3:كُلُواْ وَتَمَتَّعُواْ قَلِيلًا إِنَّكُم مُّجۡرِمُونَ¦77:47:1:وَيۡلࣱ\nT;0;77:47:2:يَوۡمَئِذࣲ لِّلۡمُكَذِّبِينَ¦77:48:3:وَإِذَا قِيلَ لَهُمُ ٱرۡكَعُواْ لَا يَرۡكَعُونَ\nT;2;77:49:3:وَيۡلࣱ يَوۡمَئِذࣲ لِّلۡمُكَذِّبِينَ¦77:50:3:فَبِأَيِّ حَدِيثِۭ بَعۡدَهُۥ يُؤۡمِنُونَ',
  '30;59;0;233\nH;78\nB;78\nT;0;78:1:3:عَمَّ يَتَسَآءَلُونَ¦78:2:3:عَنِ ٱلنَّبَإِ ٱلۡعَظِيمِ¦78:3:3:ٱلَّذِي هُمۡ فِيهِ مُخۡتَلِفُونَ\nT;0;78:4:3:كَلَّا سَيَعۡلَمُونَ¦78:5:3:ثُمَّ كَلَّا سَيَعۡلَمُونَ¦78:6:3:أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ مِهَٰدࣰا\nT;0;78:7:3:وَٱلۡجِبَالَ أَوۡتَادࣰا¦78:8:3:وَخَلَقۡنَٰكُمۡ أَزۡوَٰجࣰا¦78:9:3:وَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتࣰا\nT;0;78:10:3:وَجَعَلۡنَا ٱلَّيۡلَ لِبَاسࣰا¦78:11:3:وَجَعَلۡنَا ٱلنَّهَارَ مَعَاشࣰا¦78:12:1:وَبَنَيۡنَا\nT;0;78:12:2:فَوۡقَكُمۡ سَبۡعࣰا شِدَادࣰا¦78:13:3:وَجَعَلۡنَا سِرَاجࣰا وَهَّاجࣰا¦78:14:1:وَأَنزَلۡنَا مِنَ\nT;0;78:14:2:ٱلۡمُعۡصِرَٰتِ مَآءࣰ ثَجَّاجࣰا¦78:15:3:لِّنُخۡرِجَ بِهِۦ حَبࣰّا وَنَبَاتࣰا¦78:16:1:وَجَنَّٰتٍ\nT;0;78:16:2:أَلۡفَافًا¦78:17:3:إِنَّ يَوۡمَ ٱلۡفَصۡلِ كَانَ مِيقَٰتࣰا¦78:18:1:يَوۡمَ يُنفَخُ فِي ٱلصُّورِ\nT;0;78:18:2:فَتَأۡتُونَ أَفۡوَاجࣰا¦78:19:3:وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتۡ أَبۡوَٰبࣰا¦78:20:1:وَسُيِّرَتِ\nT;0;78:20:2:ٱلۡجِبَالُ فَكَانَتۡ سَرَابًا¦78:21:3:إِنَّ جَهَنَّمَ كَانَتۡ مِرۡصَادࣰا¦78:22:1:لِّلطَّٰغِينَ\nT;0;78:22:2:مَـَٔابࣰا¦78:23:3:لَّٰبِثِينَ فِيهَآ أَحۡقَابࣰا¦78:24:1:لَّا يَذُوقُونَ فِيهَا بَرۡدࣰا وَلَا\nT;0;78:24:2:شَرَابًا¦78:25:3:إِلَّا حَمِيمࣰا وَغَسَّاقࣰا¦78:26:3:جَزَآءࣰ وِفَاقًا¦78:27:1:إِنَّهُمۡ كَانُواْ\nT;0;78:27:2:لَا يَرۡجُونَ حِسَابࣰا¦78:28:3:وَكَذَّبُواْ بِـَٔايَٰتِنَا كِذَّابࣰا¦78:29:1:وَكُلَّ شَيۡءٍ\nT;0;78:29:2:أَحۡصَيۡنَٰهُ كِتَٰبࣰا¦78:30:3:فَذُوقُواْ فَلَن نَّزِيدَكُمۡ إِلَّا عَذَابًا',
  '30;59;0;\nT;0;78:31:3:إِنَّ لِلۡمُتَّقِينَ مَفَازًا¦78:32:3:حَدَآئِقَ وَأَعۡنَٰبࣰا¦78:33:3:وَكَوَاعِبَ أَتۡرَابࣰا¦78:34:1:وَكَأۡسࣰا\nT;0;78:34:2:دِهَاقࣰا¦78:35:3:لَّا يَسۡمَعُونَ فِيهَا لَغۡوࣰا وَلَا كِذَّٰبࣰا¦78:36:1:جَزَآءࣰ مِّن رَّبِّكَ عَطَآءً\nT;0;78:36:2:حِسَابࣰا¦78:37:1:رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلرَّحۡمَٰنِۖ لَا يَمۡلِكُونَ\nT;0;78:37:2:مِنۡهُ خِطَابࣰا¦78:38:1:يَوۡمَ يَقُومُ ٱلرُّوحُ وَٱلۡمَلَٰٓئِكَةُ صَفࣰّاۖ لَّا يَتَكَلَّمُونَ\nT;0;78:38:2:إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَقَالَ صَوَابࣰا¦78:39:1:ذَٰلِكَ ٱلۡيَوۡمُ ٱلۡحَقُّۖ فَمَن\nT;0;78:39:2:شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا¦78:40:1:إِنَّآ أَنذَرۡنَٰكُمۡ عَذَابࣰا قَرِيبࣰا يَوۡمَ يَنظُرُ\nT;2;78:40:2:ٱلۡمَرۡءُ مَا قَدَّمَتۡ يَدَاهُ وَيَقُولُ ٱلۡكَافِرُ يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا\nH;79\nB;79\nT;0;79:1:3:وَٱلنَّٰزِعَٰتِ غَرۡقࣰا¦79:2:3:وَٱلنَّٰشِطَٰتِ نَشۡطࣰا¦79:3:3:وَٱلسَّٰبِحَٰتِ سَبۡحࣰا\nT;0;79:4:3:فَٱلسَّٰبِقَٰتِ سَبۡقࣰا¦79:5:3:فَٱلۡمُدَبِّرَٰتِ أَمۡرࣰا¦79:6:3:يَوۡمَ تَرۡجُفُ ٱلرَّاجِفَةُ\nT;0;79:7:3:تَتۡبَعُهَا ٱلرَّادِفَةُ¦79:8:3:قُلُوبࣱ يَوۡمَئِذࣲ وَاجِفَةٌ¦79:9:3:أَبۡصَٰرُهَا خَٰشِعَةࣱ\nT;0;79:10:3:يَقُولُونَ أَءِنَّا لَمَرۡدُودُونَ فِي ٱلۡحَافِرَةِ¦79:11:3:أَءِذَا كُنَّا عِظَٰمࣰا نَّخِرَةࣰ¦79:12:1:قَالُواْ\nT;0;79:12:2:تِلۡكَ إِذࣰا كَرَّةٌ خَاسِرَةࣱ¦79:13:3:فَإِنَّمَا هِيَ زَجۡرَةࣱ وَٰحِدَةࣱ¦79:14:3:فَإِذَا هُم بِٱلسَّاهِرَةِ\nT;0;79:15:3:هَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ¦79:16:3:إِذۡ نَادَىٰهُ رَبُّهُۥ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوًى',
  '30;59;0;\nT;0;79:17:3:ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ¦79:18:3:فَقُلۡ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ\nT;0;79:19:3:وَأَهۡدِيَكَ إِلَىٰ رَبِّكَ فَتَخۡشَىٰ¦79:20:3:فَأَرَىٰهُ ٱلۡأٓيَةَ ٱلۡكُبۡرَىٰ\nT;0;79:21:3:فَكَذَّبَ وَعَصَىٰ¦79:22:3:ثُمَّ أَدۡبَرَ يَسۡعَىٰ¦79:23:3:فَحَشَرَ فَنَادَىٰ\nT;0;79:24:3:فَقَالَ أَنَا۠ رَبُّكُمُ ٱلۡأَعۡلَىٰ¦79:25:3:فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلۡأٓخِرَةِ وَٱلۡأُولَىٰٓ\nT;0;79:26:3:إِنَّ فِي ذَٰلِكَ لَعِبۡرَةࣰ لِّمَن يَخۡشَىٰٓ¦79:27:1:ءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُۚ\nT;0;79:27:2:بَنَىٰهَا¦79:28:3:رَفَعَ سَمۡكَهَا فَسَوَّىٰهَا¦79:29:1:وَأَغۡطَشَ لَيۡلَهَا وَأَخۡرَجَ\nT;0;79:29:2:ضُحَىٰهَا¦79:30:3:وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ دَحَىٰهَآ¦79:31:1:أَخۡرَجَ مِنۡهَا مَآءَهَا\nT;0;79:31:2:وَمَرۡعَىٰهَا¦79:32:3:وَٱلۡجِبَالَ أَرۡسَىٰهَا¦79:33:3:مَتَٰعࣰا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ\nT;0;79:34:3:فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلۡكُبۡرَىٰ¦79:35:3:يَوۡمَ يَتَذَكَّرُ ٱلۡإِنسَٰنُ مَا سَعَىٰ\nT;0;79:36:3:وَبُرِّزَتِ ٱلۡجَحِيمُ لِمَن يَرَىٰ¦79:37:3:فَأَمَّا مَن طَغَىٰ¦79:38:1:وَءَاثَرَ ٱلۡحَيَوٰةَ\nT;0;79:38:2:ٱلدُّنۡيَا¦79:39:3:فَإِنَّ ٱلۡجَحِيمَ هِيَ ٱلۡمَأۡوَىٰ¦79:40:1:وَأَمَّا مَنۡ خَافَ مَقَامَ\nT;0;79:40:2:رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ¦79:41:3:فَإِنَّ ٱلۡجَنَّةَ هِيَ ٱلۡمَأۡوَىٰ\nT;0;79:42:3:يَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرۡسَىٰهَا¦79:43:1:فِيمَ أَنتَ مِن\nT;0;79:43:2:ذِكۡرَىٰهَآ¦79:44:3:إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ¦79:45:3:إِنَّمَآ أَنتَ مُنذِرُ مَن يَخۡشَىٰهَا\nT;2;79:46:3:كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَهَا لَمۡ يَلۡبَثُوٓاْ إِلَّا عَشِيَّةً أَوۡ ضُحَىٰهَا',
  '30;59;1;234\nH;80\nB;80\nT;0;80:1:3:عَبَسَ وَتَوَلَّىٰٓ¦80:2:3:أَن جَآءَهُ ٱلۡأَعۡمَىٰ¦80:3:3:وَمَا يُدۡرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ¦80:4:1:أَوۡ يَذَّكَّرُ\nT;0;80:4:2:فَتَنفَعَهُ ٱلذِّكۡرَىٰٓ¦80:5:3:أَمَّا مَنِ ٱسۡتَغۡنَىٰ¦80:6:3:فَأَنتَ لَهُۥ تَصَدَّىٰ¦80:7:1:وَمَا عَلَيۡكَ\nT;0;80:7:2:أَلَّا يَزَّكَّىٰ¦80:8:3:وَأَمَّا مَن جَآءَكَ يَسۡعَىٰ¦80:9:3:وَهُوَ يَخۡشَىٰ¦80:10:3:فَأَنتَ عَنۡهُ تَلَهَّىٰ\nT;0;80:11:3:كَلَّآ إِنَّهَا تَذۡكِرَةࣱ¦80:12:3:فَمَن شَآءَ ذَكَرَهُۥ¦80:13:3:فِي صُحُفࣲ مُّكَرَّمَةࣲ¦80:14:1:مَّرۡفُوعَةࣲ\nT;0;80:14:2:مُّطَهَّرَةِۭ¦80:15:3:بِأَيۡدِي سَفَرَةࣲ¦80:16:3:كِرَامِۭ بَرَرَةࣲ¦80:17:3:قُتِلَ ٱلۡإِنسَٰنُ مَآ أَكۡفَرَهُۥ¦80:18:1:مِنۡ\nT;0;80:18:2:أَيِّ شَيۡءٍ خَلَقَهُۥ¦80:19:3:مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ¦80:20:3:ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ\nT;0;80:21:3:ثُمَّ أَمَاتَهُۥ فَأَقۡبَرَهُۥ¦80:22:3:ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ¦80:23:3:كَلَّا لَمَّا يَقۡضِ مَآ أَمَرَهُۥ\nT;0;80:24:3:فَلۡيَنظُرِ ٱلۡإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ¦80:25:3:أَنَّا صَبَبۡنَا ٱلۡمَآءَ صَبࣰّا¦80:26:1:ثُمَّ شَقَقۡنَا\nT;0;80:26:2:ٱلۡأَرۡضَ شَقࣰّا¦80:27:3:فَأَنۢبَتۡنَا فِيهَا حَبࣰّا¦80:28:3:وَعِنَبࣰا وَقَضۡبࣰا¦80:29:3:وَزَيۡتُونࣰا وَنَخۡلࣰا\nT;0;80:30:3:وَحَدَآئِقَ غُلۡبࣰا¦80:31:3:وَفَٰكِهَةࣰ وَأَبࣰّا¦80:32:3:مَّتَٰعࣰا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ¦80:33:1:فَإِذَا جَآءَتِ\nT;0;80:33:2:ٱلصَّآخَّةُ¦80:34:3:يَوۡمَ يَفِرُّ ٱلۡمَرۡءُ مِنۡ أَخِيهِ¦80:35:3:وَأُمِّهِۦ وَأَبِيهِ¦80:36:1:وَصَٰحِبَتِهِۦ\nT;0;80:36:2:وَبَنِيهِ¦80:37:3:لِكُلِّ ٱمۡرِيࣲٕ مِّنۡهُمۡ يَوۡمَئِذࣲ شَأۡنࣱ يُغۡنِيهِ¦80:38:1:وُجُوهࣱ يَوۡمَئِذࣲ\nT;0;80:38:2:مُّسۡفِرَةࣱ¦80:39:3:ضَاحِكَةࣱ مُّسۡتَبۡشِرَةࣱ¦80:40:3:وَوُجُوهࣱ يَوۡمَئِذٍ عَلَيۡهَا غَبَرَةࣱ',
  '30;59;1;\nT;2;80:41:3:تَرۡهَقُهَا قَتَرَةٌ¦80:42:3:أُوْلَٰٓئِكَ هُمُ ٱلۡكَفَرَةُ ٱلۡفَجَرَةُ\nH;81\nB;81\nT;0;81:1:3:إِذَا ٱلشَّمۡسُ كُوِّرَتۡ¦81:2:3:وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتۡ¦81:3:1:وَإِذَا ٱلۡجِبَالُ\nT;0;81:3:2:سُيِّرَتۡ¦81:4:3:وَإِذَا ٱلۡعِشَارُ عُطِّلَتۡ¦81:5:3:وَإِذَا ٱلۡوُحُوشُ حُشِرَتۡ\nT;0;81:6:3:وَإِذَا ٱلۡبِحَارُ سُجِّرَتۡ¦81:7:3:وَإِذَا ٱلنُّفُوسُ زُوِّجَتۡ¦81:8:1:وَإِذَا ٱلۡمَوۡءُۥدَةُ\nT;0;81:8:2:سُئِلَتۡ¦81:9:3:بِأَيِّ ذَنۢبࣲ قُتِلَتۡ¦81:10:3:وَإِذَا ٱلصُّحُفُ نُشِرَتۡ\nT;0;81:11:3:وَإِذَا ٱلسَّمَآءُ كُشِطَتۡ¦81:12:3:وَإِذَا ٱلۡجَحِيمُ سُعِّرَتۡ¦81:13:1:وَإِذَا ٱلۡجَنَّةُ\nT;0;81:13:2:أُزۡلِفَتۡ¦81:14:3:عَلِمَتۡ نَفۡسࣱ مَّآ أَحۡضَرَتۡ¦81:15:3:فَلَآ أُقۡسِمُ بِٱلۡخُنَّسِ\nT;0;81:16:3:ٱلۡجَوَارِ ٱلۡكُنَّسِ¦81:17:3:وَٱلَّيۡلِ إِذَا عَسۡعَسَ¦81:18:3:وَٱلصُّبۡحِ إِذَا تَنَفَّسَ\nT;0;81:19:3:إِنَّهُۥ لَقَوۡلُ رَسُولࣲ كَرِيمࣲ¦81:20:3:ذِي قُوَّةٍ عِندَ ذِي ٱلۡعَرۡشِ مَكِينࣲ¦81:21:1:مُّطَاعࣲ ثَمَّ\nT;0;81:21:2:أَمِينࣲ¦81:22:3:وَمَا صَاحِبُكُم بِمَجۡنُونࣲ¦81:23:3:وَلَقَدۡ رَءَاهُ بِٱلۡأُفُقِ ٱلۡمُبِينِ\nT;0;81:24:3:وَمَا هُوَ عَلَى ٱلۡغَيۡبِ بِضَنِينࣲ¦81:25:3:وَمَا هُوَ بِقَوۡلِ شَيۡطَٰنࣲ رَّجِيمࣲ\nT;0;81:26:3:فَأَيۡنَ تَذۡهَبُونَ¦81:27:3:إِنۡ هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَٰلَمِينَ¦81:28:1:لِمَن شَآءَ مِنكُمۡ أَن\nT;2;81:28:2:يَسۡتَقِيمَ¦81:29:3:وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ',
  '30;59;2;235\nH;82\nB;82\nT;0;82:1:3:إِذَا ٱلسَّمَآءُ ٱنفَطَرَتۡ¦82:2:3:وَإِذَا ٱلۡكَوَاكِبُ ٱنتَثَرَتۡ¦82:3:1:وَإِذَا ٱلۡبِحَارُ\nT;0;82:3:2:فُجِّرَتۡ¦82:4:3:وَإِذَا ٱلۡقُبُورُ بُعۡثِرَتۡ¦82:5:1:عَلِمَتۡ نَفۡسࣱ مَّا قَدَّمَتۡ\nT;0;82:5:2:وَأَخَّرَتۡ¦82:6:3:يَٰٓأَيُّهَا ٱلۡإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلۡكَرِيمِ¦82:7:1:ٱلَّذِي\nT;0;82:7:2:خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ¦82:8:3:فِيٓ أَيِّ صُورَةࣲ مَّا شَآءَ رَكَّبَكَ\nT;0;82:9:3:كَلَّا بَلۡ تُكَذِّبُونَ بِٱلدِّينِ¦82:10:3:وَإِنَّ عَلَيۡكُمۡ لَحَٰفِظِينَ¦82:11:1:كِرَامࣰا\nT;0;82:11:2:كَٰتِبِينَ¦82:12:3:يَعۡلَمُونَ مَا تَفۡعَلُونَ¦82:13:3:إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمࣲ¦82:14:1:وَإِنَّ\nT;0;82:14:2:ٱلۡفُجَّارَ لَفِي جَحِيمࣲ¦82:15:3:يَصۡلَوۡنَهَا يَوۡمَ ٱلدِّينِ¦82:16:1:وَمَا هُمۡ عَنۡهَا\nT;0;82:16:2:بِغَآئِبِينَ¦82:17:3:وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ¦82:18:1:ثُمَّ مَآ أَدۡرَىٰكَ مَا يَوۡمُ\nT;2;82:18:2:ٱلدِّينِ¦82:19:3:يَوۡمَ لَا تَمۡلِكُ نَفۡسࣱ لِّنَفۡسࣲ شَيۡـࣰٔاۖ وَٱلۡأَمۡرُ يَوۡمَئِذࣲ لِّلَّهِ\nH;83\nB;83\nT;0;83:1:3:وَيۡلࣱ لِّلۡمُطَفِّفِينَ¦83:2:3:ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ\nT;0;83:3:3:وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ¦83:4:3:أَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ',
  '30;59;2;\nT;0;83:5:3:لِيَوۡمٍ عَظِيمࣲ¦83:6:3:يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ¦83:7:1:كَلَّآ إِنَّ كِتَٰبَ\nT;0;83:7:2:ٱلۡفُجَّارِ لَفِي سِجِّينࣲ¦83:8:3:وَمَآ أَدۡرَىٰكَ مَا سِجِّينࣱ¦83:9:3:كِتَٰبࣱ مَّرۡقُومࣱ\nT;0;83:10:3:وَيۡلࣱ يَوۡمَئِذࣲ لِّلۡمُكَذِّبِينَ¦83:11:3:ٱلَّذِينَ يُكَذِّبُونَ بِيَوۡمِ ٱلدِّينِ¦83:12:1:وَمَا يُكَذِّبُ\nT;0;83:12:2:بِهِۦٓ إِلَّا كُلُّ مُعۡتَدٍ أَثِيمٍ¦83:13:3:إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ\nT;0;83:14:3:كَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ¦83:15:1:كَلَّآ إِنَّهُمۡ عَن رَّبِّهِمۡ\nT;0;83:15:2:يَوۡمَئِذࣲ لَّمَحۡجُوبُونَ¦83:16:3:ثُمَّ إِنَّهُمۡ لَصَالُواْ ٱلۡجَحِيمِ¦83:17:1:ثُمَّ يُقَالُ هَٰذَا\nT;0;83:17:2:ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ¦83:18:3:كَلَّآ إِنَّ كِتَٰبَ ٱلۡأَبۡرَارِ لَفِي عِلِّيِّينَ\nT;0;83:19:3:وَمَآ أَدۡرَىٰكَ مَا عِلِّيُّونَ¦83:20:3:كِتَٰبࣱ مَّرۡقُومࣱ¦83:21:3:يَشۡهَدُهُ ٱلۡمُقَرَّبُونَ\nT;0;83:22:3:إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٍ¦83:23:3:عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ¦83:24:1:تَعۡرِفُ فِي\nT;0;83:24:2:وُجُوهِهِمۡ نَضۡرَةَ ٱلنَّعِيمِ¦83:25:3:يُسۡقَوۡنَ مِن رَّحِيقࣲ مَّخۡتُومٍ¦83:26:1:خِتَٰمُهُۥ\nT;0;83:26:2:مِسۡكࣱۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ¦83:27:1:وَمِزَاجُهُۥ مِن\nT;0;83:27:2:تَسۡنِيمٍ¦83:28:3:عَيۡنࣰا يَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ¦83:29:1:إِنَّ ٱلَّذِينَ أَجۡرَمُواْ كَانُواْ\nT;0;83:29:2:مِنَ ٱلَّذِينَ ءَامَنُواْ يَضۡحَكُونَ¦83:30:3:وَإِذَا مَرُّواْ بِهِمۡ يَتَغَامَزُونَ\nT;0;83:31:3:وَإِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمُ ٱنقَلَبُواْ فَكِهِينَ¦83:32:1:وَإِذَا رَأَوۡهُمۡ قَالُوٓاْ\nT;0;83:32:2:إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ¦83:33:3:وَمَآ أُرۡسِلُواْ عَلَيۡهِمۡ حَٰفِظِينَ',
  '30;59;2;236\nT;0;83:34:3:فَٱلۡيَوۡمَ ٱلَّذِينَ ءَامَنُواْ مِنَ ٱلۡكُفَّارِ يَضۡحَكُونَ¦83:35:1:عَلَى\nT;2;83:35:2:ٱلۡأَرَآئِكِ يَنظُرُونَ¦83:36:3:هَلۡ ثُوِّبَ ٱلۡكُفَّارُ مَا كَانُواْ يَفۡعَلُونَ\nH;84\nB;84\nT;0;84:1:3:إِذَا ٱلسَّمَآءُ ٱنشَقَّتۡ¦84:2:3:وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ¦84:3:3:وَإِذَا ٱلۡأَرۡضُ مُدَّتۡ\nT;0;84:4:3:وَأَلۡقَتۡ مَا فِيهَا وَتَخَلَّتۡ¦84:5:3:وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ¦84:6:1:يَٰٓأَيُّهَا\nT;0;84:6:2:ٱلۡإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدۡحࣰا فَمُلَٰقِيهِ¦84:7:1:فَأَمَّا مَنۡ أُوتِيَ\nT;0;84:7:2:كِتَٰبَهُۥ بِيَمِينِهِۦ¦84:8:3:فَسَوۡفَ يُحَاسَبُ حِسَابࣰا يَسِيرࣰا¦84:9:1:وَيَنقَلِبُ\nT;0;84:9:2:إِلَىٰٓ أَهۡلِهِۦ مَسۡرُورࣰا¦84:10:3:وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهۡرِهِۦ¦84:11:1:فَسَوۡفَ\nT;0;84:11:2:يَدۡعُواْ ثُبُورࣰا¦84:12:3:وَيَصۡلَىٰ سَعِيرًا¦84:13:3:إِنَّهُۥ كَانَ فِيٓ أَهۡلِهِۦ مَسۡرُورًا\nT;0;84:14:3:إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ¦84:15:3:بَلَىٰٓۚ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرࣰا¦84:16:1:فَلَآ أُقۡسِمُ\nT;0;84:16:2:بِٱلشَّفَقِ¦84:17:3:وَٱلَّيۡلِ وَمَا وَسَقَ¦84:18:3:وَٱلۡقَمَرِ إِذَا ٱتَّسَقَ\nT;0;84:19:3:لَتَرۡكَبُنَّ طَبَقًا عَن طَبَقࣲ¦84:20:3:فَمَا لَهُمۡ لَا يُؤۡمِنُونَ¦84:21:1:وَإِذَا قُرِئَ\nT;0;84:21:2:عَلَيۡهِمُ ٱلۡقُرۡءَانُ لَا يَسۡجُدُونَۤ۩¦84:22:3:بَلِ ٱلَّذِينَ كَفَرُواْ يُكَذِّبُونَ\nT;0;84:23:3:وَٱللَّهُ أَعۡلَمُ بِمَا يُوعُونَ¦84:24:3:فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ',
  '30;59;3;\nT;2;84:25:3:إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونِۭ\nH;85\nB;85\nT;0;85:1:3:وَٱلسَّمَآءِ ذَاتِ ٱلۡبُرُوجِ¦85:2:3:وَٱلۡيَوۡمِ ٱلۡمَوۡعُودِ¦85:3:3:وَشَاهِدࣲ وَمَشۡهُودࣲ\nT;0;85:4:3:قُتِلَ أَصۡحَٰبُ ٱلۡأُخۡدُودِ¦85:5:3:ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ¦85:6:1:إِذۡ هُمۡ عَلَيۡهَا\nT;0;85:6:2:قُعُودࣱ¦85:7:3:وَهُمۡ عَلَىٰ مَا يَفۡعَلُونَ بِٱلۡمُؤۡمِنِينَ شُهُودࣱ¦85:8:1:وَمَا نَقَمُواْ\nT;0;85:8:2:مِنۡهُمۡ إِلَّآ أَن يُؤۡمِنُواْ بِٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ¦85:9:1:ٱلَّذِي لَهُۥ مُلۡكُ\nT;0;85:9:2:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ شَهِيدٌ¦85:10:1:إِنَّ ٱلَّذِينَ\nT;0;85:10:0:فَتَنُواْ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ثُمَّ لَمۡ يَتُوبُواْ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ\nT;0;85:10:2:عَذَابُ ٱلۡحَرِيقِ¦85:11:1:إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ\nT;0;85:11:2:جَنَّٰتࣱ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡكَبِيرُ¦85:12:1:إِنَّ بَطۡشَ\nT;0;85:12:2:رَبِّكَ لَشَدِيدٌ¦85:13:3:إِنَّهُۥ هُوَ يُبۡدِئُ وَيُعِيدُ¦85:14:3:وَهُوَ ٱلۡغَفُورُ ٱلۡوَدُودُ\nT;0;85:15:3:ذُو ٱلۡعَرۡشِ ٱلۡمَجِيدُ¦85:16:3:فَعَّالࣱ لِّمَا يُرِيدُ¦85:17:1:هَلۡ أَتَىٰكَ حَدِيثُ\nT;0;85:17:2:ٱلۡجُنُودِ¦85:18:3:فِرۡعَوۡنَ وَثَمُودَ¦85:19:3:بَلِ ٱلَّذِينَ كَفَرُواْ فِي تَكۡذِيبࣲ¦85:20:1:وَٱللَّهُ\nT;2;85:20:2:مِن وَرَآئِهِم مُّحِيطُۢ¦85:21:3:بَلۡ هُوَ قُرۡءَانࣱ مَّجِيدࣱ¦85:22:3:فِي لَوۡحࣲ مَّحۡفُوظِۭ',
  '30;59;3;237\nH;86\nB;86\nT;0;86:1:3:وَٱلسَّمَآءِ وَٱلطَّارِقِ¦86:2:3:وَمَآ أَدۡرَىٰكَ مَا ٱلطَّارِقُ¦86:3:3:ٱلنَّجۡمُ ٱلثَّاقِبُ\nT;0;86:4:3:إِن كُلُّ نَفۡسࣲ لَّمَّا عَلَيۡهَا حَافِظࣱ¦86:5:3:فَلۡيَنظُرِ ٱلۡإِنسَٰنُ مِمَّ خُلِقَ\nT;0;86:6:3:خُلِقَ مِن مَّآءࣲ دَافِقࣲ¦86:7:3:يَخۡرُجُ مِنۢ بَيۡنِ ٱلصُّلۡبِ وَٱلتَّرَآئِبِ¦86:8:1:إِنَّهُۥ\nT;0;86:8:2:عَلَىٰ رَجۡعِهِۦ لَقَادِرࣱ¦86:9:3:يَوۡمَ تُبۡلَى ٱلسَّرَآئِرُ¦86:10:1:فَمَا لَهُۥ مِن قُوَّةࣲ وَلَا\nT;0;86:10:2:نَاصِرࣲ¦86:11:3:وَٱلسَّمَآءِ ذَاتِ ٱلرَّجۡعِ¦86:12:3:وَٱلۡأَرۡضِ ذَاتِ ٱلصَّدۡعِ\nT;0;86:13:3:إِنَّهُۥ لَقَوۡلࣱ فَصۡلࣱ¦86:14:3:وَمَا هُوَ بِٱلۡهَزۡلِ¦86:15:3:إِنَّهُمۡ يَكِيدُونَ كَيۡدࣰا\nT;2;86:16:3:وَأَكِيدُ كَيۡدࣰا¦86:17:3:فَمَهِّلِ ٱلۡكَٰفِرِينَ أَمۡهِلۡهُمۡ رُوَيۡدَۢا\nH;87\nB;87\nT;0;87:1:3:سَبِّحِ ٱسۡمَ رَبِّكَ ٱلۡأَعۡلَى¦87:2:3:ٱلَّذِي خَلَقَ فَسَوَّىٰ¦87:3:1:وَٱلَّذِي قَدَّرَ\nT;0;87:3:2:فَهَدَىٰ¦87:4:3:وَٱلَّذِيٓ أَخۡرَجَ ٱلۡمَرۡعَىٰ¦87:5:3:فَجَعَلَهُۥ غُثَآءً أَحۡوَىٰ\nT;0;87:6:3:سَنُقۡرِئُكَ فَلَا تَنسَىٰٓ¦87:7:3:إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ وَمَا يَخۡفَىٰ\nT;0;87:8:3:وَنُيَسِّرُكَ لِلۡيُسۡرَىٰ¦87:9:3:فَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ¦87:10:3:سَيَذَّكَّرُ مَن يَخۡشَىٰ',
  '30;60;0;\nT;0;87:11:3:وَيَتَجَنَّبُهَا ٱلۡأَشۡقَى¦87:12:3:ٱلَّذِي يَصۡلَى ٱلنَّارَ ٱلۡكُبۡرَىٰ¦87:13:1:ثُمَّ لَا يَمُوتُ\nT;0;87:13:2:فِيهَا وَلَا يَحۡيَىٰ¦87:14:3:قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ¦87:15:3:وَذَكَرَ ٱسۡمَ رَبِّهِۦ فَصَلَّىٰ\nT;0;87:16:3:بَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا¦87:17:3:وَٱلۡأٓخِرَةُ خَيۡرࣱ وَأَبۡقَىٰٓ¦87:18:1:إِنَّ\nT;2;87:18:2:هَٰذَا لَفِي ٱلصُّحُفِ ٱلۡأُولَىٰ¦87:19:3:صُحُفِ إِبۡرَٰهِيمَ وَمُوسَىٰ\nH;88\nB;88\nT;0;88:1:3:هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡغَٰشِيَةِ¦88:2:3:وُجُوهࣱ يَوۡمَئِذٍ خَٰشِعَةٌ¦88:3:1:عَامِلَةࣱ\nT;0;88:3:2:نَّاصِبَةࣱ¦88:4:3:تَصۡلَىٰ نَارًا حَامِيَةࣰ¦88:5:3:تُسۡقَىٰ مِنۡ عَيۡنٍ ءَانِيَةࣲ¦88:6:1:لَّيۡسَ\nT;0;88:6:2:لَهُمۡ طَعَامٌ إِلَّا مِن ضَرِيعࣲ¦88:7:3:لَّا يُسۡمِنُ وَلَا يُغۡنِي مِن جُوعࣲ¦88:8:1:وُجُوهࣱ\nT;0;88:8:2:يَوۡمَئِذࣲ نَّاعِمَةࣱ¦88:9:3:لِّسَعۡيِهَا رَاضِيَةࣱ¦88:10:3:فِي جَنَّةٍ عَالِيَةࣲ¦88:11:1:لَّا تَسۡمَعُ\nT;0;88:11:2:فِيهَا لَٰغِيَةࣰ¦88:12:3:فِيهَا عَيۡنࣱ جَارِيَةࣱ¦88:13:3:فِيهَا سُرُرࣱ مَّرۡفُوعَةࣱ¦88:14:1:وَأَكۡوَابࣱ\nT;0;88:14:2:مَّوۡضُوعَةࣱ¦88:15:3:وَنَمَارِقُ مَصۡفُوفَةࣱ¦88:16:3:وَزَرَابِيُّ مَبۡثُوثَةٌ¦88:17:1:أَفَلَا يَنظُرُونَ\nT;0;88:17:2:إِلَى ٱلۡإِبِلِ كَيۡفَ خُلِقَتۡ¦88:18:3:وَإِلَى ٱلسَّمَآءِ كَيۡفَ رُفِعَتۡ¦88:19:1:وَإِلَى\nT;0;88:19:2:ٱلۡجِبَالِ كَيۡفَ نُصِبَتۡ¦88:20:3:وَإِلَى ٱلۡأَرۡضِ كَيۡفَ سُطِحَتۡ\nT;0;88:21:3:فَذَكِّرۡ إِنَّمَآ أَنتَ مُذَكِّرࣱ¦88:22:3:لَّسۡتَ عَلَيۡهِم بِمُصَيۡطِرٍ',
  '30;60;0;\nT;0;88:23:3:إِلَّا مَن تَوَلَّىٰ وَكَفَرَ¦88:24:3:فَيُعَذِّبُهُ ٱللَّهُ ٱلۡعَذَابَ ٱلۡأَكۡبَرَ\nT;2;88:25:3:إِنَّ إِلَيۡنَآ إِيَابَهُمۡ¦88:26:3:ثُمَّ إِنَّ عَلَيۡنَا حِسَابَهُم\nH;89\nB;89\nT;0;89:1:3:وَٱلۡفَجۡرِ¦89:2:3:وَلَيَالٍ عَشۡرࣲ¦89:3:3:وَٱلشَّفۡعِ وَٱلۡوَتۡرِ¦89:4:3:وَٱلَّيۡلِ إِذَا يَسۡرِ\nT;0;89:5:3:هَلۡ فِي ذَٰلِكَ قَسَمࣱ لِّذِي حِجۡرٍ¦89:6:3:أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِعَادٍ\nT;0;89:7:3:إِرَمَ ذَاتِ ٱلۡعِمَادِ¦89:8:3:ٱلَّتِي لَمۡ يُخۡلَقۡ مِثۡلُهَا فِي ٱلۡبِلَٰدِ¦89:9:1:وَثَمُودَ ٱلَّذِينَ\nT;0;89:9:2:جَابُواْ ٱلصَّخۡرَ بِٱلۡوَادِ¦89:10:3:وَفِرۡعَوۡنَ ذِي ٱلۡأَوۡتَادِ¦89:11:1:ٱلَّذِينَ طَغَوۡاْ فِي\nT;0;89:11:2:ٱلۡبِلَٰدِ¦89:12:3:فَأَكۡثَرُواْ فِيهَا ٱلۡفَسَادَ¦89:13:1:فَصَبَّ عَلَيۡهِمۡ رَبُّكَ سَوۡطَ\nT;0;89:13:2:عَذَابٍ¦89:14:3:إِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ¦89:15:1:فَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ\nT;0;89:15:2:رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ¦89:16:1:وَأَمَّآ إِذَا مَا ٱبۡتَلَىٰهُ\nT;0;89:16:2:فَقَدَرَ عَلَيۡهِ رِزۡقَهُۥ فَيَقُولُ رَبِّيٓ أَهَٰنَنِ¦89:17:1:كَلَّاۖ بَل لَّا تُكۡرِمُونَ\nT;0;89:17:2:ٱلۡيَتِيمَ¦89:18:3:وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ¦89:19:1:وَتَأۡكُلُونَ\nT;0;89:19:2:ٱلتُّرَاثَ أَكۡلࣰا لَّمࣰّا¦89:20:3:وَتُحِبُّونَ ٱلۡمَالَ حُبࣰّا جَمࣰّا¦89:21:1:كَلَّآۖ إِذَا\nT;0;89:21:2:دُكَّتِ ٱلۡأَرۡضُ دَكࣰّا دَكࣰّا¦89:22:3:وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفࣰّا صَفࣰّا',
  '30;60;0;238\nT;0;89:23:1:وَجِاْيٓءَ يَوۡمَئِذِۭ بِجَهَنَّمَۚ يَوۡمَئِذࣲ يَتَذَكَّرُ ٱلۡإِنسَٰنُ وَأَنَّىٰ\nT;0;89:23:2:لَهُ ٱلذِّكۡرَىٰ¦89:24:3:يَقُولُ يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي¦89:25:1:فَيَوۡمَئِذࣲ\nT;0;89:25:2:لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدࣱ¦89:26:3:وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدࣱ¦89:27:1:يَٰٓأَيَّتُهَا\nT;0;89:27:2:ٱلنَّفۡسُ ٱلۡمُطۡمَئِنَّةُ¦89:28:3:ٱرۡجِعِيٓ إِلَىٰ رَبِّكِ رَاضِيَةࣰ مَّرۡضِيَّةࣰ\nT;2;89:29:3:فَٱدۡخُلِي فِي عِبَٰدِي¦89:30:3:وَٱدۡخُلِي جَنَّتِي\nH;90\nB;90\nT;0;90:1:3:لَآ أُقۡسِمُ بِهَٰذَا ٱلۡبَلَدِ¦90:2:3:وَأَنتَ حِلُّۢ بِهَٰذَا ٱلۡبَلَدِ¦90:3:3:وَوَالِدࣲ وَمَا وَلَدَ\nT;0;90:4:3:لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِي كَبَدٍ¦90:5:1:أَيَحۡسَبُ أَن لَّن يَقۡدِرَ عَلَيۡهِ\nT;0;90:5:2:أَحَدࣱ¦90:6:3:يَقُولُ أَهۡلَكۡتُ مَالࣰا لُّبَدًا¦90:7:3:أَيَحۡسَبُ أَن لَّمۡ يَرَهُۥٓ أَحَدٌ\nT;0;90:8:3:أَلَمۡ نَجۡعَل لَّهُۥ عَيۡنَيۡنِ¦90:9:3:وَلِسَانࣰا وَشَفَتَيۡنِ¦90:10:1:وَهَدَيۡنَٰهُ\nT;0;90:10:2:ٱلنَّجۡدَيۡنِ¦90:11:3:فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ¦90:12:3:وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ\nT;0;90:13:3:فَكُّ رَقَبَةٍ¦90:14:3:أَوۡ إِطۡعَٰمࣱ فِي يَوۡمࣲ ذِي مَسۡغَبَةࣲ¦90:15:3:يَتِيمࣰا ذَا مَقۡرَبَةٍ\nT;0;90:16:3:أَوۡ مِسۡكِينࣰا ذَا مَتۡرَبَةࣲ¦90:17:1:ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ\nT;0;90:17:2:بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ¦90:18:3:أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ',
  '30;60;1;\nT;2;90:19:3:وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا هُمۡ أَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ¦90:20:3:عَلَيۡهِمۡ نَارࣱ مُّؤۡصَدَةُۢ\nH;91\nB;91\nT;0;91:1:3:وَٱلشَّمۡسِ وَضُحَىٰهَا¦91:2:3:وَٱلۡقَمَرِ إِذَا تَلَىٰهَا¦91:3:3:وَٱلنَّهَارِ إِذَا جَلَّىٰهَا\nT;0;91:4:3:وَٱلَّيۡلِ إِذَا يَغۡشَىٰهَا¦91:5:3:وَٱلسَّمَآءِ وَمَا بَنَىٰهَا¦91:6:1:وَٱلۡأَرۡضِ\nT;0;91:6:2:وَمَا طَحَىٰهَا¦91:7:3:وَنَفۡسࣲ وَمَا سَوَّىٰهَا¦91:8:1:فَأَلۡهَمَهَا فُجُورَهَا\nT;0;91:8:2:وَتَقۡوَىٰهَا¦91:9:3:قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا¦91:10:3:وَقَدۡ خَابَ مَن دَسَّىٰهَا\nT;0;91:11:3:كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَآ¦91:12:3:إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا¦91:13:1:فَقَالَ لَهُمۡ\nT;0;91:13:2:رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا¦91:14:1:فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ\nT;2;91:14:2:عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا¦91:15:3:وَلَا يَخَافُ عُقۡبَٰهَا\nH;92\nB;92\nT;0;92:1:3:وَٱلَّيۡلِ إِذَا يَغۡشَىٰ¦92:2:3:وَٱلنَّهَارِ إِذَا تَجَلَّىٰ¦92:3:3:وَمَا خَلَقَ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ\nT;0;92:4:3:إِنَّ سَعۡيَكُمۡ لَشَتَّىٰ¦92:5:3:فَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ¦92:6:3:وَصَدَّقَ بِٱلۡحُسۡنَىٰ\nT;0;92:7:3:فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ¦92:8:3:وَأَمَّا مَنۢ بَخِلَ وَٱسۡتَغۡنَىٰ¦92:9:3:وَكَذَّبَ بِٱلۡحُسۡنَىٰ',
  '30;60;1;239\nT;0;92:10:3:فَسَنُيَسِّرُهُۥ لِلۡعُسۡرَىٰ¦92:11:3:وَمَا يُغۡنِي عَنۡهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ¦92:12:1:إِنَّ عَلَيۡنَا\nT;0;92:12:2:لَلۡهُدَىٰ¦92:13:3:وَإِنَّ لَنَا لَلۡأٓخِرَةَ وَٱلۡأُولَىٰ¦92:14:3:فَأَنذَرۡتُكُمۡ نَارࣰا تَلَظَّىٰ\nT;0;92:15:3:لَا يَصۡلَىٰهَآ إِلَّا ٱلۡأَشۡقَى¦92:16:3:ٱلَّذِي كَذَّبَ وَتَوَلَّىٰ¦92:17:1:وَسَيُجَنَّبُهَا\nT;0;92:17:2:ٱلۡأَتۡقَى¦92:18:3:ٱلَّذِي يُؤۡتِي مَالَهُۥ يَتَزَكَّىٰ¦92:19:1:وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةࣲ\nT;2;92:19:2:تُجۡزَىٰٓ¦92:20:3:إِلَّا ٱبۡتِغَآءَ وَجۡهِ رَبِّهِ ٱلۡأَعۡلَىٰ¦92:21:3:وَلَسَوۡفَ يَرۡضَىٰ\nH;93\nB;93\nT;0;93:1:3:وَٱلضُّحَىٰ¦93:2:3:وَٱلَّيۡلِ إِذَا سَجَىٰ¦93:3:3:مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ\nT;0;93:4:3:وَلَلۡأٓخِرَةُ خَيۡرࣱ لَّكَ مِنَ ٱلۡأُولَىٰ¦93:5:1:وَلَسَوۡفَ يُعۡطِيكَ رَبُّكَ\nT;0;93:5:2:فَتَرۡضَىٰٓ¦93:6:3:أَلَمۡ يَجِدۡكَ يَتِيمࣰا فَـَٔاوَىٰ¦93:7:3:وَوَجَدَكَ ضَآلࣰّا فَهَدَىٰ\nT;0;93:8:3:وَوَجَدَكَ عَآئِلࣰا فَأَغۡنَىٰ¦93:9:3:فَأَمَّا ٱلۡيَتِيمَ فَلَا تَقۡهَرۡ\nT;2;93:10:3:وَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ¦93:11:3:وَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ\nH;94\nB;94\nT;0;94:1:3:أَلَمۡ نَشۡرَحۡ لَكَ صَدۡرَكَ¦94:2:3:وَوَضَعۡنَا عَنكَ وِزۡرَكَ',
  '30;60;2;\nT;0;94:3:3:ٱلَّذِيٓ أَنقَضَ ظَهۡرَكَ¦94:4:3:وَرَفَعۡنَا لَكَ ذِكۡرَكَ¦94:5:3:فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا\nT;2;94:6:3:إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرࣰا¦94:7:3:فَإِذَا فَرَغۡتَ فَٱنصَبۡ¦94:8:3:وَإِلَىٰ رَبِّكَ فَٱرۡغَب\nH;95\nB;95\nT;0;95:1:3:وَٱلتِّينِ وَٱلزَّيۡتُونِ¦95:2:3:وَطُورِ سِينِينَ¦95:3:3:وَهَٰذَا ٱلۡبَلَدِ ٱلۡأَمِينِ\nT;0;95:4:3:لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمࣲ¦95:5:3:ثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ\nT;0;95:6:3:إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَلَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونࣲ\nT;2;95:7:3:فَمَا يُكَذِّبُكَ بَعۡدُ بِٱلدِّينِ¦95:8:3:أَلَيۡسَ ٱللَّهُ بِأَحۡكَمِ ٱلۡحَٰكِمِينَ\nH;96\nB;96\nT;0;96:1:3:ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ¦96:2:3:خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ¦96:3:1:ٱقۡرَأۡ\nT;0;96:3:2:وَرَبُّكَ ٱلۡأَكۡرَمُ¦96:4:3:ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ¦96:5:1:عَلَّمَ ٱلۡإِنسَٰنَ\nT;0;96:5:2:مَا لَمۡ يَعۡلَمۡ¦96:6:3:كَلَّآ إِنَّ ٱلۡإِنسَٰنَ لَيَطۡغَىٰٓ¦96:7:3:أَن رَّءَاهُ ٱسۡتَغۡنَىٰٓ\nT;0;96:8:3:إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰٓ¦96:9:3:أَرَءَيۡتَ ٱلَّذِي يَنۡهَىٰ¦96:10:1:عَبۡدًا\nT;0;96:10:2:إِذَا صَلَّىٰٓ¦96:11:3:أَرَءَيۡتَ إِن كَانَ عَلَى ٱلۡهُدَىٰٓ¦96:12:3:أَوۡ أَمَرَ بِٱلتَّقۡوَىٰٓ',
  '30;60;2;\nT;0;96:13:3:أَرَءَيۡتَ إِن كَذَّبَ وَتَوَلَّىٰٓ¦96:14:3:أَلَمۡ يَعۡلَم بِأَنَّ ٱللَّهَ يَرَىٰ¦96:15:1:كَلَّا لَئِن لَّمۡ يَنتَهِ\nT;0;96:15:2:لَنَسۡفَعَۢا بِٱلنَّاصِيَةِ¦96:16:3:نَاصِيَةࣲ كَٰذِبَةٍ خَاطِئَةࣲ¦96:17:3:فَلۡيَدۡعُ نَادِيَهُۥ\nT;2;96:18:3:سَنَدۡعُ ٱلزَّبَانِيَةَ¦96:19:3:كَلَّا لَا تُطِعۡهُ وَٱسۡجُدۡۤ وَٱقۡتَرِب۩\nH;97\nB;97\nT;0;97:1:3:إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ¦97:2:3:وَمَآ أَدۡرَىٰكَ مَا لَيۡلَةُ ٱلۡقَدۡرِ\nT;0;97:3:3:لَيۡلَةُ ٱلۡقَدۡرِ خَيۡرࣱ مِّنۡ أَلۡفِ شَهۡرࣲ¦97:4:1:تَنَزَّلُ ٱلۡمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا\nT;2;97:4:2:بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرࣲ¦97:5:3:سَلَٰمٌ هِيَ حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ\nH;98\nB;98\nT;0;98:1:1:لَمۡ يَكُنِ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ مُنفَكِّينَ حَتَّىٰ\nT;0;98:1:2:تَأۡتِيَهُمُ ٱلۡبَيِّنَةُ¦98:2:3:رَسُولࣱ مِّنَ ٱللَّهِ يَتۡلُواْ صُحُفࣰا مُّطَهَّرَةࣰ¦98:3:1:فِيهَا كُتُبࣱ\nT;0;98:3:2:قَيِّمَةࣱ¦98:4:1:وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ\nT;0;98:4:2:ٱلۡبَيِّنَةُ¦98:5:1:وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ\nT;0;98:5:2:حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ',
  '30;60;2;\nT;0;98:6:1:إِنَّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ فِي نَارِ جَهَنَّمَ\nT;0;98:6:2:خَٰلِدِينَ فِيهَآۚ أُوْلَٰٓئِكَ هُمۡ شَرُّ ٱلۡبَرِيَّةِ¦98:7:1:إِنَّ ٱلَّذِينَ ءَامَنُواْ\nT;0;98:7:2:وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ هُمۡ خَيۡرُ ٱلۡبَرِيَّةِ¦98:8:1:جَزَآؤُهُمۡ\nT;0;98:8:0:عِندَ رَبِّهِمۡ جَنَّٰتُ عَدۡنࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ\nT;2;98:8:2:فِيهَآ أَبَدࣰاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ\nH;99\nB;99\nT;0;99:1:3:إِذَا زُلۡزِلَتِ ٱلۡأَرۡضُ زِلۡزَالَهَا¦99:2:3:وَأَخۡرَجَتِ ٱلۡأَرۡضُ أَثۡقَالَهَا¦99:3:1:وَقَالَ\nT;0;99:3:2:ٱلۡإِنسَٰنُ مَا لَهَا¦99:4:3:يَوۡمَئِذࣲ تُحَدِّثُ أَخۡبَارَهَا¦99:5:3:بِأَنَّ رَبَّكَ أَوۡحَىٰ لَهَا\nT;0;99:6:3:يَوۡمَئِذࣲ يَصۡدُرُ ٱلنَّاسُ أَشۡتَاتࣰا لِّيُرَوۡاْ أَعۡمَٰلَهُمۡ¦99:7:1:فَمَن يَعۡمَلۡ\nT;2;99:7:2:مِثۡقَالَ ذَرَّةٍ خَيۡرࣰا يَرَهُۥ¦99:8:3:وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةࣲ شَرࣰّا يَرَهُۥ\nH;100\nB;100\nT;0;100:1:3:وَٱلۡعَٰدِيَٰتِ ضَبۡحࣰا¦100:2:3:فَٱلۡمُورِيَٰتِ قَدۡحࣰا¦100:3:1:فَٱلۡمُغِيرَٰتِ\nT;0;100:3:2:صُبۡحࣰا¦100:4:3:فَأَثَرۡنَ بِهِۦ نَقۡعࣰا¦100:5:3:فَوَسَطۡنَ بِهِۦ جَمۡعًا',
  '30;60;2;240\nT;0;100:6:3:إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودࣱ¦100:7:3:وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدࣱ¦100:8:1:وَإِنَّهُۥ لِحُبِّ\nT;0;100:8:2:ٱلۡخَيۡرِ لَشَدِيدٌ¦100:9:3:۞ أَفَلَا يَعۡلَمُ إِذَا بُعۡثِرَ مَا فِي ٱلۡقُبُورِ\nT;2;100:10:3:وَحُصِّلَ مَا فِي ٱلصُّدُورِ¦100:11:3:إِنَّ رَبَّهُم بِهِمۡ يَوۡمَئِذࣲ لَّخَبِيرُۢ\nH;101\nB;101\nT;0;101:1:3:ٱلۡقَارِعَةُ¦101:2:3:مَا ٱلۡقَارِعَةُ¦101:3:3:وَمَآ أَدۡرَىٰكَ مَا ٱلۡقَارِعَةُ¦101:4:1:يَوۡمَ\nT;0;101:4:2:يَكُونُ ٱلنَّاسُ كَٱلۡفَرَاشِ ٱلۡمَبۡثُوثِ¦101:5:1:وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ\nT;0;101:5:2:ٱلۡمَنفُوشِ¦101:6:3:فَأَمَّا مَن ثَقُلَتۡ مَوَٰزِينُهُۥ¦101:7:1:فَهُوَ فِي عِيشَةࣲ\nT;0;101:7:2:رَّاضِيَةࣲ¦101:8:3:وَأَمَّا مَنۡ خَفَّتۡ مَوَٰزِينُهُۥ¦101:9:3:فَأُمُّهُۥ هَاوِيَةࣱ\nT;2;101:10:3:وَمَآ أَدۡرَىٰكَ مَا هِيَهۡ¦101:11:3:نَارٌ حَامِيَةُۢ\nH;102\nB;102\nT;0;102:1:3:أَلۡهَىٰكُمُ ٱلتَّكَاثُرُ¦102:2:3:حَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ¦102:3:3:كَلَّا سَوۡفَ تَعۡلَمُونَ¦102:4:1:ثُمَّ\nT;0;102:4:2:كَلَّا سَوۡفَ تَعۡلَمُونَ¦102:5:3:كَلَّا لَوۡ تَعۡلَمُونَ عِلۡمَ ٱلۡيَقِينِ¦102:6:3:لَتَرَوُنَّ ٱلۡجَحِيمَ\nT;2;102:7:3:ثُمَّ لَتَرَوُنَّهَا عَيۡنَ ٱلۡيَقِينِ¦102:8:3:ثُمَّ لَتُسۡـَٔلُنَّ يَوۡمَئِذٍ عَنِ ٱلنَّعِيمِ',
  '30;60;3;\nH;103\nB;103\nT;0;103:1:3:وَٱلۡعَصۡرِ¦103:2:3:إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ¦103:3:1:إِلَّا ٱلَّذِينَ ءَامَنُواْ\nT;2;103:3:2:وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ\nH;104\nB;104\nT;0;104:1:3:وَيۡلࣱ لِّكُلِّ هُمَزَةࣲ لُّمَزَةٍ¦104:2:3:ٱلَّذِي جَمَعَ مَالࣰا وَعَدَّدَهُۥ\nT;0;104:3:3:يَحۡسَبُ أَنَّ مَالَهُۥٓ أَخۡلَدَهُۥ¦104:4:3:كَلَّاۖ لَيُنۢبَذَنَّ فِي ٱلۡحُطَمَةِ\nT;0;104:5:3:وَمَآ أَدۡرَىٰكَ مَا ٱلۡحُطَمَةُ¦104:6:3:نَارُ ٱللَّهِ ٱلۡمُوقَدَةُ¦104:7:1:ٱلَّتِي تَطَّلِعُ\nT;2;104:7:2:عَلَى ٱلۡأَفۡـِٔدَةِ¦104:8:3:إِنَّهَا عَلَيۡهِم مُّؤۡصَدَةࣱ¦104:9:3:فِي عَمَدࣲ مُّمَدَّدَةِۭ\nH;105\nB;105\nT;0;105:1:3:أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِأَصۡحَٰبِ ٱلۡفِيلِ¦105:2:1:أَلَمۡ يَجۡعَلۡ\nT;0;105:2:2:كَيۡدَهُمۡ فِي تَضۡلِيلࣲ¦105:3:3:وَأَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا أَبَابِيلَ\nT;2;105:4:3:تَرۡمِيهِم بِحِجَارَةࣲ مِّن سِجِّيلࣲ¦105:5:3:فَجَعَلَهُمۡ كَعَصۡفࣲ مَّأۡكُولِۭ',
